// --- Data Handling & Firebase ---
function fetchMenu() {
    state.isMenuLoading = true;
    renderApp();
    const weekId = getWeekId(new Date(state.selectedDate + 'T12:00:00Z'));
    const menuRef = ref(database, `menus/${weekId}`);
    onValue(menuRef, async (snapshot) => {
        const menuData = snapshot.val();
        if (menuData && menuData.dishes) {
            // Pre-fetch and cache reference images
            const imagePromises = menuData.dishes.map(dish => 
                fetch(`https://corsproxy.io/?${encodeURIComponent(dish.dishImage)}`)
                .then(response => response.blob())
                .then(blob => URL.createObjectURL(blob))
                .then(localUrl => {
                    dish.dishImage = localUrl; // Replace remote URL with local blob URL
                    return dish;
                })
                .catch(err => {
                    console.error(`Failed to pre-fetch image for ${dish.dishName}:`, err);
                    return dish; // Return original dish data on error
                })
            );
            await Promise.all(imagePromises);
        }
        state.menu = menuData || null;
        state.isMenuLoading = false;
        renderApp();
    });
}


function fetchCheckData() {
    state.isCheckDataLoading = true;
    renderApp();
    const checkRef = ref(database, `quality-checks/${state.selectedDate}`);
    onValue(checkRef, (snapshot) => {
        state.checkedData = snapshot.val() || {};
        state.isCheckDataLoading = false;
        // If a dish is selected, re-render it. Otherwise, render the grid.
        if(state.selectedDish) {
          renderDishCard();
        } else {
          renderApp();
        }
    });
}

function saveCheckData(data) {
    const dbRef = ref(database, `quality-checks/${data.date}/${data.dishLetter}`);
    set(dbRef, data).catch(console.error);
}

// --- AI Functions ---
async function handleAiCheck(dish, capturedImageDataUrl) {
    const feedbackContainer = document.getElementById('ai-feedback-container');
    feedbackContainer.innerHTML = `<div class="p-4 border rounded-md bg-gray-700/50"><div class="flex items-center"><svg class="animate-spin -ml-1 mr-3 h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg><p>AI is analyzing the dish, please wait...</p></div></div>`;

    const form = document.getElementById('dish-form');

    try {
        const apiKey = localStorage.getItem('geminiApiKey');
        if (!apiKey) {
            feedbackContainer.innerHTML = `<div class="p-4 border rounded-md bg-yellow-900/30 text-yellow-300"><p><strong>Action Required:</strong> Please set your Gemini API key in Settings.</p></div>`;
            DOMElements.settingsModal.classList.remove('hidden');
            DOMElements.apiKeyInput.focus();
            return;
        }
        const ai = new GoogleGenAI({ apiKey });

        const refImageResponse = await fetch(dish.dishImage);
        const refImageBlob = await refImageResponse.blob();

        const blobToBase64 = (blob) => new Promise((resolve, reject) => {
            const reader = new FileReader();
            reader.onloadend = () => resolve(reader.result.split(',')[1]);
            reader.onerror = reject;
            reader.readAsDataURL(blob);
        });

        const [refImageBase64, capturedImageBase64] = await Promise.all([
            blobToBase64(refImageBlob),
            Promise.resolve(capturedImageDataUrl.split(',')[1])
        ]);

        const ingredientsList = dish.dishIngredients.map(ing => `${ing.name} (${ing.weight})`).join(', ');
        const promptText = `As a culinary quality control expert, analyze the provided "Captured Image" against the "Reference Image" for the dish '${dish.dishName}'.
        The expected ingredients are: ${ingredientsList}.
        Based purely on a visual comparison, provide your analysis.
        Your entire response MUST be a single, valid JSON object with the following structure: { "score": number, "positives": string[], "improvements": string[], "overall_comment": string }.
        The "score" MUST be an integer between 1 and 10.
        Do not include any text, markdown formatting, or code fences (like \`\`\`json) before or after the JSON object. The "improvements" should be actionable suggestions for the chef to match the reference image better.`;

        const refImagePart = { inlineData: { mimeType: 'image/jpeg', data: refImageBase64 } };
        const capturedImagePart = { inlineData: { mimeType: 'image/jpeg', data: capturedImageBase64 } };
        const textPart = { text: promptText };

        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: { parts: [textPart, refImagePart, capturedImagePart] }
        });

        const textResponse = response.text;

        if (!textResponse) {
             if (response.candidates && response.candidates.length > 0) {
                 const candidate = response.candidates[0];
                 if(candidate.finishReason && candidate.finishReason !== 'STOP'){
                     throw new Error(`Request was blocked by API. Reason: ${candidate.finishReason}.`);
                 }
             }
             console.error("Invalid API response structure, no text part:", response);
             throw new Error("AI did not return a text response.");
        }

        let feedbackData;
        try {
            const jsonString = textResponse.trim().replace(/^```json\s*/, '').replace(/\s*```$/, '');
            feedbackData = JSON.parse(jsonString);
        } catch (e) {
            console.error("Failed to parse JSON from AI response:", textResponse);
            throw new Error("AI returned an invalid JSON format.");
        }

        if (form) {
            form.dataset.aiFeedback = JSON.stringify(feedbackData);
        }
        renderAiFeedback(feedbackData);

    } catch (error) {
        console.error("AI Check failed:", error);
        let errorMessage = error.message;
        if (errorMessage.includes('API key not valid')) {
            errorMessage = 'Your API Key is not valid. Please check it in Settings.';
        }
        feedbackContainer.innerHTML = `<div class="p-4 border rounded-md bg-red-900/30 text-red-300"><p><strong>Error:</strong> AI analysis failed.</p><p class="text-xs mt-1">${errorMessage}</p></div>`;
    }
}


function renderAiFeedback(feedbackData) {
    const container = document.getElementById('ai-feedback-container');
    if (!container || !feedbackData) return;

    // Clamp the score to be between 1 and 10, just in case.
    const score = Math.max(1, Math.min(10, feedbackData.score || 0));
    const { positives, improvements, overall_comment } = feedbackData;

    // Determine color and width for the progress bar
    const scorePercentage = (score / 10) * 100;
    let scoreBarColorClass = 'bg-green-500';
    if (score < 5) {
        scoreBarColorClass = 'bg-red-600';
    } else if (score < 8) {
        scoreBarColorClass = 'bg-yellow-500';
    }

    const listItems = (items, icon) => (items || []).map(item => `<li class="flex items-start"><span class="mr-2 pt-0.5">${icon}</span><span>${item}</span></li>`).join('');

    container.innerHTML = `
        <div>
            <h4 class="font-semibold text-gray-200 mb-2">AI Analysis</h4>
            <div class="p-4 border border-gray-700 rounded-md bg-gray-900/50">
                <div>
                    <div class="flex justify-between items-baseline mb-1">
                        <p class="font-bold text-lg text-gray-200">Overall Score</p>
                        <p class="text-2xl font-black text-white">${score}<span class="text-base font-medium text-gray-400">/10</span></p>
                    </div>
                    <div class="w-full bg-gray-700 rounded-full h-2.5">
                        <div class="${scoreBarColorClass} h-2.5 rounded-full" style="width: ${scorePercentage}%"></div>
                    </div>
                </div>

                <p class="text-sm italic text-gray-400 mt-4">"${overall_comment}"</p>

                <div class="mt-4 grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div>
                        <h5 class="font-semibold mb-1 text-green-400">What's Good:</h5>
                        <ul class="space-y-1 text-sm list-none pl-0 text-gray-300">${listItems(positives, '✅')}</ul>
                    </div>
                    <div>
                        <h5 class="font-semibold mb-1 text-yellow-400">Actionable Improvements:</h5>
                        <ul class="space-y-1 text-sm list-none pl-0 text-gray-300">${listItems(improvements, '⚠️')}</ul>
                    </div>
                </div>
            </div>
        </div>
    `;
}

