            <video id="camera-video" autoplay playsinline class="w-full h-full object-cover rounded"></video>
            <button type="button" id="capture-btn" class="w-full bg-indigo-600 text-white text-[10px] py-1 absolute bottom-0 left-0 bg-opacity-70 hover:bg-opacity-100 flex items-center justify-center gap-1 uppercase font-bold tracking-tighter">Capture</button>
