    set(dbRef, data).catch(console.error);
}

// --- AI Functions ---
async function handleAiCheck(dish, capturedImageDataUrl) {
    const feedbackContainer = document.getElementById('ai-feedback-container');
    feedbackContainer.innerHTML = `<div class="p-1 border rounded bg-gray-700/50"><div class="flex items-center text-[10px]"><svg class="animate-spin -ml-0.5 mr-1 h-3 w-3 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg><p>Analyzing...</p></div></div>`;

    const form = document.getElementById('dish-form');

    try {
        const apiKey = localStorage.getItem('geminiApiKey');
        if (!apiKey) {
            feedbackContainer.innerHTML = `<div class="p-1 border rounded bg-yellow-900/30 text-yellow-300 text-[10px]"><p><strong>Action Required:</strong> Set API key in Settings.</p></div>`;
            return;
        }
        const ai = new GoogleGenAI({ apiKey });

        const refImageResponse = await fetch(dish.dishImage);
        const refImageBlob = await refImageResponse.blob();

        const blobToBase64 = (blob) => new Promise((resolve, reject) => {
            const reader = new FileReader();
            reader.onloadend = () => resolve(reader.result.split(',')[1]);
            reader.onerror = reject;
            reader.readAsDataURL(blob);
        });

        const [refImageBase64, capturedImageBase64] = await Promise.all([
            blobToBase64(refImageBlob),
            Promise.resolve(capturedImageDataUrl.split(',')[1])
        ]);

        const ingredientsList = dish.dishIngredients.map(ing => `${ing.name} (${ing.weight})`).join(', ');
        const promptText = `Analyze "Captured Image" against "Reference Image" for '${dish.dishName}'.
        Ingredients: ${ingredientsList}.
        Provide your analysis as a single JSON object: { "score": number(1-10), "positives": string[], "improvements": string[], "overall_comment": string }.
        Actionable improvements only.`;

        const refImagePart = { inlineData: { mimeType: 'image/jpeg', data: refImageBase64 } };
        const capturedImagePart = { inlineData: { mimeType: 'image/jpeg', data: capturedImageBase64 } };
        const textPart = { text: promptText };

        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: { parts: [textPart, refImagePart, capturedImagePart] }
        });

        const textResponse = response.text;

        if (!textResponse) {
             throw new Error("Empty response");
        }

        let feedbackData;
        try {
            const jsonString = textResponse.trim().replace(/^```json\s*/, '').replace(/\s*```$/, '');
            feedbackData = JSON.parse(jsonString);
        } catch (e) {
            throw new Error("Invalid JSON format.");
        }

        if (form) {
            form.dataset.aiFeedback = JSON.stringify(feedbackData);
        }
        renderAiFeedback(feedbackData);

    } catch (error) {
        feedbackContainer.innerHTML = `<div class="p-1 border rounded bg-red-900/30 text-red-300 text-[10px]"><p><strong>Error:</strong> AI analysis failed.</p></div>`;
    }
}


function renderAiFeedback(feedbackData) {
    const container = document.getElementById('ai-feedback-container');
    if (!container || !feedbackData) return;

    const score = Math.max(1, Math.min(10, feedbackData.score || 0));
    const { positives, improvements, overall_comment } = feedbackData;

    const scorePercentage = (score / 10) * 100;
    let scoreBarColorClass = 'bg-green-500';
    if (score < 5) scoreBarColorClass = 'bg-red-600';
    else if (score < 8) scoreBarColorClass = 'bg-yellow-500';

    const listItems = (items, color) => (items || []).map(item => `<li class="flex items-start ${color}"><span class="mr-1">•</span><span>${item}</span></li>`).join('');

    container.innerHTML = `
        <div class="p-1.5 border border-gray-700 rounded bg-gray-900/50 text-[10px]">
            <div class="flex justify-between items-center mb-0.5">
                <p class="font-bold text-gray-200">AI Score: ${score}/10</p>
                <div class="w-16 bg-gray-700 rounded-full h-1.5">
                    <div class="${scoreBarColorClass} h-1.5 rounded-full" style="width: ${scorePercentage}%"></div>
                </div>
            </div>
            <p class="italic text-gray-400 mb-1 leading-tight line-clamp-2">"${overall_comment}"</p>
            <div class="grid grid-cols-2 gap-2">
                <ul class="space-y-0.5 list-none pl-0">${listItems(positives, 'text-green-400')}</ul>
                <ul class="space-y-0.5 list-none pl-0">${listItems(improvements, 'text-yellow-400')}</ul>
            </div>
        </div>
    `;
}

