                <div class="grid grid-cols-2 gap-1">
                    <div class="space-y-0.5">
                        <p class="text-[9px] font-medium text-gray-400 uppercase">Temps</p>
                        ${(formData.temperatures || ['', '', '']).map((t, i) => `<input type="text" inputmode="decimal" data-form-input name="temperatures" value="${t}" placeholder="T${i + 1}" class="block w-full px-1 py-0.5 bg-gray-700 border border-gray-600 rounded text-[10px] text-gray-100">`).join('')}
