function renderDailySummaryTable() {
    if (!state.menu || !state.menu.dishes) return;
    const dishes = state.menu.dishes;
    const cold = dishes.filter(d => d.dishType === 'cold').sort((a,b) => a.dishLetter.localeCompare(b.dishLetter));
    const hot = dishes.filter(d => d.dishType === 'hot').sort((a,b) => a.dishLetter.localeCompare(b.dishLetter));
    const other = dishes.filter(d => d.dishType !== 'cold' && d.dishType !== 'hot').sort((a,b) => a.dishLetter.localeCompare(b.dishLetter));

    let tableHTML = `
        <table class="min-w-full divide-y divide-gray-700 text-[10px]">
            <thead class="bg-gray-900/50">
                <tr>
                    <th scope="col" class="px-1 py-0.5 text-left font-medium text-gray-400 uppercase">Dish</th>
                    <th scope="col" class="px-1 py-0.5 text-left font-medium text-gray-400 uppercase">Name</th>
                    <th scope="col" class="px-1 py-0.5 text-left font-medium text-gray-400 uppercase">AvgT</th>
                    <th scope="col" class="px-1 py-0.5 text-left font-medium text-gray-400 uppercase">Avg/TheoW</th>
                    <th scope="col" class="px-1 py-0.5 text-left font-medium text-gray-400 uppercase">AI</th>
                    <th scope="col" class="px-1 py-0.5 text-left font-medium text-gray-400 uppercase">Comment</th>
                </tr>
            </thead>
            <tbody class="divide-y divide-gray-700">
    `;

    const renderRows = (list, title) => {
        if(list.length === 0) return;
        tableHTML += `<tr class="bg-gray-900/40"><td colspan="6" class="px-1 py-0.5 text-[8px] font-bold text-gray-500 uppercase border-l-2 border-indigo-500">${title}</td></tr>`;
        list.forEach(dish => {
            const check = state.checkedData[dish.dishLetter];
            const isChecked = !!check;

            const validTemps = (check?.temperatures || []).map(t => parseFloat(t)).filter(t => !isNaN(t));
            const avgTemp = validTemps.length > 0 ? (validTemps.reduce((a, b) => a + b, 0) / validTemps.length).toFixed(1) + '°' : '-';

            const validWeights = (check?.weights || []).map(w => parseFloat(w)).filter(w => !isNaN(w));
            const actualAvg = validWeights.length > 0 ? (validWeights.reduce((a, b) => a + b, 0) / validWeights.length) : null;
            const theoW = dish.theoreticalWeight || 0;
            const weightDisplay = actualAvg !== null ? `${actualAvg.toFixed(0)}/${theoW.toFixed(0)}g` : `-/${theoW.toFixed(0)}g`;

            const aiScore = check?.aiCheckResult?.score || '-';
            const userComment = check?.comment || '-';

            tableHTML += `
                <tr class="hover:bg-gray-700/30 cursor-pointer ${!isChecked ? 'opacity-50' : ''}" onclick="window.state.selectedDish = ${JSON.stringify(dish).replace(/"/g, '&quot;')}; showDishDetailView();">
