function handleSaveSettings() {
    const val = DOMElements.jsonInput.value.trim();
    if (DOMElements.apiKeyInput) localStorage.setItem('geminiApiKey', DOMElements.apiKeyInput.value);
    if (!val) { DOMElements.settingsModal.classList.add('hidden'); return; }
    try {
        const p = JSON.parse(val);
        const dishes = p.dishes.filter(d => d.stickerNo && d.stickerNo !== 'addons').map(d => {
            const ingredients = (d.ingredients || []).map(i => ({name: i.name || '?', weight: parseFloat(i.amount) || 0}));
            const theoW = ingredients.reduce((sum, ing) => sum + (ing.weight || 0), 0);
            return {
                dishLetter: d.stickerNo, dishName: d.variantName, dishImage: d.webUrl, dishType: ['hot', 'cold'].includes(d.type) ? d.type : 'unknown',
                dishIngredients: (d.ingredients || []).map(i => ({name: i.name || '?', weight: (i.amount || '0') + 'g'})),
                theoreticalWeight: theoW
            };
        });
        const menuWeekId = getWeekId(new Date(p.startDate + 'T12:00:00Z'));
        set(ref(database, `menus/${menuWeekId}`), { dishes, startDate: p.startDate }).then(() => {
            DOMElements.settingsModal.classList.add('hidden');
            fetchMenu();
        });
    } catch (e) { DOMElements.settingsError.textContent = "Invalid JSON."; }
}

