function renderDishSelectionGrid() {
    DOMElements.dishGridContainer.innerHTML = '';
    if (!state.menu || !state.menu.dishes) return;

    const cold = state.menu.dishes.filter(d => d.dishType === 'cold').sort((a,b) => a.dishLetter.localeCompare(b.dishLetter));
    const hot = state.menu.dishes.filter(d => d.dishType === 'hot').sort((a,b) => a.dishLetter.localeCompare(b.dishLetter));
    const other = state.menu.dishes.filter(d => d.dishType !== 'cold' && d.dishType !== 'hot').sort((a,b) => a.dishLetter.localeCompare(b.dishLetter));

    const themes = {
      hot: { cardBg: 'bg-gray-800', cardBorder: 'border-red-900', circleBg: 'bg-red-900', letterText: 'text-red-300' },
      cold: { cardBg: 'bg-gray-800', cardBorder: 'border-blue-900', circleBg: 'bg-blue-900', letterText: 'text-blue-300' },
      default: { cardBg: 'bg-gray-800', cardBorder: 'border-gray-700', circleBg: 'bg-gray-700', letterText: 'text-indigo-400' }
    };

    const renderBatch = (list, title) => {
        if (list.length === 0) return;
        const h = document.createElement('div');
        h.className = 'col-span-full text-[9px] font-bold text-gray-500 uppercase tracking-tighter border-b border-gray-800 mt-1';
        h.textContent = title;
        DOMElements.dishGridContainer.appendChild(h);

        list.forEach(dish => {
            const isChecked = !!state.checkedData[dish.dishLetter];
            const theme = dish.dishType === 'hot' ? 'hot' : dish.dishType === 'cold' ? 'cold' : 'default';
            const currentTheme = themes[theme];
            const button = document.createElement('button');
            button.className = `relative text-center p-0.5 border rounded shadow-sm hover:shadow-md transition-all duration-200 transform hover:-translate-y-0.5 ${currentTheme.cardBg} ${currentTheme.cardBorder}`;
            button.onclick = () => {
                state.selectedDish = dish;
                showDishDetailView();
            };
            let checkmarkHTML = isChecked ? `<div class="absolute top-0.5 right-0.5 text-green-500"><svg xmlns="http://www.w3.org/2000/svg" class="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg></div>` : '';
            button.innerHTML = `
                ${checkmarkHTML}
                <div class="mx-auto mb-0.5 h-8 w-8 rounded-full flex items-center justify-center text-xs font-black ${currentTheme.circleBg} ${currentTheme.letterText}">${dish.dishLetter}</div>
                <p class="font-semibold text-[8px] truncate text-gray-300 px-0.5">${dish.dishName}</p>
            `;
            DOMElements.dishGridContainer.appendChild(button);
        });
    };

    renderBatch(cold, 'Cold Dishes');
    renderBatch(hot, 'Hot Dishes');
    renderBatch(other, 'Other');
}

function renderDailySummaryTable() {
    if (!state.menu || !state.menu.dishes) return;
    const dishes = state.menu.dishes;
    const cold = dishes.filter(d => d.dishType === 'cold').sort((a,b) => a.dishLetter.localeCompare(b.dishLetter));
    const hot = dishes.filter(d => d.dishType === 'hot').sort((a,b) => a.dishLetter.localeCompare(b.dishLetter));
    const other = dishes.filter(d => d.dishType !== 'cold' && d.dishType !== 'hot').sort((a,b) => a.dishLetter.localeCompare(b.dishLetter));

    let tableHTML = `
        <table class="min-w-full divide-y divide-gray-700 text-[10px]">
            <thead class="bg-gray-900/50">
                <tr>
                    <th scope="col" class="px-1 py-0.5 text-left font-medium text-gray-400 uppercase">Dish</th>
                    <th scope="col" class="px-1 py-0.5 text-left font-medium text-gray-400 uppercase">Name</th>
                    <th scope="col" class="px-1 py-0.5 text-left font-medium text-gray-400 uppercase">AvgT</th>
                    <th scope="col" class="px-1 py-0.5 text-left font-medium text-gray-400 uppercase">Avg/TheoW</th>
                    <th scope="col" class="px-1 py-0.5 text-left font-medium text-gray-400 uppercase">AI</th>
                    <th scope="col" class="px-1 py-0.5 text-left font-medium text-gray-400 uppercase">Comment</th>
                </tr>
            </thead>
            <tbody class="divide-y divide-gray-700">
    `;

    const renderRows = (list, title) => {
        if(list.length === 0) return;
        tableHTML += `<tr class="bg-gray-900/40"><td colspan="6" class="px-1 py-0.5 text-[8px] font-bold text-gray-500 uppercase border-l-2 border-indigo-500">${title}</td></tr>`;
        list.forEach(dish => {
            const check = state.checkedData[dish.dishLetter];
            const isChecked = !!check;

            const validTemps = (check?.temperatures || []).map(t => parseFloat(t)).filter(t => !isNaN(t));
            const avgTemp = validTemps.length > 0 ? (validTemps.reduce((a, b) => a + b, 0) / validTemps.length).toFixed(1) + '°' : '-';

            const validWeights = (check?.weights || []).map(w => parseFloat(w)).filter(w => !isNaN(w));
            const actualAvg = validWeights.length > 0 ? (validWeights.reduce((a, b) => a + b, 0) / validWeights.length) : null;
            const theoW = dish.theoreticalWeight || 0;
            const weightDisplay = actualAvg !== null ? `${actualAvg.toFixed(0)}/${theoW.toFixed(0)}g` : `-/${theoW.toFixed(0)}g`;

            const aiScore = check?.aiCheckResult?.score || '-';
            const userComment = check?.comment || '-';

            tableHTML += `
                <tr class="hover:bg-gray-700/30 cursor-pointer ${!isChecked ? 'opacity-50' : ''}" onclick="window.state.selectedDish = ${JSON.stringify(dish).replace(/"/g, '&quot;')}; showDishDetailView();">
                    <td class="px-1 py-0.5 font-bold text-indigo-400">${dish.dishLetter}</td>
                    <td class="px-1 py-0.5 text-gray-300 truncate max-w-[80px]">${dish.dishName}</td>
                    <td class="px-1 py-0.5 text-gray-300">${avgTemp}</td>
                    <td class="px-1 py-0.5 text-gray-300">${weightDisplay}</td>
                    <td class="px-1 py-0.5 font-bold ${isChecked ? 'text-white' : 'text-gray-500'}">${aiScore}</td>
                    <td class="px-1 py-0.5 text-gray-400 italic truncate max-w-[120px]">${userComment}</td>
                </tr>
            `;
        });
    };

    renderRows(cold, 'Cold');
    renderRows(hot, 'Hot');
    renderRows(other, 'Other');

    tableHTML += `</tbody></table>`;
    DOMElements.dailySummaryContainer.innerHTML = tableHTML;
    window.state = state;
}

