function fetchMenu() {
    state.isMenuLoading = true;
    renderApp();
    const weekId = getWeekId(new Date(state.selectedDate + 'T12:00:00Z'));
    onValue(ref(database, `menus/${weekId}`), (snapshot) => {
        state.menu = snapshot.val() || null;
        state.isMenuLoading = false;
        renderApp();
    });
}

function fetchCheckData() {
    state.isCheckDataLoading = true;
    renderApp();
    onValue(ref(database, `quality-checks/${state.selectedDate}`), (snapshot) => {
        state.checkedData = snapshot.val() || {};
        state.isCheckDataLoading = false;
        if(state.selectedDish) renderDishCard(); else renderApp();
    });
}

function saveCheckData(data) {
    set(ref(database, `quality-checks/${data.date}/${data.dishLetter}`), data).catch(console.error);
}

async function handleAiCheck(dish, capturedImageDataUrl) {
    const feedbackContainer = document.getElementById('ai-feedback-container');
    feedbackContainer.innerHTML = `<div class="p-1 border rounded bg-gray-700/50 flex items-center text-[9px]"><p>Analyzing...</p></div>`;
    try {
        const apiKey = localStorage.getItem('geminiApiKey');
        if (!apiKey) { feedbackContainer.innerHTML = `<p class="text-[9px] text-yellow-500">No API key.</p>`; return; }
        const ai = new GoogleGenAI({ apiKey });
        const refImgBase64 = await fetch(dish.dishImage).then(r => r.blob()).then(b => new Promise(res => { const fr = new FileReader(); fr.onloadend = () => res(fr.result.split(',')[1]); fr.readAsDataURL(b); }));
        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: { parts: [{text: `Analyze image for '${dish.dishName}'. Return JSON: { "score": 1-10, "positives": [], "improvements": [], "overall_comment": "" }.`}, {inlineData: {mimeType: 'image/jpeg', data: refImgBase64}}, {inlineData: {mimeType: 'image/jpeg', data: capturedImageDataUrl.split(',')[1]}}] }
        });
        const feedbackData = JSON.parse(response.text.trim().replace(/^```json\s*/, '').replace(/\s*```$/, ''));
        document.getElementById('dish-form').dataset.aiFeedback = JSON.stringify(feedbackData);
        renderAiFeedback(feedbackData);
    } catch (e) { feedbackContainer.innerHTML = `<p class="text-[9px] text-red-500">AI Error.</p>`; }
}

function renderAiFeedback(feedbackData) {
    const container = document.getElementById('ai-feedback-container');
    if (!container || !feedbackData) return;
    const score = Math.max(1, Math.min(10, feedbackData.score || 0));
    container.innerHTML = `<div class="p-1 border border-gray-700 rounded bg-gray-900/50 text-[9px] flex items-center justify-between"><p class="font-bold text-gray-200">Score: ${score}/10</p><p class="italic text-gray-500 truncate max-w-[70%]">"${feedbackData.overall_comment}"</p></div>`;
}

