    DOMElements.dishCardContainer.innerHTML = `
        <div class="bg-gray-800 rounded shadow-lg overflow-hidden border border-gray-700">
            <div class="p-1 flex justify-between items-center ${headerBgClass}">
                <h3 class="text-xs font-bold text-indigo-400">${dish.dishLetter} - ${dish.dishName}</h3>
                ${timestampHTML}
            </div>
            <form id="dish-form" class="p-1 space-y-1">
                <div class="grid grid-cols-2 gap-1">
                    <div class="text-center">
                        <img src="${dish.dishImage}" class="w-full aspect-square object-cover rounded shadow-sm"/>
                    </div>
                    <div class="text-center" id="camera-container"></div>
                </div>
                <div id="ai-feedback-container"></div>
                <div>
                    <h4 class="text-[9px] font-semibold text-gray-400 uppercase mb-0.5">Ingredients</h4>
                    <div class="grid grid-cols-2 gap-0.5">${ingredientsHTML}</div>
                </div>
                <div class="grid grid-cols-2 gap-1">
                    <div class="space-y-0.5">
                        <p class="text-[9px] font-medium text-gray-400 uppercase">Temps</p>
                        ${(formData.temperatures || ['', '', '']).map((t, i) => `<input type="text" inputmode="decimal" data-form-input name="temperatures" value="${t}" placeholder="T1" class="block w-full px-1 py-0.5 bg-gray-700 border border-gray-600 rounded text-[10px] text-gray-100">`).join('')}
                    </div>
                    <div class="space-y-0.5">
                        <p class="text-[9px] font-medium text-gray-400 uppercase">Weights (Theo: ${dish.theoreticalWeight ? dish.theoreticalWeight.toFixed(0) : '0'}g)</p>
                        ${(formData.weights || ['', '', '']).map((w, i) => `<input type="text" inputmode="decimal" data-form-input name="weights" value="${w}" placeholder="W1" class="block w-full px-1 py-0.5 bg-gray-700 border border-gray-600 rounded text-[10px] text-gray-100">`).join('')}
                    </div>
                </div>
                <div>
                    <h4 class="text-[9px] font-semibold text-gray-400 uppercase mb-0.5">Comment (by you)</h4>
                    <textarea name="comment" rows="2" data-form-input placeholder="Write your observation..." class="block w-full px-1 py-0.5 bg-gray-700 border border-gray-600 rounded text-[10px] text-gray-100">${formData.comment || ''}</textarea>
                </div>
                <div class="pt-1 flex justify-end space-x-1">
                    <button type="button" id="edit-btn" class="px-2 py-0.5 text-[10px] font-medium text-white bg-yellow-600 rounded">Edit</button>
                    <button type="submit" id="submit-btn" class="px-2 py-0.5 text-[10px] font-medium text-white bg-indigo-600 rounded">Submit</button>
