async function handleAiCheck(dish, capturedImageDataUrl) {
    const feedbackContainer = document.getElementById('ai-feedback-container');
    feedbackContainer.innerHTML = `<div class="p-1 border rounded bg-gray-700/50 flex items-center text-[9px]"><p>Analyzing...</p></div>`;
    try {
        const apiKey = process.env.API_KEY;
        const ai = new GoogleGenAI({ apiKey });

        let refImgBase64 = null;
        try {
            const refRes = await fetch(dish.dishImage);
            if (!refRes.ok) throw new Error("Fetch failed");
            const blob = await refRes.blob();
            refImgBase64 = await new Promise(res => { 
                const fr = new FileReader(); 
                fr.onloadend = () => res(fr.result.split(',')[1]); 
                fr.readAsDataURL(blob); 
            });
        } catch (fetchErr) {
            console.warn("Could not fetch reference image due to CORS. Continuing with text analysis only.", fetchErr);
        }

        const promptParts = [
            { text: `Analyze the provided food image for the dish '${dish.dishName}'. 
            Compare it against quality standards. 
            Return strictly a JSON object with this structure: 
            { "score": number (1-10), "positives": string[], "improvements": string[], "overall_comment": string }.` }
        ];

        if (refImgBase64) {
            promptParts.push({ inlineData: { mimeType: 'image/jpeg', data: refImgBase64 } });
            promptParts[0].text += " The first image is the reference/standard image. The second image is the captured dish to check.";
        }

        promptParts.push({ inlineData: { mimeType: 'image/jpeg', data: capturedImageDataUrl.split(',')[1] } });

        const result = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: { parts: promptParts }
        });

        const text = result.text;
        if (!text) throw new Error("Empty AI response");

        const jsonMatch = text.match(/\{[\s\S]*\}/);
        if (!jsonMatch) throw new Error("No JSON in AI response");

        const feedbackData = JSON.parse(jsonMatch[0]);
        document.getElementById('dish-form').dataset.aiFeedback = JSON.stringify(feedbackData);
        renderAiFeedback(feedbackData);
    } catch (e) { 
        console.error("AI Analysis Error:", e);
        feedbackContainer.innerHTML = `<p class="text-[9px] text-red-500">AI Error. Check console for details.</p>`; 
    }
}

function renderAiFeedback(feedbackData) {
    const container = document.getElementById('ai-feedback-container');
    if (!container || !feedbackData) return;
    const score = Math.max(1, Math.min(10, feedbackData.score || 0));
    container.innerHTML = `<div class="p-1 border border-gray-700 rounded bg-gray-900/50 text-[9px] flex items-center justify-between"><p class="font-bold text-gray-200">Score: ${score}/10</p><p class="italic text-gray-500 truncate max-w-[70%]">"${feedbackData.overall_comment}"</p></div>`;
}

