async function handleExportDetails(startDate, endDate) {
    if (!state.menu) return;
    const dateRange = getDatesInRange(startDate, endDate);
    const results = await Promise.all(dateRange.map(d => get(ref(database, `quality-checks/${d}`))));
    const allChecks = [];
    results.forEach(res => { if(res.val()) Object.values(res.val()).forEach(v => allChecks.push(v)); });

    if(allChecks.length === 0) { alert('No data for range.'); return; }

    const meta = [
        ["CULINARY QUALITY CONTROL - DETAILED DISH SCORECARDS"],
        [`Date Range: ${startDate} to ${endDate}`],
        ["Report Generated: " + new Date().toLocaleString()],
        ["Note: Feedback rows are separated for clarity. Please enable 'Wrap Text' in Excel."],
        []
    ];

    const finalAoa = [...meta];

    allChecks.forEach(c => {
        const dish = state.menu.dishes.find(d => d.dishLetter === c.dishLetter) || {};

        finalAoa.push(["DISH QUALITY SCORECARD", `${c.dishLetter} - ${dish.dishName || '?'}`]);
        finalAoa.push(["Date:", c.date, "Check Time:", c.timestamp ? new Date(c.timestamp).toLocaleTimeString() : '']);

        finalAoa.push(["CATEGORY", "VAL 1", "VAL 2", "VAL 3", "TARGET/THEO"]);
        finalAoa.push(["Temperatures (°C)", c.temperatures?.[0] || '', c.temperatures?.[1] || '', c.temperatures?.[2] || '', "N/A"]);
        finalAoa.push(["Weights (g)", c.weights?.[0] || '', c.weights?.[1] || '', c.weights?.[2] || '', dish.theoreticalWeight || 0]);

        finalAoa.push(["AI QUALITY SCORE", (c.aiCheckResult?.score || 'Pending') + " / 10"]);

        finalAoa.push(["AI POSITIVES (Satisfactory)"]);
        const positives = c.aiCheckResult?.positives || [];
        if (positives.length > 0) {
            positives.forEach(p => finalAoa.push(["", "• " + p]));
        } else {
            finalAoa.push(["", "No specific positives recorded"]);
        }

        finalAoa.push(["AI IMPROVEMENTS (Action Required)"]);
        const improvements = c.aiCheckResult?.improvements || [];
        if (improvements.length > 0) {
            improvements.forEach(i => finalAoa.push(["", "• " + i]));
        } else {
            finalAoa.push(["", "No improvements required"]);
        }

        finalAoa.push(["AI OVERALL EVALUATION"]);
        finalAoa.push(["", (c.aiCheckResult?.overall_comment || '-')]);

        finalAoa.push(["USER OBSERVATIONS"]);
        finalAoa.push(["", (c.comment || '-')]);

        finalAoa.push([]);
        finalAoa.push(["=========================================================================================="]);
        finalAoa.push([]);
    });

    const ws = XLSX.utils.aoa_to_sheet(finalAoa);
    ws['!cols'] = [
        { wch: 30 }, 
        { wch: 80 }, 
        { wch: 15 }, 
        { wch: 15 }, 
        { wch: 18 }
    ];

    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Scorecard Details");
    XLSX.writeFile(wb, `QC_Detailed_Scorecard_${startDate}_to_${endDate}.xlsx`);
}

async function handleExportSummary(startDate, endDate) {
    if (!state.menu) return;
    const dateRange = getDatesInRange(startDate, endDate);
    const results = await Promise.all(dateRange.map(d => get(ref(database, `quality-checks/${d}`))));
    const allChecks = [];
    results.forEach(res => { if(res.val()) Object.values(res.val()).forEach(v => allChecks.push(v)); });

    if(allChecks.length === 0) { alert('No data for range.'); return; }

    const meta = [
        ["CULINARY QUALITY CONTROL - SUMMARY REPORT"],
        [`Date Range: ${startDate} to ${endDate}`],
        []
    ];

    const headers = [
        "Date", "Dish", "Name", "Avg Temp (°C)", 
        "Avg Weight (g)", "Theo. Weight (g)", "Accuracy %",
        "AI Score", "User Comment"
    ];

    const rows = allChecks.map(c => {
        const dish = state.menu.dishes.find(d => d.dishLetter === c.dishLetter) || {};
        const vt = (c.temperatures || []).map(t => parseFloat(t)).filter(t => !isNaN(t));
        const avgT = vt.length ? (vt.reduce((a,b)=>a+b,0)/vt.length).toFixed(1) : '-';
        const vw = (c.weights || []).map(w => parseFloat(w)).filter(w => !isNaN(w));
        const avgW = vw.length ? (vw.reduce((a,b)=>a+b,0)/vw.length) : null;
        const theoW = dish.theoreticalWeight || 0;
        const accuracy = (avgW && theoW) ? ((avgW / theoW) * 100).toFixed(1) + '%' : '-';

        return [
            c.date, c.dishLetter, dish.dishName || '?', 
            avgT, avgW ? avgW.toFixed(0) : '-', theoW.toFixed(0), accuracy,
            c.aiCheckResult?.score || '', c.comment || ''
        ];
    });

    const ws = XLSX.utils.aoa_to_sheet([...meta, headers, ...rows]);
    ws['!cols'] = [
        { wch: 12 }, { wch: 10 }, { wch: 30 }, { wch: 15 }, 
        { wch: 15 }, { wch: 15 }, { wch: 15 }, { wch: 10 }, { wch: 50 }
    ];

    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Summary");
    XLSX.writeFile(wb, `QC_Summary_Report_${startDate}_to_${endDate}.xlsx`);
}

