function renderCameraCapture(dish, initialImage) {
    const container = document.getElementById('camera-container');
    container.innerHTML = `
        <p class="text-[8px] uppercase text-gray-500 mb-0.5">Captured Dish</p>
        <div id="camera-placeholder" class="w-full aspect-square rounded bg-gray-700 flex flex-col items-center justify-center text-gray-400 border border-dashed border-gray-600 cursor-pointer">
            <svg xmlns="http://www.w3.org/2000/svg" class="h-6 w-6 mb-1" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z"></path></svg>
            <span class="text-[10px] font-bold uppercase tracking-wider">Tap to Capture</span>
        </div>
        <div id="camera-view" class="w-full aspect-square rounded bg-black hidden relative overflow-hidden">
            <video id="camera-video" autoplay playsinline class="w-full h-full object-cover"></video>
            <button type="button" id="capture-btn" class="absolute bottom-2 left-1/2 -translate-x-1/2 w-10 h-10 rounded-full border-4 border-white bg-indigo-600/50"></button>
        </div>
        <div id="image-preview" class="w-full aspect-square rounded relative hidden group border border-gray-700">
            <img id="preview-img" class="w-full h-full object-cover rounded" />
            <button type="button" id="retake-btn" class="absolute inset-0 bg-black bg-opacity-60 text-white text-[10px] opacity-0 group-hover:opacity-100 transition-opacity font-bold uppercase tracking-widest">Retake Photo</button>
        </div>
    `;
    const videoEl = container.querySelector('#camera-video');
    const form = DOMElements.dishCardContainer.querySelector('#dish-form');
    let stream = null;

    container.querySelector('#camera-placeholder').onclick = async () => {
        if (form.querySelector('input').disabled) return;
        try {
            stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } });
            videoEl.srcObject = stream;
            container.querySelector('#camera-placeholder').classList.add('hidden');
            container.querySelector('#camera-view').classList.remove('hidden');
        } catch (e) { alert("Camera failed: " + e.message); }
    };

    container.querySelector('#capture-btn').onclick = () => {
        const canvas = document.createElement('canvas');
        canvas.width = 640; canvas.height = 640;
        canvas.getContext('2d').drawImage(videoEl, 0, 0, 640, 640);
        const dataUrl = canvas.toDataURL('image/jpeg', 0.85);
        container.querySelector('#preview-img').src = dataUrl;
        form.dataset.capturedImage = dataUrl;
        if (stream) stream.getTracks().forEach(t => t.stop());
        container.querySelector('#camera-view').classList.add('hidden');
        container.querySelector('#image-preview').classList.remove('hidden');
        handleAiCheck(dish, dataUrl);
    };

    container.querySelector('#retake-btn').onclick = () => {
        if (form.querySelector('input').disabled) return;
        container.querySelector('#image-preview').classList.add('hidden');
        container.querySelector('#camera-placeholder').classList.remove('hidden');
    };

    if (initialImage) {
        container.querySelector('#preview-img').src = initialImage;
        form.dataset.capturedImage = initialImage;
        container.querySelector('#camera-placeholder').classList.add('hidden');
        container.querySelector('#image-preview').classList.remove('hidden');
    }
}

