async function handleAiCheck(dish, capturedImageDataUrl) {
    const feedbackContainer = document.getElementById('ai-feedback-container');
    feedbackContainer.innerHTML = `<div class="p-2 border rounded bg-indigo-900/20 border-indigo-700/50 flex flex-col items-center text-[10px]"><div class="animate-spin rounded-full h-4 w-4 border-2 border-indigo-500 border-t-transparent mb-1"></div><p class="font-bold text-indigo-300">AI ANALYZING QUALITY...</p></div>`;

    try {
        const apiKey = process.env.API_KEY;
        const ai = new GoogleGenAI({ apiKey });

        let refImgBase64 = null;
        try {
            const refRes = await fetch(dish.dishImage);
            if (refRes.ok) {
                const blob = await refRes.blob();
                refImgBase64 = await new Promise(res => { 
                    const fr = new FileReader(); 
                    fr.onloadend = () => res(fr.result.split(',')[1]); 
                    fr.readAsDataURL(blob); 
                });
            }
        } catch (e) { console.warn("Reference image issue:", e); }

        const promptText = `Analyze the dish '${dish.dishName}'. 
        Return strictly a JSON object: 
        { "score": number(1-10), "positives": string[], "improvements": string[], "overall_comment": string }`;

        const contentsParts = [ { text: promptText } ];
        if (refImgBase64) contentsParts.push({ inlineData: { mimeType: 'image/jpeg', data: refImgBase64 } });
        contentsParts.push({ inlineData: { mimeType: 'image/jpeg', data: capturedImageDataUrl.split(',')[1] } });

        const result = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: { parts: contentsParts },
            config: { responseMimeType: "application/json" }
        });

        const feedbackData = JSON.parse(result.text);
        document.getElementById('dish-form').dataset.aiFeedback = JSON.stringify(feedbackData);
        renderAiFeedback(feedbackData);
    } catch (e) { 
        console.error("AI Analysis Failed:", e);
        feedbackContainer.innerHTML = `<div class="p-2 border border-red-900/50 bg-red-900/10 rounded text-[9px] text-red-400"><b>AI Error:</b> High-resolution analysis unavailable. Please check manually.</div>`; 
    }
}

function renderAiFeedback(feedbackData) {
    const container = document.getElementById('ai-feedback-container');
    if (!container || !feedbackData) return;

    const score = Math.max(1, Math.min(10, feedbackData.score || 0));
    const positives = (feedbackData.positives || []).map(p => `<li>• ${p}</li>`).join('');
    const improvements = (feedbackData.improvements || []).map(i => `<li>• ${i}</li>`).join('');

    container.innerHTML = `
        <div class="bg-gray-900/50 border border-gray-700 rounded overflow-hidden shadow-sm">
            <div class="p-1.5 flex justify-between items-center bg-gray-800 border-b border-gray-700">
                <span class="text-[9px] font-black uppercase text-indigo-400 tracking-wider">QC Detailed Report</span>
                <span class="text-xs font-black text-white bg-indigo-600 px-2 py-0.5 rounded">${score}/10</span>
            </div>
            <div class="p-2 grid grid-cols-1 sm:grid-cols-2 gap-2 text-[9px]">
                <div class="space-y-1">
                    <p class="font-bold text-green-400 uppercase tracking-tighter">Positives</p>
                    <ul class="text-gray-300 list-none leading-tight">${positives || 'Standard quality met'}</ul>
                </div>
                <div class="space-y-1">
                    <p class="font-bold text-yellow-400 uppercase tracking-tighter">Improvements</p>
                    <ul class="text-gray-300 list-none leading-tight">${improvements || 'No issues detected'}</ul>
                </div>
            </div>
            <div class="px-2 pb-2">
                <p class="text-[9px] italic text-gray-500 leading-tight">"${feedbackData.overall_comment}"</p>
            </div>
        </div>
    `;
}

