async function handleExportDetails(startDate, endDate) {
    if (!state.menu) return;
    const dateRange = getDatesInRange(startDate, endDate);
    const results = await Promise.all(dateRange.map(d => get(ref(database, `quality-checks/${d}`))));
    const allChecks = [];
    results.forEach(res => { if(res.val()) Object.values(res.val()).forEach(v => allChecks.push(v)); });

    if(allChecks.length === 0) { alert('No data for range.'); return; }

    const meta = [
        ["CULINARY QUALITY CONTROL - DETAILED REPORT"],
        [`Report Range: ${startDate} to ${endDate}`],
        ["Generated on: " + new Date().toLocaleString()],
        []
    ];

    const finalAoa = [...meta];

    allChecks.forEach(c => {
        const dish = state.menu.dishes.find(d => d.dishLetter === c.dishLetter) || {};
        finalAoa.push(["DISH QUALITY SCORECARD", `${c.dishLetter} - ${dish.dishName || '?'}`]);
        finalAoa.push(["Date:", c.date, "Timestamp:", c.timestamp || '']);
        finalAoa.push(["METRICS", "Val 1", "Val 2", "Val 3", "Theo Target"]);
        finalAoa.push(["Temperatures (°C)", ...(c.temperatures || ['', '', '']), "N/A"]);
        finalAoa.push(["Weights (g)", ...(c.weights || ['', '', '']), dish.theoreticalWeight || 0]);
        finalAoa.push(["AI SCORE", (c.aiCheckResult?.score || 'N/A') + " / 10"]);

        finalAoa.push(["AI POSITIVES"]);
        (c.aiCheckResult?.positives || []).forEach(p => finalAoa.push(["", "• " + p]));

        finalAoa.push(["AI IMPROVEMENTS"]);
        (c.aiCheckResult?.improvements || []).forEach(i => finalAoa.push(["", "• " + i]));

        finalAoa.push(["AI FEEDBACK", c.aiCheckResult?.overall_comment || '-']);
        finalAoa.push(["USER COMMENT", c.comment || '-']);
        finalAoa.push([]);
        finalAoa.push(["--------------------------------------------------------------------------------"]);
        finalAoa.push([]);
    });

    const ws = XLSX.utils.aoa_to_sheet(finalAoa);
    ws['!cols'] = [{ wch: 25 }, { wch: 80 }, { wch: 15 }, { wch: 15 }, { wch: 15 }];
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Details");
    XLSX.writeFile(wb, `QC_Detailed_Report_${startDate}_${endDate}.xlsx`);
}

async function handleExportSummary(startDate, endDate) {
    if (!state.menu) return;
    const dateRange = getDatesInRange(startDate, endDate);
    const results = await Promise.all(dateRange.map(d => get(ref(database, `quality-checks/${d}`))));
    const allChecks = [];
    results.forEach(res => { if(res.val()) Object.values(res.val()).forEach(v => allChecks.push(v)); });

    if(allChecks.length === 0) { alert('No data for range.'); return; }

    const meta = [ ["QC SUMMARY"], [`${startDate} - ${endDate}`], [] ];
    const headers = [ "Date", "Dish", "Name", "Avg Temp", "Avg Weight", "Target", "Accuracy", "AI Score", "Comment" ];
    const rows = allChecks.map(c => {
        const dish = state.menu.dishes.find(d => d.dishLetter === c.dishLetter) || {};
        const vt = (c.temperatures || []).map(t => parseFloat(t)).filter(t => !isNaN(t));
        const avgT = vt.length ? (vt.reduce((a,b)=>a+b,0)/vt.length).toFixed(1) : '-';
        const vw = (c.weights || []).map(w => parseFloat(w)).filter(w => !isNaN(w));
        const avgW = vw.length ? (vw.reduce((a,b)=>a+b,0)/vw.length) : null;
        const theoW = dish.theoreticalWeight || 0;
        const accuracy = (avgW && theoW) ? ((avgW / theoW) * 100).toFixed(1) + '%' : '-';
        return [ c.date, c.dishLetter, dish.dishName || '?', avgT, avgW ? avgW.toFixed(0) : '-', theoW.toFixed(0), accuracy, c.aiCheckResult?.score || '', c.comment || '' ];
    });

    const ws = XLSX.utils.aoa_to_sheet([...meta, headers, ...rows]);
    ws['!cols'] = [{ wch: 12 }, { wch: 8 }, { wch: 30 }, { wch: 10 }, { wch: 10 }, { wch: 10 }, { wch: 10 }, { wch: 10 }, { wch: 45 }];
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Summary");
    XLSX.writeFile(wb, `QC_Summary_${startDate}_${endDate}.xlsx`);
}

