                    <th scope="col" class="px-1 py-1 text-left font-medium text-gray-400 uppercase">Dish</th>
                    <th scope="col" class="px-1 py-1 text-left font-medium text-gray-400 uppercase hidden sm:table-cell">Name</th>
                    <th scope="col" class="px-1 py-1 text-left font-medium text-gray-400 uppercase">Temp</th>
                    <th scope="col" class="px-1 py-1 text-left font-medium text-gray-400 uppercase">Weight</th>
                    <th scope="col" class="px-1 py-1 text-left font-medium text-gray-400 uppercase hidden sm:table-cell">Target</th>
                    <th scope="col" class="px-1 py-1 text-left font-medium text-gray-400 uppercase">AI</th>
                    <th scope="col" class="px-1 py-1 text-left font-medium text-gray-400 uppercase hidden sm:table-cell">Observation</th>
                </tr>
            </thead>
            <tbody class="divide-y divide-gray-700">
    `;

    dishes.forEach(dish => {
        const check = state.checkedData[dish.dishLetter];
        const isChecked = !!check;
        const validTemps = (check?.temperatures || []).map(t => parseFloat(t)).filter(t => !isNaN(t));
        const avgTemp = validTemps.length > 0 ? (validTemps.reduce((a, b) => a + b, 0) / validTemps.length).toFixed(1) + '°' : '-';
        const validWeights = (check?.weights || []).map(w => parseFloat(w)).filter(w => !isNaN(w));
        const actualAvg = validWeights.length > 0 ? (validWeights.reduce((a, b) => a + b, 0) / validWeights.length) : null;

        const weightDisplay = actualAvg !== null ? `${actualAvg.toFixed(0)}g` : '-';
        const theoWeight = dish.theoreticalWeight ? `${dish.theoreticalWeight.toFixed(0)}g` : '-';

        const aiScore = check?.aiCheckResult?.score || '-';
        const userComment = check?.comment || '-';

        tableHTML += `
            <tr class="hover:bg-gray-700/30 cursor-pointer ${!isChecked ? 'opacity-40' : ''}" onclick="window.state.selectedDish = ${JSON.stringify(dish).replace(/"/g, '&quot;')}; showDishDetailView();">
                <td class="px-1 py-1 font-bold text-indigo-400">${dish.dishLetter}</td>
                <td class="px-1 py-1 text-gray-300 hidden sm:table-cell truncate max-w-[150px]">${dish.dishName}</td>
                <td class="px-1 py-1 text-gray-300">${avgTemp}</td>
                <td class="px-1 py-1 text-gray-300">${weightDisplay}</td>
                <td class="px-1 py-1 text-gray-500 hidden sm:table-cell italic">${theoWeight}</td>
                <td class="px-1 py-1 font-bold ${isChecked ? 'text-white' : 'text-gray-500'}">${aiScore}</td>
                <td class="px-1 py-1 text-gray-400 italic truncate max-w-[120px] hidden sm:table-cell">${userComment}</td>
            </tr>
        `;
    });

    tableHTML += `</tbody></table>`;
    DOMElements.dailySummaryContainer.innerHTML = tableHTML;
    window.state = state;
}

