                <div class="grid grid-cols-2 gap-1.5">
                    <div class="space-y-1">
                        <p class="text-[9px] font-medium text-gray-400 uppercase">Temps (°C)</p>
                        ${(formData.temperatures || ['', '', '']).map((t, i) => `<input type="text" inputmode="decimal" name="temperatures" value="${t}" placeholder="T${i + 1}" class="block w-full px-2 py-1 bg-gray-700 border border-gray-600 rounded text-[10px] text-gray-100 focus:border-indigo-500 outline-none">`).join('')}
                    </div>
                    <div class="space-y-1">
                        <p class="text-[9px] font-medium text-gray-400 uppercase">Weights (Target: ${dish.theoreticalWeight ? dish.theoreticalWeight.toFixed(0) : '0'}g)</p>
                        ${(formData.weights || ['', '', '']).map((w, i) => `<input type="text" inputmode="decimal" name="weights" value="${w}" placeholder="W${i + 1}" class="block w-full px-2 py-1 bg-gray-700 border border-gray-600 rounded text-[10px] text-gray-100 focus:border-indigo-500 outline-none">`).join('')}
