async function runDishAudit() {
    const letter = DOMElements.auditDishSelect.value;
    if (!letter) return;

    DOMElements.auditResultsContainer.innerHTML = `
        <div class="flex flex-col items-center justify-center py-12 space-y-4">
            <div class="animate-spin rounded-full h-10 w-10 border-4 border-indigo-500 border-t-transparent"></div>
            <p class="text-[10px] font-black text-indigo-400 uppercase tracking-[0.2em] animate-pulse">Aggregating History...</p>
        </div>
    `;

    try {
        // Fetch all quality checks for all time (Scan root of quality-checks)
        const snapshot = await get(ref(database, 'quality-checks'));
        const allData = snapshot.val() || {};
        const historicalChecks = [];

        Object.keys(allData).forEach(date => {
            if (allData[date][letter]) {
                historicalChecks.push({ date, ...allData[date][letter] });
            }
        });

        if (historicalChecks.length === 0) {
            DOMElements.auditResultsContainer.innerHTML = `<div class="p-6 bg-gray-800 border border-yellow-900/30 rounded-xl text-center"><p class="text-xs text-yellow-400 font-bold">No historical data found for this dish yet.</p></div>`;
            return;
        }

        const dish = state.menu.dishes.find(d => d.dishLetter === letter);
        const feedbackSummaries = historicalChecks.map(c => `[${c.date} Score:${c.aiCheckResult?.score || '?'}] Positives: ${c.aiCheckResult?.positives?.join(', ')} | Improvements: ${c.aiCheckResult?.improvements?.join(', ')} | User: ${c.comment}`).join('\n');

        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: `Audit the historical consistency of dish '${dish.dishName}'. 
            Here are past AI results:
            ${feedbackSummaries}

            Return strictly a JSON object:
            { "consistency_score": 1-10, "recurring_patterns": string[], "progress_observation": string, "action_items": string[] }`,
            config: { responseMimeType: "application/json" }
        });

        const audit = JSON.parse(response.text);
        renderAuditReport(audit, historicalChecks);

    } catch (e) {
        console.error(e);
        DOMElements.auditResultsContainer.innerHTML = `<div class="p-6 bg-red-900/10 border border-red-900/30 rounded-xl"><p class="text-xs text-red-400 font-bold">Audit Agent Failed: ${e.message}</p></div>`;
    }
}

function renderAuditReport(audit, history) {
    const scoreColor = audit.consistency_score > 7 ? 'text-green-400' : audit.consistency_score > 4 ? 'text-yellow-400' : 'text-red-400';

    let html = `
        <div class="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div class="bg-gray-800 rounded-xl p-4 border border-gray-700 shadow-sm flex flex-col items-center justify-center">
                <p class="text-[9px] font-black text-gray-500 uppercase tracking-widest mb-1">Consistency Index</p>
                <div class="text-4xl font-black ${scoreColor}">${audit.consistency_score}<span class="text-lg text-gray-600">/10</span></div>
                <p class="text-[10px] text-gray-400 mt-2 font-bold">${history.length} Logs Analyzed</p>
            </div>
            <div class="md:col-span-2 bg-gray-800 rounded-xl p-4 border border-gray-700 shadow-sm">
                <p class="text-[9px] font-black text-gray-500 uppercase tracking-widest mb-2">Trend Intelligence</p>
                <p class="text-xs text-gray-300 italic leading-relaxed">"${audit.progress_observation}"</p>
            </div>
        </div>

        <div class="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div class="bg-gray-800 rounded-xl p-4 border border-gray-700">
                <p class="text-[9px] font-black text-indigo-400 uppercase tracking-widest mb-2">Recurring Patterns</p>
                <ul class="space-y-1.5">
                    ${audit.recurring_patterns.map(p => `<li class="text-[11px] text-gray-300 flex items-start gap-2"><span class="text-indigo-500 mt-1">•</span> ${p}</li>`).join('')}
                </ul>
            </div>
            <div class="bg-gray-800 rounded-xl p-4 border border-gray-700">
                <p class="text-[9px] font-black text-green-400 uppercase tracking-widest mb-2">Correction Strategy</p>
                <ul class="space-y-1.5">
                    ${audit.action_items.map(a => `<li class="text-[11px] text-gray-300 flex items-start gap-2"><span class="text-green-500 mt-1">✓</span> ${a}</li>`).join('')}
                </ul>
            </div>
        </div>
    `;
    DOMElements.auditResultsContainer.innerHTML = html;
}

