function renderCameraCapture(dish, initialImage) {
    const container = document.getElementById('camera-container');
    container.innerHTML = `
        <p class="text-[8px] font-black text-gray-500 uppercase tracking-widest mb-1.5 text-center">Live Capture</p>
        <div id="camera-placeholder" class="w-full aspect-square rounded-lg bg-gray-900 border-2 border-dashed border-gray-700 flex flex-col items-center justify-center text-gray-600 cursor-pointer hover:border-indigo-500 hover:text-indigo-500 transition-all">
            <svg xmlns="http://www.w3.org/2000/svg" class="h-10 w-10 mb-2" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z"></path></svg>
            <span class="text-[10px] font-black uppercase tracking-widest">TAP TO ACTIVATE</span>
        </div>
        <div id="camera-view" class="w-full aspect-square rounded-lg bg-black hidden relative overflow-hidden ring-1 ring-white/10 shadow-inner">
            <video id="camera-video" autoplay playsinline class="w-full h-full object-cover"></video>
            <button type="button" id="capture-btn" class="absolute bottom-4 left-1/2 -translate-x-1/2 w-14 h-14 rounded-full border-4 border-white bg-indigo-600/50 shadow-2xl active:scale-90 transition-transform"></button>
        </div>
        <div id="image-preview" class="w-full aspect-square rounded-lg relative hidden group border border-gray-700 overflow-hidden shadow-lg">
            <img id="preview-img" class="w-full h-full object-cover" />
            <button type="button" id="retake-btn" class="absolute inset-0 bg-black/70 text-white text-xs opacity-0 group-hover:opacity-100 transition-opacity font-black uppercase tracking-widest">Replace Photo</button>
        </div>
    `;
    const videoEl = container.querySelector('#camera-video');
    const form = DOMElements.dishCardContainer.querySelector('#dish-form');
    let stream = null;

    container.querySelector('#camera-placeholder').onclick = async () => {
        if (form.querySelector('input').disabled) return;
        try {
            stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } });
            videoEl.srcObject = stream;
            container.querySelector('#camera-placeholder').classList.add('hidden');
            container.querySelector('#camera-view').classList.remove('hidden');
        } catch (e) { alert("Camera failed: " + e.message); }
    };

    container.querySelector('#capture-btn').onclick = () => {
        const canvas = document.createElement('canvas');
        canvas.width = 640; canvas.height = 640;
        canvas.getContext('2d').drawImage(videoEl, 0, 0, 640, 640);
        const dataUrl = canvas.toDataURL('image/jpeg', 0.85);
        container.querySelector('#preview-img').src = dataUrl;
        form.dataset.capturedImage = dataUrl;
        if (stream) stream.getTracks().forEach(t => t.stop());
        container.querySelector('#camera-view').classList.add('hidden');
        container.querySelector('#image-preview').classList.remove('hidden');
        handleAiCheck(dish, dataUrl);
    };

    container.querySelector('#retake-btn').onclick = () => {
        if (form.querySelector('input').disabled) return;
        container.querySelector('#image-preview').classList.add('hidden');
        container.querySelector('#camera-placeholder').classList.remove('hidden');
    };

    if (initialImage) {
        container.querySelector('#preview-img').src = initialImage;
        form.dataset.capturedImage = initialImage;
        container.querySelector('#camera-placeholder').classList.add('hidden');
        container.querySelector('#image-preview').classList.remove('hidden');
    }
}

async function handleAiCheck(dish, capturedImageDataUrl) {
    const feedbackContainer = document.getElementById('ai-feedback-container');
    feedbackContainer.innerHTML = `
        <div class="p-4 border rounded-xl bg-indigo-900/10 border-indigo-700/30 flex flex-col items-center justify-center space-y-2">
            <div class="animate-spin rounded-full h-5 w-5 border-2 border-indigo-500 border-t-transparent"></div>
            <p class="font-black text-indigo-400 text-[9px] uppercase tracking-widest animate-pulse">Running Neural Audit...</p>
        </div>`;

    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

        let refImgPart = null;
        try {
            const refRes = await fetch(dish.dishImage);
            if (refRes.ok) {
                const blob = await refRes.blob();
                const refBase64 = await new Promise(res => { 
                    const fr = new FileReader(); 
                    fr.onloadend = () => res(fr.result.split(',')[1]); 
                    fr.readAsDataURL(blob); 
                });
                refImgPart = { inlineData: { mimeType: 'image/jpeg', data: refBase64 } };
            }
        } catch (e) { console.warn("Reference image issue:", e); }

        const promptText = `Analyze dish '${dish.dishName}'. 
        Return strictly JSON: 
        { "score": 1-10, "positives": string[], "improvements": string[], "overall_comment": string }`;

        const contentsParts = [ { text: promptText } ];
        if (refImgPart) contentsParts.push(refImgPart);
        contentsParts.push({ inlineData: { mimeType: 'image/jpeg', data: capturedImageDataUrl.split(',')[1] } });

        const result = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: { parts: contentsParts },
            config: { responseMimeType: "application/json" }
        });

        const feedbackData = JSON.parse(result.text);
        document.getElementById('dish-form').dataset.aiFeedback = JSON.stringify(feedbackData);
        renderAiFeedback(feedbackData);
    } catch (e) { 
        console.error(e);
        feedbackContainer.innerHTML = `<div class="p-3 border border-red-900/30 bg-red-900/10 rounded-lg text-[10px] text-red-400 font-bold uppercase">AI Service Interrupted — Proceed Manually</div>`; 
    }
}

function renderAiFeedback(feedbackData) {
    const container = document.getElementById('ai-feedback-container');
    if (!container || !feedbackData) return;

    const score = Math.max(1, Math.min(10, feedbackData.score || 0));
    const positives = (feedbackData.positives || []).map(p => `<li class="flex items-center gap-1.5"><span class="text-green-500">•</span>${p}</li>`).join('');
    const improvements = (feedbackData.improvements || []).map(i => `<li class="flex items-center gap-1.5"><span class="text-yellow-500">•</span>${i}</li>`).join('');

    container.innerHTML = `
        <div class="bg-gray-900/50 border border-gray-700 rounded-xl overflow-hidden shadow-lg ring-1 ring-white/5">
            <div class="px-3 py-2 flex justify-between items-center bg-gray-800 border-b border-gray-700">
                <span class="text-[9px] font-black uppercase text-indigo-400 tracking-widest">AI Audit Report</span>
                <span class="text-xs font-black text-white bg-indigo-600 px-2.5 py-1 rounded-md shadow-lg shadow-indigo-600/30">${score}/10</span>
            </div>
            <div class="p-3 grid grid-cols-1 sm:grid-cols-2 gap-3 text-[10px]">
                <div class="space-y-1.5">
                    <p class="font-black text-green-400 uppercase tracking-tighter">Positives</p>
                    <ul class="text-gray-300 list-none leading-snug space-y-0.5">${positives || 'Standard met'}</ul>
                </div>
                <div class="space-y-1.5">
                    <p class="font-black text-yellow-400 uppercase tracking-tighter">Improvements</p>
                    <ul class="text-gray-300 list-none leading-snug space-y-0.5">${improvements || 'No issues detected'}</ul>
                </div>
            </div>
            <div class="px-3 pb-3">
                <p class="text-[10px] italic text-gray-500 leading-tight border-t border-gray-700 pt-2 font-medium">"${feedbackData.overall_comment}"</p>
            </div>
        </div>
    `;
}

