function populateAuditDropdown() {
    if (!state.menu || !state.menu.dishes) return;
    // Audit based on DISH NAME only
    const distinctNames = [...new Set(state.menu.dishes.map(d => d.dishName))].sort();
    DOMElements.auditDishSelect.innerHTML = '<option value="">Select a dish to audit...</option>';
    distinctNames.forEach(name => {
        const opt = document.createElement('option');
        opt.value = name;
        opt.textContent = name;
        DOMElements.auditDishSelect.appendChild(opt);
