async function runDishAudit() {
    const dishName = DOMElements.auditDishSelect.value;
    if (!dishName) return;

    DOMElements.auditResultsContainer.innerHTML = `
        <div class="flex flex-col items-center justify-center py-16 space-y-6">
            <div class="relative">
                <div class="animate-spin rounded-full h-16 w-16 border-4 border-indigo-500/20 border-t-indigo-500"></div>
                <div class="absolute inset-0 flex items-center justify-center">
                    <div class="h-8 w-8 bg-indigo-500/10 rounded-full animate-pulse"></div>
                </div>
            </div>
            <div class="text-center">
                <p class="text-[10px] font-black text-indigo-400 uppercase tracking-[0.3em] animate-pulse mb-1">Deep Scan in Progress</p>
                <p class="text-[8px] text-gray-500 font-bold uppercase tracking-widest">Cross-referencing historical benchmarks for "${dishName}"</p>
            </div>
        </div>
    `;

    try {
        const snapshot = await get(ref(database, 'quality-checks'));
        const allData = snapshot.val() || {};
        const historicalChecks = [];

        // Match by dishName across all records
        Object.keys(allData).forEach(date => {
            Object.values(allData[date]).forEach(check => {
                if (check.dishName === dishName) {
                    historicalChecks.push({ date, ...check });
                }
            });
        });

        if (historicalChecks.length === 0) {
            DOMElements.auditResultsContainer.innerHTML = `<div class="p-8 bg-gray-800 border border-yellow-900/30 rounded-2xl text-center"><p class="text-xs text-yellow-400 font-bold uppercase tracking-widest">No historical logs found for "${dishName}".</p></div>`;
            return;
        }

        const feedbackSummaries = historicalChecks.map(c => 
            `[Log: ${c.date}] Quality Score: ${c.aiCheckResult?.score || 'N/A'}. 
             Observations: ${c.aiCheckResult?.positives?.join(', ')} / ${c.aiCheckResult?.improvements?.join(', ')}.
             Chef's Note: ${c.comment}`
        ).join('\n');

        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: `As an executive culinary auditor, analyze the historical consistency and quality trajectory for the dish "${dishName}". 
            Ignore dish letters/IDs, focus entirely on the culinary quality described in these logs:

            ${feedbackSummaries}

            Produce a strictly formatted JSON report for a Michelin-starred operations team.
            Output JSON structure:
            {
              "stability_rating": 1-10,
              "trend_narrative": "Detailed executive summary of quality changes over time.",
              "critical_deficiencies": ["List of recurring issues"],
              "best_practices": ["What is consistently executed well"],
              "operational_directives": ["High-impact steps to improve score"],
              "score_trajectory": [number, number, ...] 
            }`,
            config: { 
                responseMimeType: "application/json",
                temperature: 0.2 // Lower temperature for more analytical consistency
            }
        });

        const audit = JSON.parse(response.text);
        renderAuditReport(audit, historicalChecks, dishName);

    } catch (e) {
        console.error(e);
        DOMElements.auditResultsContainer.innerHTML = `<div class="p-6 bg-red-900/10 border border-red-900/30 rounded-xl"><p class="text-xs text-red-400 font-bold">Audit Agent Failed: ${e.message}</p></div>`;
    }
}

