                <div class="bg-gray-900/50 p-3 rounded-lg border border-gray-700">
                    <h4 class="text-[9px] font-black text-gray-500 uppercase tracking-widest mb-2">Observation Checklist</h4>
                    <div class="grid grid-cols-2 gap-2">
                        ${(dish.dishIngredients || []).map(ing => `
                            <label class="flex items-center space-x-2 text-[10px] p-1.5 rounded bg-gray-800 border border-gray-700 cursor-pointer hover:border-indigo-500 transition-colors">
                                <input type="checkbox" name="selectedIngredients" value="${ing.name}" class="h-3 w-3 text-indigo-500 bg-gray-700 border-gray-600 rounded" ${(formData.selectedIngredients || []).includes(ing.name) ? 'checked' : ''}>
