        </div>
    `;

    try {
        const snapshot = await get(ref(database, 'quality-checks'));
        const allData = snapshot.val() || {};

        // Extract all unique dishes ever seen
        const dishMap = new Map();
        Object.keys(allData).forEach(date => {
            Object.values(allData[date]).forEach(check => {
                if (check.dishName) {
                    const key = check.dishName;
                    if (!dishMap.has(key)) {
                        dishMap.set(key, { 
                            name: check.dishName, 
                            type: check.dishType || 'extras',
                            count: 1
                        });
                    } else {
                        dishMap.get(key).count++;
                    }
                }
            });
        });

        const allDishes = Array.from(dishMap.values());
        if (allDishes.length === 0) {
            DOMElements.auditResultsContainer.innerHTML = `<div class="p-12 text-center bg-gray-800/50 rounded-2xl border border-dashed border-gray-700"><p class="text-xs text-gray-500">No historical data available for audit yet.</p></div>`;
