                            </button>
                        `).join('')}
                    </div>
                </div>
            `;
        };

        html += renderSection(hot, 'Hot Selections Library', 'text-red-400');
        html += renderSection(cold, 'Cold Selections Library', 'text-blue-400');
        html += renderSection(extras, 'Other / Extras Library', 'text-gray-400');
