function renderDailySummaryTable() {
    if (!state.menu || !state.menu.dishes) return;
    const dishes = state.menu.dishes;
    DOMElements.dailySummaryContainer.innerHTML = '';

    const types = ['cold', 'hot', 'extras'];
    const groups = {
        cold: dishes.filter(d => d.dishType === 'cold').sort((a,b) => a.dishLetter.localeCompare(b.dishLetter)),
        hot: dishes.filter(d => d.dishType === 'hot').sort((a,b) => a.dishLetter.localeCompare(b.dishLetter)),
        extras: dishes.filter(d => d.dishType !== 'cold' && d.dishType !== 'hot').sort((a,b) => a.dishLetter.localeCompare(b.dishLetter))
    };

    types.forEach(type => {
        const list = groups[type];
        if (list.length === 0) return;

        const wrapper = document.createElement('div');
        wrapper.className = 'bg-gray-800 rounded-lg border border-gray-700 overflow-hidden shadow-sm';

        const header = document.createElement('div');
        header.className = `px-2 py-1 text-[9px] font-black uppercase tracking-widest text-white ${type === 'hot' ? 'bg-red-900/40' : type === 'cold' ? 'bg-blue-900/40' : 'bg-gray-700/40'}`;
        header.textContent = `${type} DISHES`;
        wrapper.appendChild(header);

        let tableHTML = `
            <div class="overflow-x-auto">
                <table class="min-w-full divide-y divide-gray-700 text-[10px]">
                    <thead class="bg-gray-900/50">
                        <tr>
                            <th scope="col" class="px-2 py-1.5 text-left font-bold text-gray-400 uppercase">ID</th>
                            <th scope="col" class="px-2 py-1.5 text-left font-bold text-gray-400 uppercase hidden sm:table-cell">Dish Name</th>
                            <th scope="col" class="px-2 py-1.5 text-left font-bold text-gray-400 uppercase">Temp</th>
                            <th scope="col" class="px-2 py-1.5 text-left font-bold text-gray-400 uppercase">Weight</th>
                            <th scope="col" class="px-2 py-1.5 text-left font-bold text-gray-400 uppercase hidden sm:table-cell">Target</th>
                            <th scope="col" class="px-2 py-1.5 text-left font-bold text-gray-400 uppercase">AI</th>
                            <th scope="col" class="px-2 py-1.5 text-left font-bold text-gray-400 uppercase hidden sm:table-cell">User Comments</th>
                        </tr>
                    </thead>
                    <tbody class="divide-y divide-gray-700">
        `;

        list.forEach(dish => {
            const check = state.checkedData[dish.dishLetter];
            const isChecked = !!check;
            const vt = (check?.temperatures || []).map(t => parseFloat(t)).filter(t => !isNaN(t));
            const avgT = vt.length ? (vt.reduce((a,b)=>a+b,0)/vt.length).toFixed(1) + '°' : '-';
            const vw = (check?.weights || []).map(w => parseFloat(w)).filter(w => !isNaN(w));
            const avgW = vw.length ? (vw.reduce((a,b)=>a+b,0)/vw.length).toFixed(0) + 'g' : '-';
            const ai = check?.aiCheckResult?.score || '-';
            const comment = check?.comment || '-';
            const target = dish.theoreticalWeight ? `${dish.theoreticalWeight.toFixed(0)}g` : '-';

            tableHTML += `
                <tr class="hover:bg-gray-700/30 cursor-pointer ${!isChecked ? 'opacity-30' : ''}" onclick="window.handleSelectDish('${dish.dishLetter}')">
                    <td class="px-2 py-1.5 font-black text-indigo-400">${dish.dishLetter}</td>
                    <td class="px-2 py-1.5 text-gray-200 hidden sm:table-cell truncate max-w-[150px] font-medium">${dish.dishName}</td>
                    <td class="px-2 py-1.5 text-gray-300 font-mono">${avgT}</td>
                    <td class="px-2 py-1.5 text-gray-300 font-mono">${avgW}</td>
                    <td class="px-2 py-1.5 text-gray-500 hidden sm:table-cell italic font-mono">${target}</td>
                    <td class="px-2 py-1.5 font-black ${isChecked ? 'text-white' : 'text-gray-500'}">${ai}</td>
                    <td class="px-2 py-1.5 text-gray-400 italic truncate max-w-[120px] hidden sm:table-cell">${comment}</td>
                </tr>
            `;
        });

        tableHTML += `</tbody></table></div>`;
        wrapper.innerHTML += tableHTML;
        DOMElements.dailySummaryContainer.appendChild(wrapper);
    });
}

