// --- Core Logic ---

function renderApp() {
    DOMElements.loadingIndicator.classList.toggle('hidden', !state.isMenuLoading && !state.isCheckDataLoading);
    DOMElements.mainView.classList.toggle('hidden', state.isMenuLoading || state.isCheckDataLoading || state.currentView !== 'dashboard');

    if (state.menu && state.menu.dishes.length > 0) {
        DOMElements.welcomePlaceholder.classList.add('hidden');
        DOMElements.dishGridContainer.classList.remove('hidden');
        DOMElements.dailySummarySection.classList.remove('hidden');
        renderDishSelectionGrid();
        renderDailySummaryTable();
    } else {
        renderWelcomePlaceholder();
        DOMElements.dailySummarySection.classList.add('hidden');
    }
    renderDateSelector();
}

function renderDateSelector() {
    const viewDate = getStartOfWeek(new Date(state.selectedDate + 'T12:00:00Z'));
    const weekDays = Array.from({ length: 5 }).map((_, i) => {
        const day = new Date(viewDate);
        day.setDate(viewDate.getDate() + i);
        return day;
    });
    DOMElements.dateButtonsContainer.innerHTML = '';
    weekDays.forEach(day => {
        const dayString = day.toISOString().split('T')[0];
        const isSelected = dayString === state.selectedDate;
        const button = document.createElement('button');
        button.className = `flex flex-col items-center justify-center w-9 h-12 sm:w-12 sm:h-14 rounded-2xl transition-all duration-300 transform active:scale-90 ${isSelected ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-600/30 ring-2 ring-indigo-400/20' : 'bg-slate-800 text-slate-500 hover:text-slate-300 border border-slate-700/50'}`;
        button.innerHTML = `
            <span class="text-[8px] uppercase font-black tracking-tighter">${day.toLocaleDateString('en-US', { weekday: 'short' })}</span>
            <span class="text-sm font-black">${day.getDate()}</span>
        `;
        button.onclick = () => {
            state.selectedDate = dayString;
            fetchCheckData();
        };
        DOMElements.dateButtonsContainer.appendChild(button);
    });
}

function renderDishSelectionGrid() {
    DOMElements.dishGridContainer.innerHTML = '';
    if (!state.menu || !state.menu.dishes) return;

    const groups = {
        cold: state.menu.dishes.filter(d => d.dishType === 'cold').sort((a,b) => a.dishLetter.localeCompare(b.dishLetter)),
        hot: state.menu.dishes.filter(d => d.dishType === 'hot').sort((a,b) => a.dishLetter.localeCompare(b.dishLetter)),
        extras: state.menu.dishes.filter(d => d.dishType !== 'cold' && d.dishType !== 'hot').sort((a,b) => a.dishLetter.localeCompare(b.dishLetter))
    };

    const themes = {
      hot: { cardBg: 'bg-slate-800/40', cardBorder: 'border-red-900/40', circleBg: 'bg-red-500', letterText: 'text-white' },
      cold: { cardBg: 'bg-slate-800/40', cardBorder: 'border-blue-900/40', circleBg: 'bg-blue-500', letterText: 'text-white' },
      default: { cardBg: 'bg-slate-800/40', cardBorder: 'border-slate-700/40', circleBg: 'bg-indigo-600', letterText: 'text-white' }
    };

    Object.keys(groups).forEach(type => {
        const list = groups[type];
        if (list.length === 0) return;

        const h = document.createElement('div');
        h.className = 'col-span-full text-[9px] font-black text-slate-500 uppercase tracking-[0.2em] mt-2 mb-1 pl-1';
        h.textContent = `${type} Station`;
        DOMElements.dishGridContainer.appendChild(h);

        list.forEach(dish => {
            const isChecked = !!state.checkedData[dish.dishLetter];
            const theme = themes[dish.dishType] || themes.default;
            const button = document.createElement('button');
            button.className = `group relative flex flex-col items-center justify-center p-2.5 border rounded-2xl transition-all duration-300 ${theme.cardBg} ${theme.cardBorder} hover:scale-105 active:scale-95 shadow-lg`;
            button.onclick = () => {
                state.selectedDish = dish;
                showView('detail');
                renderDishCard();
            };
            let checkHTML = isChecked ? `<div class="absolute -top-1 -right-1 bg-green-500 rounded-full p-1 text-white shadow-xl ring-2 ring-slate-900 scale-100 group-hover:scale-110 transition-transform"><svg xmlns="http://www.w3.org/2000/svg" class="h-2.5 w-2.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="3" d="M5 13l4 4L19 7"></path></svg></div>` : '';
            button.innerHTML = `
                ${checkHTML}
                <div class="mb-2 h-10 w-10 sm:h-11 sm:w-11 rounded-full flex items-center justify-center text-xs sm:text-sm font-black shadow-inner ring-2 ring-white/10 ${theme.circleBg} ${theme.letterText}">${dish.dishLetter}</div>
                <p class="font-bold text-[9px] text-slate-300 px-0.5 leading-none text-center line-clamp-2 uppercase tracking-tight h-5">${dish.dishName}</p>
            `;
            DOMElements.dishGridContainer.appendChild(button);
        });
    });
}

function renderDailySummaryTable() {
    if (!state.menu || !state.menu.dishes) return;
    const dishes = state.menu.dishes;
    DOMElements.dailySummaryContainer.innerHTML = '';

    const types = ['cold', 'hot', 'extras'];
    const groups = {
        cold: dishes.filter(d => d.dishType === 'cold').sort((a,b) => a.dishLetter.localeCompare(b.dishLetter)),
        hot: dishes.filter(d => d.dishType === 'hot').sort((a,b) => a.dishLetter.localeCompare(b.dishLetter)),
        extras: dishes.filter(d => d.dishType !== 'cold' && d.dishType !== 'hot').sort((a,b) => a.dishLetter.localeCompare(b.dishLetter))
    };

    types.forEach(type => {
        const list = groups[type];
        if (list.length === 0) return;

        const wrapper = document.createElement('div');
        wrapper.className = 'bg-slate-800/40 rounded-3xl border border-slate-700/50 overflow-hidden shadow-2xl animate-in slide-in-from-bottom-4 duration-300';

        const header = document.createElement('div');
        header.className = `px-4 py-3 text-[10px] font-black uppercase tracking-widest text-white border-b border-white/5 ${type === 'hot' ? 'bg-red-600/20' : type === 'cold' ? 'bg-blue-600/20' : 'bg-slate-700/40'}`;
        header.textContent = `${type} DISHES REPORT`;
        wrapper.appendChild(header);

        let tableHTML = `
            <div class="overflow-x-auto">
                <table class="min-w-full divide-y divide-slate-800 text-[11px]">
                    <thead class="bg-slate-900/50">
                        <tr>
                            <th scope="col" class="px-4 py-3 text-left font-black text-slate-500 uppercase tracking-widest">ID</th>
                            <th scope="col" class="px-4 py-3 text-left font-black text-slate-500 uppercase tracking-widest hidden sm:table-cell">Dish</th>
                            <th scope="col" class="px-4 py-3 text-left font-black text-slate-500 uppercase tracking-widest">°C</th>
                            <th scope="col" class="px-4 py-3 text-left font-black text-slate-500 uppercase tracking-widest">Act</th>
                            <th scope="col" class="px-4 py-3 text-left font-black text-slate-500 uppercase tracking-widest hidden sm:table-cell">Tgt</th>
                            <th scope="col" class="px-4 py-3 text-left font-black text-slate-500 uppercase tracking-widest">AI</th>
                        </tr>
                    </thead>
                    <tbody class="divide-y divide-slate-800/50">
        `;

        list.forEach(dish => {
            const check = state.checkedData[dish.dishLetter];
            const isChecked = !!check;
            const vt = (check?.temperatures || []).map(t => parseFloat(t)).filter(t => !isNaN(t));
            const avgT = vt.length ? (vt.reduce((a,b)=>a+b,0)/vt.length).toFixed(1) + '°' : '-';
            const vw = (check?.weights || []).map(w => parseFloat(w)).filter(w => !isNaN(w));
            const avgW = vw.length ? (vw.reduce((a,b)=>a+b,0)/vw.length).toFixed(0) + 'g' : '-';
            const ai = check?.aiCheckResult?.score || '-';
            const target = dish.theoreticalWeight ? `${dish.theoreticalWeight.toFixed(0)}g` : '-';

            tableHTML += `
