function renderCameraCapture(dish, initialImage) {
    const container = document.getElementById('camera-container');
    container.innerHTML = `
        <p class="text-[8px] font-black text-slate-500 uppercase tracking-widest mb-1.5 text-center">Live Sample Image</p>
        <div id="camera-placeholder" class="w-full aspect-square rounded-3xl bg-slate-900 border-2 border-dashed border-slate-800 flex flex-col items-center justify-center text-slate-700 cursor-pointer hover:border-indigo-500 hover:text-indigo-500 transition-all shadow-inner group">
            <svg xmlns="http://www.w3.org/2000/svg" class="h-10 w-10 mb-2 group-hover:scale-110 transition-transform" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z"></path></svg>
            <span class="text-[9px] font-black uppercase tracking-[0.2em]">Activate Lens</span>
        </div>
        <div id="camera-view" class="w-full aspect-square rounded-3xl bg-black hidden relative overflow-hidden ring-2 ring-indigo-500/20 shadow-2xl">
            <video id="camera-video" autoplay playsinline class="w-full h-full object-cover"></video>
            <button type="button" id="capture-btn" class="absolute bottom-6 left-1/2 -translate-x-1/2 w-16 h-16 rounded-full border-4 border-white bg-indigo-600/60 shadow-2xl active:scale-90 transition-all backdrop-blur-sm"></button>
        </div>
        <div id="image-preview" class="w-full aspect-square rounded-3xl relative hidden group border-2 border-slate-700 overflow-hidden shadow-2xl">
            <img id="preview-img" class="w-full h-full object-cover" />
            <div class="absolute inset-0 bg-slate-950/70 text-white flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">
                <button type="button" id="retake-btn" class="px-6 py-3 bg-white text-slate-950 rounded-2xl text-[10px] font-black uppercase tracking-widest active:scale-95 transition-transform shadow-2xl">Replace Sample</button>
            </div>
        </div>
    `;
    const videoEl = container.querySelector('#camera-video');
    const form = DOMElements.dishCardContainer.querySelector('#dish-form');
    let stream = null;

    container.querySelector('#camera-placeholder').onclick = async () => {
        if (form.querySelector('input').disabled) return;
        try {
            stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } });
            videoEl.srcObject = stream;
            container.querySelector('#camera-placeholder').classList.add('hidden');
            container.querySelector('#camera-view').classList.remove('hidden');
        } catch (e) { alert("Camera Permission Failed: " + e.message); }
    };

    container.querySelector('#capture-btn').onclick = () => {
        const canvas = document.createElement('canvas');
        canvas.width = 1024; canvas.height = 1024;
        canvas.getContext('2d').drawImage(videoEl, 0, 0, 1024, 1024);
        const dataUrl = canvas.toDataURL('image/jpeg', 0.9);
        container.querySelector('#preview-img').src = dataUrl;
        form.dataset.capturedImage = dataUrl;
        if (stream) stream.getTracks().forEach(t => t.stop());
        container.querySelector('#camera-view').classList.add('hidden');
        container.querySelector('#image-preview').classList.remove('hidden');
        handleAiCheck(dish, dataUrl);
    };

    container.querySelector('#retake-btn').onclick = () => {
        if (form.querySelector('input').disabled) return;
        container.querySelector('#image-preview').classList.add('hidden');
        container.querySelector('#camera-placeholder').classList.remove('hidden');
    };

    if (initialImage) {
        container.querySelector('#preview-img').src = initialImage;
        form.dataset.capturedImage = initialImage;
        container.querySelector('#camera-placeholder').classList.add('hidden');
        container.querySelector('#image-preview').classList.remove('hidden');
    }
}

async function handleAiCheck(dish, capturedImageDataUrl) {
    const feedbackContainer = document.getElementById('ai-feedback-container');
    feedbackContainer.innerHTML = `
        <div class="p-6 border border-indigo-500/20 bg-indigo-900/10 rounded-3xl flex flex-col items-center justify-center space-y-3 shadow-inner">
            <div class="animate-spin rounded-full h-6 w-6 border-2 border-indigo-500 border-t-transparent"></div>
            <p class="font-black text-indigo-400 text-[10px] uppercase tracking-[0.3em] animate-pulse">Running Neural Quality Audit</p>
        </div>`;

    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

        let refImgPart = null;
        try {
            const refRes = await fetch(dish.dishImage);
            if (refRes.ok) {
                const blob = await refRes.blob();
                const refBase64 = await new Promise(res => { 
                    const fr = new FileReader(); 
                    fr.onloadend = () => res(fr.result.split(',')[1]); 
                    fr.readAsDataURL(blob); 
                });
                refImgPart = { inlineData: { mimeType: 'image/jpeg', data: refBase64 } };
            }
        } catch (e) { console.warn("Reference failed:", e); }

        const promptText = `Analyze dish '${dish.dishName}'. Michelin standards. Return JSON: { "score": 1-10, "positives": string[], "improvements": string[], "overall_comment": string }`;

        const contentsParts = [ { text: promptText } ];
        if (refImgPart) contentsParts.push(refImgPart);
        contentsParts.push({ inlineData: { mimeType: 'image/jpeg', data: capturedImageDataUrl.split(',')[1] } });

        const result = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: { parts: contentsParts },
            config: { responseMimeType: "application/json" }
        });

        const feedbackData = JSON.parse(result.text);
        document.getElementById('dish-form').dataset.aiFeedback = JSON.stringify(feedbackData);
        renderAiFeedback(feedbackData);
    } catch (e) { 
        console.error(e);
        feedbackContainer.innerHTML = `<div class="p-4 border border-red-900/40 bg-red-950/20 rounded-2xl text-[10px] text-red-400 font-bold uppercase tracking-widest text-center shadow-inner">AI Service Offline — Complete Manual Audit</div>`; 
    }
}

function renderAiFeedback(feedbackData) {
    const container = document.getElementById('ai-feedback-container');
    if (!container || !feedbackData) return;

    const score = Math.max(1, Math.min(10, feedbackData.score || 0));
    const positives = (feedbackData.positives || []).map(p => `<li class="flex items-center gap-2"><div class="w-1 h-1 rounded-full bg-green-500"></div>${p}</li>`).join('');
    const improvements = (feedbackData.improvements || []).map(i => `<li class="flex items-center gap-2"><div class="w-1 h-1 rounded-full bg-yellow-500"></div>${i}</li>`).join('');

    container.innerHTML = `
        <div class="bg-slate-900/60 border border-slate-700/50 rounded-3xl overflow-hidden shadow-2xl ring-1 ring-white/5 animate-in zoom-in-95 duration-500">
            <div class="px-5 py-3 flex justify-between items-center bg-slate-800 border-b border-white/5">
                <span class="text-[9px] font-black uppercase text-indigo-400 tracking-[0.2em]">Neural Intelligence Report</span>
                <span class="text-sm font-black text-white bg-indigo-600 px-3 py-1 rounded-xl shadow-lg shadow-indigo-600/30">${score}/10</span>
            </div>
            <div class="p-5 grid grid-cols-1 sm:grid-cols-2 gap-6 text-xs">
                <div class="space-y-3">
                    <p class="font-black text-green-400 uppercase tracking-tighter text-[10px]">Exceptional Highlights</p>
                    <ul class="text-slate-300 space-y-1">${positives || 'Standard met'}</ul>
                </div>
                <div class="space-y-3">
                    <p class="font-black text-yellow-400 uppercase tracking-tighter text-[10px]">Correction Areas</p>
                    <ul class="text-slate-300 space-y-1">${improvements || 'No issues detected'}</ul>
                </div>
            </div>
            <div class="px-5 pb-5">
                <div class="bg-slate-950/40 p-4 rounded-2xl border border-slate-800">
                    <p class="text-[11px] italic text-slate-400 leading-relaxed">"${feedbackData.overall_comment}"</p>
                </div>
            </div>
        </div>
    `;
}

