    DOMElements.navAuditBtn.className = `px-4 py-1.5 text-[10px] font-black rounded-md transition-all uppercase ${viewName === 'audit' ? activeClass : inactiveClass}`;

    if (viewName === 'audit') renderAuditDishLibrary();
    if (viewName === 'dashboard') renderApp();
}

// --- Audit Library Logic ---

async function renderAuditDishLibrary() {
    DOMElements.auditResultsContainer.innerHTML = `
        <div class="flex flex-col items-center justify-center py-24">
            <div class="animate-spin rounded-full h-10 w-10 border-4 border-indigo-500/20 border-t-indigo-500 mb-6"></div>
            <p class="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] animate-pulse">Syncing Historical Master List</p>
        </div>
    `;

    try {
        const snapshot = await get(ref(database, 'quality-checks'));
        const allData = snapshot.val() || {};

        const dishMap = new Map();
        // Traverse all dates and all dishes ever recorded
        Object.keys(allData).forEach(date => {
            Object.values(allData[date]).forEach(check => {
                if (check.dishName) {
                    const key = check.dishName;
                    if (!dishMap.has(key)) {
                        dishMap.set(key, { 
                            name: check.dishName, 
                            type: check.dishType || 'extras',
                            count: 1
                        });
                    } else {
                        dishMap.get(key).count++;
                    }
                }
            });
        });

        const allDishes = Array.from(dishMap.values());
        if (allDishes.length === 0) {
            DOMElements.auditResultsContainer.innerHTML = `<div class="p-16 text-center bg-slate-800/30 rounded-3xl border-2 border-dashed border-slate-800"><p class="text-xs text-slate-500 font-bold uppercase tracking-widest">Audit Database is currently empty.</p></div>`;
            return;
        }

        const hot = allDishes.filter(d => d.type === 'hot').sort((a,b) => a.name.localeCompare(b.name));
        const cold = allDishes.filter(d => d.type === 'cold').sort((a,b) => a.name.localeCompare(b.name));
        const extras = allDishes.filter(d => d.type !== 'hot' && d.type !== 'cold').sort((a,b) => a.name.localeCompare(b.name));

        let html = `<div class="space-y-10 animate-in fade-in duration-500">`;

        const renderSection = (list, title, borderColor, iconColor) => {
            if (list.length === 0) return '';
            return `
                <div>
                    <div class="flex items-center gap-3 mb-4 px-1">
                        <div class="h-2 w-2 rounded-full ${iconColor} shadow-[0_0_8px_${iconColor}]"></div>
                        <h3 class="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">${title}</h3>
                    </div>
                    <div class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3">
                        ${list.map(d => `
                            <button onclick="window.runAuditForDish('${d.name.replace(/'/g, "\\'")}')" class="group relative flex flex-col p-4 bg-slate-800/40 border border-slate-700/50 rounded-2xl hover:border-indigo-500/50 hover:bg-slate-800 transition-all text-left shadow-lg hover:shadow-indigo-500/10 active:scale-[0.98]">
                                <div class="absolute top-4 right-4 bg-slate-900/50 p-1.5 rounded-lg opacity-40 group-hover:opacity-100 transition-opacity">
                                    <svg xmlns="http://www.w3.org/2000/svg" class="h-4 w-4 text-indigo-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M13 10V3L4 14h7v7l9-11h-7z"></path></svg>
                                </div>
                                <p class="text-sm font-black text-slate-200 group-hover:text-white pr-8 line-clamp-1 mb-1 uppercase tracking-tight">${d.name}</p>
                                <div class="flex items-center gap-2">
                                    <span class="text-[10px] text-indigo-400 font-black">${d.count}</span>
                                    <span class="text-[10px] text-slate-500 font-bold uppercase tracking-widest">Audits to Date</span>
                                </div>
                            </button>
                        `).join('')}
                    </div>
                </div>
            `;
        };

        html += renderSection(hot, 'Hot Cuisine Archive', 'border-red-500/30', 'bg-red-500');
        html += renderSection(cold, 'Cold Cuisine Archive', 'border-blue-500/30', 'bg-blue-500');
        html += renderSection(extras, 'Sides & Extras Archive', 'border-slate-500/30', 'bg-slate-500');
        html += `</div>`;

        DOMElements.auditResultsContainer.innerHTML = html;
    } catch (e) {
        console.error(e);
        DOMElements.auditResultsContainer.innerHTML = `<div class="p-8 text-center text-red-400 text-xs font-bold bg-red-950/20 border border-red-900/50 rounded-2xl uppercase tracking-widest">Synchronization Error: ${e.message}</div>`;
    }
}

window.runAuditForDish = async (dishName) => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
    DOMElements.auditResultsContainer.innerHTML = `
        <div class="flex flex-col items-center justify-center py-24 space-y-8">
            <div class="relative w-24 h-24">
                <div class="absolute inset-0 border-4 border-indigo-500/10 rounded-full"></div>
                <div class="absolute inset-0 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
                <div class="absolute inset-4 bg-indigo-500/5 rounded-full animate-pulse"></div>
            </div>
            <div class="text-center">
                <p class="text-[10px] font-black text-indigo-400 uppercase tracking-[0.5em] animate-pulse mb-3">AI Agent Analyzing History</p>
                <h3 class="text-xs text-slate-400 font-bold uppercase tracking-widest px-6 leading-relaxed">Synthesizing data points for<br><span class="text-white mt-1 block font-black border-b border-indigo-500/30 pb-1 mx-auto max-w-fit italic">"${dishName}"</span></h3>
            </div>
        </div>
    `;

    try {
        const snapshot = await get(ref(database, 'quality-checks'));
        const allData = snapshot.val() || {};
        const historicalChecks = [];

        Object.keys(allData).forEach(date => {
            Object.values(allData[date]).forEach(check => {
                if (check.dishName === dishName) historicalChecks.push({ date, ...check });
            });
        });

        // Sort by date latest first
        historicalChecks.sort((a,b) => b.date.localeCompare(a.date));

        const feedbackSummaries = historicalChecks.map(c => 
            `[${c.date}] AI Score: ${c.aiCheckResult?.score || '?'}. Positives: ${c.aiCheckResult?.positives?.join(', ')}. Improvements: ${c.aiCheckResult?.improvements?.join(', ')}. Chef Note: ${c.comment}`
        ).join('\n');

        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: `As an executive quality control auditor, perform a comprehensive trajectory analysis for "${dishName}".
            Data available:
            ${feedbackSummaries}

            Return strictly a JSON report:
            {
              "stability_rating": 1-10,
              "trend_narrative": "Executive summary of quality trajectory.",
              "critical_deficiencies": ["Recurring issues"],
              "best_practices": ["Consistently good points"],
              "operational_directives": ["Next steps for improvement"],
              "score_trajectory": [chronological scores]
            }`,
            config: { responseMimeType: "application/json", temperature: 0.1 }
        });

        const auditData = JSON.parse(response.text);
        renderAuditReport(auditData, historicalChecks, dishName);

    } catch (e) {
        console.error(e);
        DOMElements.auditResultsContainer.innerHTML = `<div class="p-8 bg-red-950/20 border border-red-900/50 rounded-3xl text-center shadow-2xl"><p class="text-xs text-red-400 font-bold">Audit Agent Encountered a Deficit: ${e.message}</p><button onclick="renderAuditDishLibrary()" class="mt-6 px-8 py-2 bg-slate-800 rounded-xl text-[10px] uppercase font-black text-white hover:bg-slate-700 transition-all border border-slate-700">Back to Library</button></div>`;
    }
}

