            <button type="button" id="capture-btn" class="absolute bottom-8 left-1/2 -translate-x-1/2 w-20 h-20 rounded-full border-[6px] border-white/20 bg-indigo-600 shadow-2xl active:scale-90 transition-all backdrop-blur-md flex items-center justify-center">
