                <svg xmlns="http://www.w3.org/2000/svg" class="h-10 w-10 mb-4 text-indigo-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"></path></svg>
                <button type="button" id="retake-btn" class="px-8 py-3 bg-white text-slate-950 rounded-2xl text-[10px] font-black uppercase tracking-[0.3em] active:scale-95 transition-transform shadow-2xl border-b-4 border-slate-300">Rescan Specimen</button>
            </div>
        </div>
    `;
    const videoEl = container.querySelector('#camera-video');
    const form = DOMElements.dishCardContainer.querySelector('#dish-form');
    let stream = null;

    container.querySelector('#camera-placeholder').onclick = async () => {
        if (form.querySelector('input').disabled) return;
        try {
            stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } });
            videoEl.srcObject = stream;
            container.querySelector('#camera-placeholder').classList.add('hidden');
            container.querySelector('#camera-view').classList.remove('hidden');
        } catch (e) { alert("Camera Access Required: " + e.message); }
    };

    container.querySelector('#capture-btn').onclick = () => {
        const canvas = document.createElement('canvas');
        canvas.width = 1024; canvas.height = 1024;
        canvas.getContext('2d').drawImage(videoEl, 0, 0, 1024, 1024);
        const dataUrl = canvas.toDataURL('image/jpeg', 0.95);
        container.querySelector('#preview-img').src = dataUrl;
        form.dataset.capturedImage = dataUrl;
        if (stream) stream.getTracks().forEach(t => t.stop());
        container.querySelector('#camera-view').classList.add('hidden');
        container.querySelector('#image-preview').classList.remove('hidden');
        handleAiCheck(dish, dataUrl);
    };

    container.querySelector('#retake-btn').onclick = () => {
        if (form.querySelector('input').disabled) return;
        container.querySelector('#image-preview').classList.add('hidden');
        container.querySelector('#camera-placeholder').classList.remove('hidden');
    };

    if (initialImage) {
        container.querySelector('#preview-img').src = initialImage;
        form.dataset.capturedImage = initialImage;
        container.querySelector('#camera-placeholder').classList.add('hidden');
        container.querySelector('#image-preview').classList.remove('hidden');
    }
}

async function handleAiCheck(dish, capturedImageDataUrl) {
    const feedbackContainer = document.getElementById('ai-feedback-container');
    feedbackContainer.innerHTML = `
        <div class="p-8 border border-indigo-500/30 bg-indigo-900/10 rounded-[2rem] flex flex-col items-center justify-center space-y-4 shadow-2xl shadow-indigo-500/5">
            <div class="relative w-8 h-8">
                <div class="absolute inset-0 border-2 border-indigo-500/20 rounded-full"></div>
                <div class="absolute inset-0 border-2 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
            </div>
            <p class="font-black text-indigo-400 text-[10px] uppercase tracking-[0.4em] animate-pulse">Running Neural Quality Probe</p>
        </div>`;

    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

        let refImgPart = null;
        try {
            const refRes = await fetch(dish.dishImage);
            if (refRes.ok) {
                const blob = await refRes.blob();
                const refBase64 = await new Promise(res => { 
                    const fr = new FileReader(); 
                    fr.onloadend = () => res(fr.result.split(',')[1]); 
                    fr.readAsDataURL(blob); 
                });
                refImgPart = { inlineData: { mimeType: 'image/jpeg', data: refBase64 } };
            }
        } catch (e) { console.warn("Reference load deficit:", e); }

        const promptText = `Execute high-standard quality analysis for dish '${dish.dishName}'. 
        Compare visual sample against reference standard.
        Return strictly JSON: 
        { "score": 1-10, "positives": string[], "improvements": string[], "overall_comment": string }`;

        const contentsParts = [ { text: promptText } ];
        if (refImgPart) contentsParts.push(refImgPart);
        contentsParts.push({ inlineData: { mimeType: 'image/jpeg', data: capturedImageDataUrl.split(',')[1] } });

        const result = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: { parts: contentsParts },
            config: { responseMimeType: "application/json", temperature: 0.1 }
        });

        const feedbackData = JSON.parse(result.text);
        document.getElementById('dish-form').dataset.aiFeedback = JSON.stringify(feedbackData);
        renderAiFeedback(feedbackData);
    } catch (e) { 
        console.error(e);
        feedbackContainer.innerHTML = `<div class="p-6 border border-red-900/40 bg-red-950/20 rounded-3xl text-[10px] text-red-400 font-black uppercase tracking-widest text-center shadow-xl">Audit Engine Halted — Manual Review Required</div>`; 
    }
}

function renderAiFeedback(feedbackData) {
    const container = document.getElementById('ai-feedback-container');
    if (!container || !feedbackData) return;

    const score = Math.max(1, Math.min(10, feedbackData.score || 0));
    const positives = (feedbackData.positives || []).map(p => `<li class="flex items-center gap-3"><div class="w-1.5 h-1.5 rounded-full bg-green-500 shadow-[0_0_8px_rgba(34,197,94,0.5)]"></div>${p}</li>`).join('');
    const improvements = (feedbackData.improvements || []).map(i => `<li class="flex items-center gap-3"><div class="w-1.5 h-1.5 rounded-full bg-yellow-500 shadow-[0_0_8px_rgba(234,179,8,0.5)]"></div>${i}</li>`).join('');

    container.innerHTML = `
        <div class="bg-slate-900/60 border border-slate-700/50 rounded-[2.5rem] overflow-hidden shadow-2xl ring-1 ring-white/5 animate-in slide-in-from-bottom-6 duration-500">
            <div class="px-8 py-5 flex justify-between items-center bg-slate-800 border-b border-white/5">
                <span class="text-[10px] font-black uppercase text-indigo-400 tracking-[0.3em]">AI Quality Intelligence Report</span>
                <span class="text-lg font-black text-white bg-indigo-600 px-5 py-2 rounded-2xl shadow-2xl shadow-indigo-600/40 border-b-4 border-indigo-800">${score}/10</span>
            </div>
            <div class="p-8 grid grid-cols-1 sm:grid-cols-2 gap-8 text-xs">
                <div class="space-y-4">
                    <p class="font-black text-green-400 uppercase tracking-widest text-[10px] pl-2 border-l-2 border-green-500/50">Verified Compliance</p>
                    <ul class="text-slate-300 space-y-2.5 font-medium pl-1">${positives || 'Standard met'}</ul>
                </div>
                <div class="space-y-4">
                    <p class="font-black text-yellow-400 uppercase tracking-widest text-[10px] pl-2 border-l-2 border-yellow-500/50">Strategic Adjustments</p>
                    <ul class="text-slate-300 space-y-2.5 font-medium pl-1">${improvements || 'Zero deficiencies'}</ul>
                </div>
            </div>
            <div class="px-8 pb-8">
                <div class="bg-slate-950/60 p-6 rounded-[1.5rem] border border-slate-800/80 shadow-inner">
                    <p class="text-xs italic text-slate-400 leading-relaxed font-medium">"${feedbackData.overall_comment}"</p>
                </div>
            </div>
        </div>
    `;
}

