function renderApp() {
    DOMElements.loadingIndicator.classList.toggle('hidden', !state.isMenuLoading && !state.isCheckDataLoading);
    DOMElements.mainView.classList.toggle('hidden', state.isMenuLoading || state.isCheckDataLoading || state.currentView !== 'dashboard');

    if (state.menu && state.menu.dishes.length > 0) {
        DOMElements.welcomePlaceholder.classList.add('hidden');
        DOMElements.dishGridContainer.classList.remove('hidden');
        DOMElements.dailySummarySection.classList.remove('hidden');
        renderDishSelectionGrid();
        renderDailySummaryTable();
    } else {
        renderWelcomePlaceholder();
        DOMElements.dailySummarySection.classList.add('hidden');
    }
    renderDateSelector();
}

function renderDateSelector() {
    const viewDate = getStartOfWeek(new Date(state.selectedDate + 'T12:00:00Z'));
    const weekDays = Array.from({ length: 5 }).map((_, i) => {
        const day = new Date(viewDate);
        day.setDate(viewDate.getDate() + i);
        return day;
    });
    DOMElements.dateButtonsContainer.innerHTML = '';
    weekDays.forEach(day => {
        const dayString = day.toISOString().split('T')[0];
        const isSelected = dayString === state.selectedDate;
        const button = document.createElement('button');
        button.className = `flex flex-col items-center justify-center w-11 h-14 sm:w-14 sm:h-16 rounded-[1.2rem] transition-all duration-300 transform active:scale-90 shadow-lg ${isSelected ? 'bg-indigo-600 text-white shadow-indigo-600/40 ring-4 ring-indigo-400/20' : 'bg-slate-800 text-slate-500 hover:text-slate-300 border border-slate-700/50'}`;
        button.innerHTML = `
            <span class="text-[9px] uppercase font-black tracking-tighter opacity-70 mb-1">${day.toLocaleDateString('en-US', { weekday: 'short' })}</span>
            <span class="text-base font-black">${day.getDate()}</span>
        `;
        button.onclick = () => {
            state.selectedDate = dayString;
            fetchCheckData();
        };
        DOMElements.dateButtonsContainer.appendChild(button);
    });
}

function renderDishSelectionGrid() {
    DOMElements.dishGridContainer.innerHTML = '';
    if (!state.menu || !state.menu.dishes) return;

    const groups = {
        cold: state.menu.dishes.filter(d => d.dishType === 'cold').sort((a,b) => a.dishLetter.localeCompare(b.dishLetter)),
        hot: state.menu.dishes.filter(d => d.dishType === 'hot').sort((a,b) => a.dishLetter.localeCompare(b.dishLetter)),
        extras: state.menu.dishes.filter(d => d.dishType !== 'cold' && d.dishType !== 'hot').sort((a,b) => a.dishLetter.localeCompare(b.dishLetter))
    };

    const themes = {
      hot: { cardBg: 'bg-slate-800/50', cardBorder: 'border-red-900/30', circleBg: 'bg-red-500', letterText: 'text-white' },
      cold: { cardBg: 'bg-slate-800/50', cardBorder: 'border-blue-900/30', circleBg: 'bg-blue-500', letterText: 'text-white' },
      default: { cardBg: 'bg-slate-800/50', cardBorder: 'border-slate-700/50', circleBg: 'bg-indigo-600', letterText: 'text-white' }
    };

    Object.keys(groups).forEach(type => {
        const list = groups[type];
        if (list.length === 0) return;

        const h = document.createElement('div');
        h.className = 'col-span-full text-[10px] font-black text-slate-500 uppercase tracking-[0.3em] mt-6 mb-2 pl-2 border-l-2 border-indigo-500/30';
        h.textContent = `${type} STATION`;
        DOMElements.dishGridContainer.appendChild(h);

        list.forEach(dish => {
            const isChecked = !!state.checkedData[dish.dishLetter];
            const theme = themes[dish.dishType] || themes.default;
            const button = document.createElement('button');
            button.className = `group relative flex flex-col items-center justify-center p-4 border rounded-[2rem] transition-all duration-300 ${theme.cardBg} ${theme.cardBorder} hover:scale-105 active:scale-95 shadow-xl hover:shadow-indigo-500/10 backdrop-blur-sm`;
            button.onclick = () => {
                state.selectedDish = dish;
                showView('detail');
                renderDishCard();
            };
            let checkHTML = isChecked ? `<div class="absolute -top-1 -right-1 bg-green-500 rounded-full p-1.5 text-white shadow-2xl ring-4 ring-slate-900 scale-100 group-hover:scale-110 transition-transform"><svg xmlns="http://www.w3.org/2000/svg" class="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="4" d="M5 13l4 4L19 7"></path></svg></div>` : '';
            button.innerHTML = `
                ${checkHTML}
                <div class="mb-3 h-12 w-12 sm:h-14 sm:w-14 rounded-full flex items-center justify-center text-sm sm:text-base font-black shadow-2xl ring-4 ring-white/5 ${theme.circleBg} ${theme.letterText} uppercase">${dish.dishLetter}</div>
                <p class="font-black text-[10px] text-slate-300 px-1 leading-tight text-center line-clamp-2 uppercase tracking-tight h-8 flex items-center group-hover:text-white transition-colors">${dish.dishName}</p>
            `;
            DOMElements.dishGridContainer.appendChild(button);
        });
    });
}

function renderDailySummaryTable() {
    if (!state.menu || !state.menu.dishes) return;
    const dishes = state.menu.dishes;
    DOMElements.dailySummaryContainer.innerHTML = '';

    const types = ['cold', 'hot', 'extras'];
    const groups = {
        cold: dishes.filter(d => d.dishType === 'cold').sort((a,b) => a.dishLetter.localeCompare(b.dishLetter)),
        hot: dishes.filter(d => d.dishType === 'hot').sort((a,b) => a.dishLetter.localeCompare(b.dishLetter)),
        extras: dishes.filter(d => d.dishType !== 'cold' && d.dishType !== 'hot').sort((a,b) => a.dishLetter.localeCompare(b.dishLetter))
    };

    types.forEach(type => {
        const list = groups[type];
        if (list.length === 0) return;

        const wrapper = document.createElement('div');
        wrapper.className = 'bg-slate-800/40 rounded-[2rem] border border-slate-700/50 overflow-hidden shadow-2xl backdrop-blur-md';

        const header = document.createElement('div');
        header.className = `px-6 py-4 text-[10px] font-black uppercase tracking-[0.2em] text-white border-b border-white/5 ${type === 'hot' ? 'bg-red-600/20' : type === 'cold' ? 'bg-blue-600/20' : 'bg-slate-700/40'}`;
        header.textContent = `${type} DISHES RECAP`;
        wrapper.appendChild(header);

        let tableHTML = `
            <div class="overflow-x-auto custom-scrollbar">
                <table class="min-w-full divide-y divide-slate-800 text-[11px]">
                    <thead class="bg-slate-950/40">
                        <tr>
                            <th scope="col" class="px-6 py-4 text-left font-black text-slate-500 uppercase tracking-widest">ID</th>
                            <th scope="col" class="px-6 py-4 text-left font-black text-slate-500 uppercase tracking-widest hidden sm:table-cell">Dish Label</th>
                            <th scope="col" class="px-6 py-4 text-left font-black text-slate-500 uppercase tracking-widest">Temp</th>
                            <th scope="col" class="px-6 py-4 text-left font-black text-slate-500 uppercase tracking-widest">Mass</th>
                            <th scope="col" class="px-6 py-4 text-left font-black text-slate-500 uppercase tracking-widest hidden sm:table-cell">Spec</th>
                            <th scope="col" class="px-6 py-4 text-left font-black text-slate-500 uppercase tracking-widest">AI</th>
                        </tr>
                    </thead>
                    <tbody class="divide-y divide-slate-800/50">
        `;

        list.forEach(dish => {
            const check = state.checkedData[dish.dishLetter];
            const isChecked = !!check;
            const vt = (check?.temperatures || []).map(t => parseFloat(t)).filter(t => !isNaN(t));
            const avgT = vt.length ? (vt.reduce((a,b)=>a+b,0)/vt.length).toFixed(1) + '°' : '-';
            const vw = (check?.weights || []).map(w => parseFloat(w)).filter(w => !isNaN(w));
            const avgW = vw.length ? (vw.reduce((a,b)=>a+b,0)/vw.length).toFixed(0) + 'g' : '-';
            const ai = check?.aiCheckResult?.score || '-';
            const target = dish.theoreticalWeight ? `${dish.theoreticalWeight.toFixed(0)}g` : '-';

            tableHTML += `
                <tr class="hover:bg-slate-700/30 cursor-pointer transition-colors ${!isChecked ? 'opacity-30' : ''}" onclick="window.handleSelectDish('${dish.dishLetter}')">
                    <td class="px-6 py-5 font-black text-indigo-400">${dish.dishLetter}</td>
                    <td class="px-6 py-5 text-slate-200 hidden sm:table-cell font-black uppercase tracking-tighter truncate max-w-[150px]">${dish.dishName}</td>
                    <td class="px-6 py-5 text-slate-300 font-mono font-black">${avgT}</td>
                    <td class="px-6 py-5 text-slate-300 font-mono font-black">${avgW}</td>
                    <td class="px-6 py-5 text-slate-600 hidden sm:table-cell italic font-mono font-bold">${target}</td>
                    <td class="px-6 py-5 font-black ${isChecked ? (ai > 7 ? 'text-green-400' : 'text-indigo-400') : 'text-slate-700'}">${ai}</td>
                </tr>
            `;
        });

        tableHTML += `</tbody></table></div>`;
        wrapper.innerHTML += tableHTML;
        DOMElements.dailySummaryContainer.appendChild(wrapper);
    });
    DOMElements.dailySummarySection.classList.toggle('hidden', dishes.length === 0);
}

window.handleSelectDish = (letter) => {
    const dish = state.menu.dishes.find(d => d.dishLetter === letter);
    if(dish) {
        state.selectedDish = dish;
        showView('detail');
        renderDishCard();
    }
}

