// --- Audit Library Logic ---

async function renderAuditDishLibrary() {
    DOMElements.auditResultsContainer.innerHTML = `
        <div class="flex flex-col items-center justify-center py-24">
            <div class="animate-spin rounded-full h-10 w-10 border-4 border-indigo-500/20 border-t-indigo-500 mb-6"></div>
            <p class="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] animate-pulse">Accessing Global Quality Records</p>
        </div>
    `;

    try {
        const snapshot = await get(ref(database, 'quality-checks'));
        const allData = snapshot.val() || {};

        const dishMap = new Map();
        // Traverse all dates and all dishes ever recorded since start to till date
        Object.keys(allData).forEach(date => {
            Object.values(allData[date]).forEach(check => {
                if (check.dishName) {
                    const key = check.dishName;
                    if (!dishMap.has(key)) {
                        dishMap.set(key, { 
                            name: check.dishName, 
                            type: check.dishType || 'extras',
                            count: 1
                        });
                    } else {
                        dishMap.get(key).count++;
                    }
                }
            });
        });

        const allDishes = Array.from(dishMap.values());
        if (allDishes.length === 0) {
            DOMElements.auditResultsContainer.innerHTML = `<div class="p-16 text-center bg-slate-800/30 rounded-3xl border-2 border-dashed border-slate-800"><p class="text-xs text-slate-500 font-bold uppercase tracking-widest">No historical checks recorded yet.</p></div>`;
            return;
        }

        const hot = allDishes.filter(d => d.type === 'hot').sort((a,b) => a.name.localeCompare(b.name));
        const cold = allDishes.filter(d => d.type === 'cold').sort((a,b) => a.name.localeCompare(b.name));
        const extras = allDishes.filter(d => d.type !== 'hot' && d.type !== 'cold').sort((a,b) => a.name.localeCompare(b.name));

        let html = `<div class="space-y-12 animate-in fade-in duration-500">`;

        const renderSection = (list, title, colorClass) => {
            if (list.length === 0) return '';
            return `
                <div>
                    <div class="flex items-center gap-3 mb-5 px-1 border-b border-slate-800 pb-2">
                        <div class="h-3 w-3 rounded-full ${colorClass} shadow-lg"></div>
                        <h3 class="text-[11px] font-black text-slate-400 uppercase tracking-[0.25em]">${title}</h3>
                    </div>
                    <div class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
                        ${list.map(d => `
                            <button onclick="window.runAuditForDish('${d.name.replace(/'/g, "\\'")}')" class="group relative flex flex-col p-5 bg-slate-800/50 border border-slate-700/50 rounded-[1.5rem] hover:border-indigo-500/50 hover:bg-slate-800 transition-all text-left shadow-xl active:scale-[0.98]">
                                <div class="absolute top-5 right-5 text-indigo-500/30 group-hover:text-indigo-400 transition-colors">
                                    <svg xmlns="http://www.w3.org/2000/svg" class="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5l7 7-7 7"></path></svg>
                                </div>
                                <p class="text-sm font-black text-slate-100 group-hover:text-white pr-8 line-clamp-1 mb-2 uppercase tracking-tight">${d.name}</p>
                                <div class="flex items-center gap-3">
                                    <span class="text-[10px] text-indigo-400 font-black px-2 py-0.5 bg-indigo-500/10 rounded-md border border-indigo-500/20">${d.count} Samples</span>
                                    <span class="text-[9px] text-slate-500 font-bold uppercase tracking-widest">History Log</span>
                                </div>
                            </button>
                        `).join('')}
                    </div>
                </div>
            `;
        };

        html += renderSection(hot, 'Hot Station Master Library', 'bg-red-500');
        html += renderSection(cold, 'Cold Station Master Library', 'bg-blue-500');
        html += renderSection(extras, 'Additional Menu Items', 'bg-slate-500');
        html += `</div>`;

        DOMElements.auditResultsContainer.innerHTML = html;
    } catch (e) {
        console.error(e);
        DOMElements.auditResultsContainer.innerHTML = `<div class="p-8 text-center text-red-400 text-xs font-bold bg-red-950/20 border border-red-900/50 rounded-2xl uppercase tracking-widest">Master List Retrieval Failed: ${e.message}</div>`;
    }
}

window.runAuditForDish = async (dishName) => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
    DOMElements.auditResultsContainer.innerHTML = `
        <div class="flex flex-col items-center justify-center py-24 space-y-8">
            <div class="relative w-24 h-24">
                <div class="absolute inset-0 border-4 border-indigo-500/10 rounded-full"></div>
                <div class="absolute inset-0 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
            </div>
            <div class="text-center">
                <p class="text-[10px] font-black text-indigo-400 uppercase tracking-[0.5em] animate-pulse mb-3">AI Intelligence Deep Scan</p>
                <h3 class="text-xs text-slate-400 font-bold uppercase tracking-widest px-6">Synthesizing full historical data for<br><span class="text-white mt-1 block font-black border-b border-indigo-500/30 pb-1 mx-auto max-w-fit italic">"${dishName}"</span></h3>
            </div>
        </div>
    `;

    try {
        const snapshot = await get(ref(database, 'quality-checks'));
        const allData = snapshot.val() || {};
        const historicalChecks = [];

        Object.keys(allData).forEach(date => {
            Object.values(allData[date]).forEach(check => {
                if (check.dishName === dishName) historicalChecks.push({ date, ...check });
            });
        });

        historicalChecks.sort((a,b) => b.date.localeCompare(a.date));

        const feedbackSummaries = historicalChecks.map(c => 
            `[Log Date: ${c.date}] AI Index Score: ${c.aiCheckResult?.score || '?'}. Findings: ${c.aiCheckResult?.positives?.join(', ')} / ${c.aiCheckResult?.improvements?.join(', ')}. Chef Observation: ${c.comment}`
        ).join('\n');

        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: `Perform an executive culinary audit for "${dishName}" based on its global history.
            Historical Data:
            ${feedbackSummaries}

            Produce a strictly formatted JSON audit report:
            {
              "stability_rating": 1-10,
              "trend_narrative": "Detailed summary of quality evolution.",
              "critical_deficiencies": ["Recurring issues"],
              "best_practices": ["Consistently well-executed points"],
              "operational_directives": ["Strategic steps for the next production cycle"],
              "score_trajectory": [chronological scores list]
            }`,
            config: { responseMimeType: "application/json", temperature: 0.1 }
        });

        const auditData = JSON.parse(response.text);
        renderAuditReport(auditData, historicalChecks, dishName);

    } catch (e) {
        console.error(e);
        DOMElements.auditResultsContainer.innerHTML = `<div class="p-8 bg-red-950/20 border border-red-900/50 rounded-3xl text-center"><p class="text-xs text-red-400 font-bold">Audit Synthesis Failed: ${e.message}</p><button onclick="renderAuditDishLibrary()" class="mt-6 px-8 py-2 bg-slate-800 rounded-xl text-[10px] uppercase font-black text-white hover:bg-slate-700 transition-all">Back to Library</button></div>`;
    }
}

