            <p class="text-xs text-slate-500 font-black uppercase tracking-[0.35em] leading-relaxed">
                No menu footprint found for week <span class="text-indigo-400 font-black underline decoration-indigo-500/30 underline-offset-8">${weekId}</span>.<br>
                <span class="text-[10px] text-slate-600 mt-8 block italic font-bold">Please initialize the database via System Setup</span>
            </p>
        </div>`;
    DOMElements.welcomePlaceholder.classList.remove('hidden');
}

// Nav Logic
DOMElements.navDashboardBtn.onclick = () => showView('dashboard');
DOMElements.navAuditBtn.onclick = () => showView('audit');
DOMElements.settingsBtn.onclick = () => DOMElements.settingsModal.classList.remove('hidden');
DOMElements.settingsCloseBtn.onclick = () => DOMElements.settingsModal.classList.add('hidden');
DOMElements.settingsCancelBtn.onclick = () => DOMElements.settingsModal.classList.add('hidden');
DOMElements.backToMenuBtn.onclick = () => showView('dashboard');

DOMElements.settingsSaveBtn.onclick = () => {
    const val = DOMElements.jsonInput.value.trim();
    if (!val) { DOMElements.settingsModal.classList.add('hidden'); return; }
    try {
        const p = JSON.parse(val);
        const dishes = p.dishes.filter(d => d.stickerNo && d.stickerNo !== 'addons').map(d => {
            const ingredients = (d.ingredients || []).map(i => ({name: i.name || '?', weight: (i.amount || '0') + 'g'}));
            const totalW = (d.ingredients || []).reduce((sum, ing) => sum + (parseFloat(ing.amount) || 0), 0);
            return {
                dishLetter: d.stickerNo, 
                dishName: d.variantName, 
                dishImage: d.webUrl, 
                dishType: ['hot', 'cold'].includes(d.type) ? d.type : 'extras',
                dishIngredients: ingredients,
                theoreticalWeight: totalW
            };
        });
        const menuWeekId = getWeekId(new Date(p.startDate + 'T12:00:00Z'));
        set(ref(database, `menus/${menuWeekId}`), { dishes, startDate: p.startDate }).then(() => {
            DOMElements.settingsModal.classList.add('hidden');
            fetchMenu();
        });
    } catch (e) { DOMElements.settingsError.textContent = "Data Schema Validation Deficit."; }
