window.runAuditForDish = async (dishName) => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
    DOMElements.auditResultsContainer.innerHTML = `
        <div class="flex flex-col items-center justify-center py-24 space-y-8">
            <div class="relative w-20 h-20">
                <div class="absolute inset-0 border-4 border-indigo-500/10 rounded-full"></div>
                <div class="absolute inset-0 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
            </div>
            <div class="text-center">
                <p class="text-[10px] font-black text-indigo-400 uppercase tracking-[0.4em] animate-pulse mb-3">AI Intelligence Deep Scan</p>
                <h3 class="text-xs text-slate-400 font-bold uppercase tracking-widest px-6">Synthesizing full historical data for<br><span class="text-white mt-1 block font-black border-b border-indigo-500/30 pb-1 mx-auto max-w-fit italic">"${dishName}"</span></h3>
            </div>
        </div>
    `;

    try {
        const snapshot = await get(ref(database, 'quality-checks'));
        const allData = snapshot.val() || {};
        const historicalChecks = [];

        Object.keys(allData).forEach(date => {
            Object.values(allData[date]).forEach(check => {
                if (check.dishName === dishName) historicalChecks.push({ date, ...check });
            });
        });

        historicalChecks.sort((a,b) => b.date.localeCompare(a.date));

        const feedbackSummaries = historicalChecks.map(c => 
            `[Date: ${c.date}] Score: ${c.aiCheckResult?.score || '?'}. Findings: ${c.aiCheckResult?.positives?.join(', ')} / ${c.aiCheckResult?.improvements?.join(', ')}. Chef: ${c.comment}`
        ).join('\n');

        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: `Perform an executive culinary audit for "${dishName}" based on all recorded history.
            Historical Data:
            ${feedbackSummaries}

            Return JSON:
            {
              "stability_rating": 1-10,
              "trend_narrative": "Detailed evolvement summary.",
              "critical_deficiencies": ["Recurring issues"],
              "best_practices": ["Consistently good"],
              "operational_directives": ["Next steps"],
              "score_trajectory": [chronological scores]
            }`,
            config: { responseMimeType: "application/json", temperature: 0.1 }
        });

        const auditData = JSON.parse(response.text);
        renderAuditReport(auditData, historicalChecks, dishName);

    } catch (e) {
        console.error(e);
        DOMElements.auditResultsContainer.innerHTML = `<div class="p-8 bg-red-950/20 border border-red-900/50 rounded-3xl text-center"><p class="text-xs text-red-400 font-bold">Audit Synthesis Failed: ${e.message}</p><button onclick="renderAuditDishLibrary()" class="mt-6 px-8 py-2 bg-slate-800 rounded-xl text-[10px] uppercase font-black text-white hover:bg-slate-700 transition-all border border-slate-700">Back to Library</button></div>`;
    }
}

