                <div class="pt-6 flex flex-col sm:flex-row gap-4">
                    <button type="button" id="edit-btn" class="flex-1 py-5 text-xs font-black rounded-2xl text-slate-300 border border-slate-700 hover:bg-slate-700 transition-all uppercase tracking-[0.2em] active:scale-95 shadow-xl">Edit Audit</button>
                    <button type="submit" id="submit-btn" class="flex-[2] py-5 text-xs font-black text-white bg-indigo-600 rounded-2xl shadow-2xl shadow-indigo-600/40 hover:bg-indigo-700 transition-all uppercase tracking-[0.2em] active:scale-95 border-b-4 border-indigo-800">Finalize Quality Audit</button>
                </div>
            </form>
        </div>
    `;
    renderCameraCapture(dish, formData.capturedImage);
    const form = DOMElements.dishCardContainer.querySelector('#dish-form');
    const editBtn = DOMElements.dishCardContainer.querySelector('#edit-btn');
    const submitBtn = DOMElements.dishCardContainer.querySelector('#submit-btn');
    const inputs = form.querySelectorAll('input, textarea');

    const setFormDisabled = (disabled) => {
        inputs.forEach(el => el.disabled = disabled);
        editBtn.classList.toggle('hidden', !disabled);
        submitBtn.classList.toggle('hidden', disabled);
    };

    editBtn.onclick = () => setFormDisabled(false);

    form.onsubmit = (e) => {
        e.preventDefault();
        const data = new FormData(e.target);
        saveCheckData({
            dishLetter: dish.dishLetter,
            dishName: dish.dishName,
            dishType: dish.dishType,
            date: state.selectedDate,
            capturedImage: e.target.dataset.capturedImage || null,
            selectedIngredients: data.getAll('selectedIngredients'),
            temperatures: data.getAll('temperatures'), 
            weights: data.getAll('weights'),
            comment: data.get('comment'), 
            aiCheckResult: e.target.dataset.aiFeedback ? JSON.parse(e.target.dataset.aiFeedback) : null,
            timestamp: new Date().toISOString(),
        });
        showView('dashboard');
    };

    setFormDisabled(!isEditing);
    if (formData.aiCheckResult) renderAiFeedback(formData.aiCheckResult);
}

function renderCameraCapture(dish, initialImage) {
    const container = document.getElementById('camera-container');
    container.innerHTML = `
        <p class="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] mb-1.5 text-center">Live Sample Lens</p>
        <div id="camera-placeholder" class="w-full aspect-square rounded-[2rem] bg-slate-950 border-2 border-dashed border-slate-800 flex flex-col items-center justify-center text-slate-700 cursor-pointer hover:border-indigo-500/50 hover:text-indigo-500 transition-all shadow-inner group relative overflow-hidden">
            <svg xmlns="http://www.w3.org/2000/svg" class="h-12 w-12 mb-3 group-hover:scale-110 transition-transform relative z-10" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z"></path></svg>
            <span class="text-[10px] font-black uppercase tracking-[0.2em] relative z-10">Capture Audit Frame</span>
        </div>
        <div id="camera-view" class="w-full aspect-square rounded-[2rem] bg-black hidden relative overflow-hidden ring-4 ring-indigo-500/10 shadow-2xl">
            <video id="camera-video" autoplay playsinline class="w-full h-full object-cover"></video>
            <button type="button" id="capture-btn" class="absolute bottom-8 left-1/2 -translate-x-1/2 w-20 h-20 rounded-full border-[6px] border-white/20 bg-indigo-600 shadow-2xl active:scale-90 transition-all backdrop-blur-md"></button>
        </div>
        <div id="image-preview" class="w-full aspect-square rounded-[2rem] relative hidden group border-2 border-slate-700 overflow-hidden shadow-2xl ring-1 ring-white/5">
            <img id="preview-img" class="w-full h-full object-cover" />
            <div class="absolute inset-0 bg-slate-950/80 text-white flex flex-col items-center justify-center opacity-0 group-hover:opacity-100 transition-all p-6 text-center backdrop-blur-sm">
                <button type="button" id="retake-btn" class="px-8 py-3 bg-white text-slate-950 rounded-2xl text-[10px] font-black uppercase tracking-[0.3em] active:scale-95 transition-transform shadow-2xl border-b-4 border-slate-300">Rescan Specimen</button>
            </div>
        </div>
    `;
    const videoEl = container.querySelector('#camera-video');
    const form = DOMElements.dishCardContainer.querySelector('#dish-form');
    let stream = null;

    container.querySelector('#camera-placeholder').onclick = async () => {
        if (form.querySelector('input').disabled) return;
        try {
            stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } });
            videoEl.srcObject = stream;
            container.querySelector('#camera-placeholder').classList.add('hidden');
            container.querySelector('#camera-view').classList.remove('hidden');
        } catch (e) { alert("Camera Access Required: " + e.message); }
    };

    container.querySelector('#capture-btn').onclick = () => {
        const canvas = document.createElement('canvas');
        canvas.width = 1024; canvas.height = 1024;
        canvas.getContext('2d').drawImage(videoEl, 0, 0, 1024, 1024);
        const dataUrl = canvas.toDataURL('image/jpeg', 0.95);
        container.querySelector('#preview-img').src = dataUrl;
        form.dataset.capturedImage = dataUrl;
        if (stream) stream.getTracks().forEach(t => t.stop());
        container.querySelector('#camera-view').classList.add('hidden');
        container.querySelector('#image-preview').classList.remove('hidden');
        handleAiCheck(dish, dataUrl);
    };

    container.querySelector('#retake-btn').onclick = () => {
        if (form.querySelector('input').disabled) return;
        container.querySelector('#image-preview').classList.add('hidden');
        container.querySelector('#camera-placeholder').classList.remove('hidden');
    };

    if (initialImage) {
        container.querySelector('#preview-img').src = initialImage;
        form.dataset.capturedImage = initialImage;
        container.querySelector('#camera-placeholder').classList.add('hidden');
        container.querySelector('#image-preview').classList.remove('hidden');
    }
}

async function handleAiCheck(dish, capturedImageDataUrl) {
    const feedbackContainer = document.getElementById('ai-feedback-container');
    feedbackContainer.innerHTML = `
        <div class="p-8 border border-indigo-500/30 bg-indigo-900/10 rounded-[2rem] flex flex-col items-center justify-center space-y-4 shadow-2xl shadow-indigo-500/5">
            <div class="relative w-8 h-8">
                <div class="absolute inset-0 border-2 border-indigo-500/20 rounded-full"></div>
                <div class="absolute inset-0 border-2 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
            </div>
            <p class="font-black text-indigo-400 text-[10px] uppercase tracking-[0.4em] animate-pulse">Running Neural Quality Probe</p>
        </div>`;

    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

        let refImgPart = null;
        try {
            const refRes = await fetch(dish.dishImage);
            if (refRes.ok) {
                const blob = await refRes.blob();
                const refBase64 = await new Promise(res => { 
                    const fr = new FileReader(); 
                    fr.onloadend = () => res(fr.result.split(',')[1]); 
                    fr.readAsDataURL(blob); 
                });
                refImgPart = { inlineData: { mimeType: 'image/jpeg', data: refBase64 } };
            }
        } catch (e) { console.warn("Reference load deficit:", e); }

        const promptText = `Execute a high-standard culinary audit for dish '${dish.dishName}'. 
        Compare visual sample against reference standard.
        Note: If the sample image is blurry or lower quality, account for this and focus on distinguishable plating patterns, component ratios, and color harmony.
        Return strictly JSON: 
        { "score": 1-10, "positives": string[], "improvements": string[], "overall_comment": string }`;

        const contentsParts = [ { text: promptText } ];
        if (refImgPart) contentsParts.push(refImgPart);
        contentsParts.push({ inlineData: { mimeType: 'image/jpeg', data: capturedImageDataUrl.split(',')[1] } });

        const result = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: { parts: contentsParts },
            config: { responseMimeType: "application/json", temperature: 0.1 }
        });

        const feedbackData = JSON.parse(result.text);
        document.getElementById('dish-form').dataset.aiFeedback = JSON.stringify(feedbackData);
        renderAiFeedback(feedbackData);
    } catch (e) { 
        console.error(e);
        feedbackContainer.innerHTML = `<div class="p-6 border border-red-900/40 bg-red-950/20 rounded-3xl text-[10px] text-red-400 font-black uppercase tracking-widest text-center shadow-xl">Audit Engine Offline — Manual Review Required</div>`; 
    }
}

function renderAiFeedback(feedbackData) {
    const container = document.getElementById('ai-feedback-container');
    if (!container || !feedbackData) return;

    const score = Math.max(1, Math.min(10, feedbackData.score || 0));
    const positives = (feedbackData.positives || []).map(p => `<li class="flex items-center gap-3"><div class="w-1.5 h-1.5 rounded-full bg-green-500 shadow-[0_0_8px_rgba(34,197,94,0.5)]"></div>${p}</li>`).join('');
    const improvements = (feedbackData.improvements || []).map(i => `<li class="flex items-center gap-3"><div class="w-1.5 h-1.5 rounded-full bg-yellow-500 shadow-[0_0_8px_rgba(234,179,8,0.5)]"></div>${i}</li>`).join('');

    container.innerHTML = `
        <div class="bg-slate-900/60 border border-slate-700/50 rounded-[2.5rem] overflow-hidden shadow-2xl ring-1 ring-white/5 animate-in slide-in-from-bottom-6 duration-500">
            <div class="px-8 py-5 flex justify-between items-center bg-slate-800 border-b border-white/5">
                <span class="text-[10px] font-black uppercase text-indigo-400 tracking-[0.3em]">AI Intelligence Feedback</span>
                <span class="text-lg font-black text-white bg-indigo-600 px-5 py-2 rounded-2xl shadow-2xl shadow-indigo-600/40 border-b-4 border-indigo-800">${score}/10</span>
            </div>
            <div class="p-8 grid grid-cols-1 sm:grid-cols-2 gap-8 text-xs">
                <div class="space-y-4">
                    <p class="font-black text-green-400 uppercase tracking-widest text-[10px] pl-2 border-l-2 border-green-500/50">Verified Compliance</p>
                    <ul class="text-slate-300 space-y-2.5 font-medium pl-1">${positives || 'Standard specifications met'}</ul>
                </div>
                <div class="space-y-4">
                    <p class="font-black text-yellow-400 uppercase tracking-widest text-[10px] pl-2 border-l-2 border-yellow-500/50">Correction Points</p>
                    <ul class="text-slate-300 space-y-2.5 font-medium pl-1">${improvements || 'Zero deficiencies'}</ul>
                </div>
            </div>
            <div class="px-8 pb-8">
                <div class="bg-slate-950/60 p-6 rounded-[1.5rem] border border-slate-800/80 shadow-inner">
                    <p class="text-xs italic text-slate-400 leading-relaxed font-medium">"${feedbackData.overall_comment}"</p>
                </div>
            </div>
        </div>
    `;
}

// --- Common Rendering Logic (Dashboard, etc) ---

function renderApp() {
    DOMElements.loadingIndicator.classList.toggle('hidden', !state.isMenuLoading && !state.isCheckDataLoading);
    DOMElements.mainView.classList.toggle('hidden', state.isMenuLoading || state.isCheckDataLoading || state.currentView !== 'dashboard');

    if (state.menu && state.menu.dishes.length > 0) {
        DOMElements.welcomePlaceholder.classList.add('hidden');
        DOMElements.dishGridContainer.classList.remove('hidden');
        DOMElements.dailySummarySection.classList.remove('hidden');
        renderDishSelectionGrid();
        renderDailySummaryTable();
    } else {
        renderWelcomePlaceholder();
        DOMElements.dailySummarySection.classList.add('hidden');
    }
    renderDateSelector();
}

function renderDateSelector() {
    const viewDate = getStartOfWeek(new Date(state.selectedDate + 'T12:00:00Z'));
    const weekDays = Array.from({ length: 5 }).map((_, i) => {
        const day = new Date(viewDate);
        day.setDate(viewDate.getDate() + i);
        return day;
    });
    DOMElements.dateButtonsContainer.innerHTML = '';
    weekDays.forEach(day => {
        const dayString = day.toISOString().split('T')[0];
        const isSelected = dayString === state.selectedDate;
        const button = document.createElement('button');
        button.className = `flex flex-col items-center justify-center w-11 h-14 sm:w-14 sm:h-16 rounded-[1.2rem] transition-all duration-300 transform active:scale-90 shadow-lg ${isSelected ? 'bg-indigo-600 text-white shadow-indigo-600/40 ring-4 ring-indigo-400/20' : 'bg-slate-800 text-slate-500 hover:text-slate-300 border border-slate-700/50'}`;
        button.innerHTML = `
            <span class="text-[9px] uppercase font-black tracking-tighter opacity-70 mb-1">${day.toLocaleDateString('en-US', { weekday: 'short' })}</span>
            <span class="text-base font-black">${day.getDate()}</span>
        `;
        button.onclick = () => {
            state.selectedDate = dayString;
            fetchCheckData();
        };
        DOMElements.dateButtonsContainer.appendChild(button);
    });
}

function renderDishSelectionGrid() {
    DOMElements.dishGridContainer.innerHTML = '';
    if (!state.menu || !state.menu.dishes) return;

    const groups = {
        cold: state.menu.dishes.filter(d => d.dishType === 'cold').sort((a,b) => a.dishLetter.localeCompare(b.dishLetter)),
        hot: state.menu.dishes.filter(d => d.dishType === 'hot').sort((a,b) => a.dishLetter.localeCompare(b.dishLetter)),
        extras: state.menu.dishes.filter(d => d.dishType !== 'cold' && d.dishType !== 'hot').sort((a,b) => a.dishLetter.localeCompare(b.dishLetter))
    };

    const themes = {
      hot: { cardBg: 'bg-slate-800/50', cardBorder: 'border-red-900/30', circleBg: 'bg-red-500', letterText: 'text-white' },
      cold: { cardBg: 'bg-slate-800/50', cardBorder: 'border-blue-900/30', circleBg: 'bg-blue-500', letterText: 'text-white' },
      default: { cardBg: 'bg-slate-800/50', cardBorder: 'border-slate-700/50', circleBg: 'bg-indigo-600', letterText: 'text-white' }
    };

    Object.keys(groups).forEach(type => {
        const list = groups[type];
        if (list.length === 0) return;

        const h = document.createElement('div');
        h.className = 'col-span-full text-[10px] font-black text-slate-500 uppercase tracking-[0.3em] mt-6 mb-2 pl-2 border-l-2 border-indigo-500/30';
        h.textContent = `${type} STATION`;
        DOMElements.dishGridContainer.appendChild(h);

        list.forEach(dish => {
            const isChecked = !!state.checkedData[dish.dishLetter];
            const theme = themes[dish.dishType] || themes.default;
            const button = document.createElement('button');
            button.className = `group relative flex flex-col items-center justify-center p-4 border rounded-[2rem] transition-all duration-300 ${theme.cardBg} ${theme.cardBorder} hover:scale-105 active:scale-95 shadow-xl hover:shadow-indigo-500/10 backdrop-blur-sm`;
            button.onclick = () => {
                state.selectedDish = dish;
                showView('detail');
                renderDishCard();
            };
            let checkHTML = isChecked ? `<div class="absolute -top-1 -right-1 bg-green-500 rounded-full p-1.5 text-white shadow-2xl ring-4 ring-slate-900 scale-100 group-hover:scale-110 transition-transform"><svg xmlns="http://www.w3.org/2000/svg" class="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="4" d="M5 13l4 4L19 7"></path></svg></div>` : '';
            button.innerHTML = `
                ${checkHTML}
                <div class="mb-3 h-12 w-12 sm:h-14 sm:w-14 rounded-full flex items-center justify-center text-sm sm:text-base font-black shadow-2xl ring-4 ring-white/5 ${theme.circleBg} ${theme.letterText} uppercase">${dish.dishLetter}</div>
                <p class="font-black text-[10px] text-slate-300 px-1 leading-tight text-center line-clamp-2 uppercase tracking-tight h-8 flex items-center group-hover:text-white transition-colors">${dish.dishName}</p>
            `;
            DOMElements.dishGridContainer.appendChild(button);
        });
    });
}

function renderDailySummaryTable() {
    if (!state.menu || !state.menu.dishes) return;
    const dishes = state.menu.dishes;
    DOMElements.dailySummaryContainer.innerHTML = '';

    const types = ['cold', 'hot', 'extras'];
    const groups = {
        cold: dishes.filter(d => d.dishType === 'cold').sort((a,b) => a.dishLetter.localeCompare(b.dishLetter)),
        hot: dishes.filter(d => d.dishType === 'hot').sort((a,b) => a.dishLetter.localeCompare(b.dishLetter)),
        extras: dishes.filter(d => d.dishType !== 'cold' && d.dishType !== 'hot').sort((a,b) => a.dishLetter.localeCompare(b.dishLetter))
    };

    types.forEach(type => {
        const list = groups[type];
        if (list.length === 0) return;

        const wrapper = document.createElement('div');
        wrapper.className = 'bg-slate-800/40 rounded-[2rem] border border-slate-700/50 overflow-hidden shadow-2xl backdrop-blur-md';

        const header = document.createElement('div');
        header.className = `px-6 py-4 text-[10px] font-black uppercase tracking-[0.2em] text-white border-b border-white/5 ${type === 'hot' ? 'bg-red-600/20' : type === 'cold' ? 'bg-blue-600/20' : 'bg-slate-700/40'}`;
        header.textContent = `${type} DISHES RECAP`;
        wrapper.appendChild(header);

        let tableHTML = `
            <div class="overflow-x-auto custom-scrollbar">
                <table class="min-w-full divide-y divide-slate-800 text-[11px]">
                    <thead class="bg-slate-950/40">
                        <tr>
                            <th scope="col" class="px-6 py-4 text-left font-black text-slate-500 uppercase tracking-widest">ID</th>
                            <th scope="col" class="px-6 py-4 text-left font-black text-slate-500 uppercase tracking-widest hidden sm:table-cell">Dish Label</th>
                            <th scope="col" class="px-6 py-4 text-left font-black text-slate-500 uppercase tracking-widest">Temp</th>
                            <th scope="col" class="px-6 py-4 text-left font-black text-slate-500 uppercase tracking-widest">Mass</th>
                            <th scope="col" class="px-6 py-4 text-left font-black text-slate-500 uppercase tracking-widest hidden sm:table-cell">Spec</th>
                            <th scope="col" class="px-6 py-4 text-left font-black text-slate-500 uppercase tracking-widest">AI</th>
                        </tr>
                    </thead>
                    <tbody class="divide-y divide-slate-800/50">
        `;

        list.forEach(dish => {
            const check = state.checkedData[dish.dishLetter];
            const isChecked = !!check;
            const vt = (check?.temperatures || []).map(t => parseFloat(t)).filter(t => !isNaN(t));
            const avgT = vt.length ? (vt.reduce((a,b)=>a+b,0)/vt.length).toFixed(1) + '°' : '-';
            const vw = (check?.weights || []).map(w => parseFloat(w)).filter(w => !isNaN(w));
            const avgW = vw.length ? (vw.reduce((a,b)=>a+b,0)/vw.length).toFixed(0) + 'g' : '-';
            const ai = check?.aiCheckResult?.score || '-';
            const target = dish.theoreticalWeight ? `${dish.theoreticalWeight.toFixed(0)}g` : '-';

            tableHTML += `
                <tr class="hover:bg-slate-700/30 cursor-pointer transition-colors ${!isChecked ? 'opacity-30' : ''}" onclick="window.handleSelectDish('${dish.dishLetter}')">
                    <td class="px-6 py-5 font-black text-indigo-400">${dish.dishLetter}</td>
                    <td class="px-6 py-5 text-slate-200 hidden sm:table-cell font-black uppercase tracking-tighter truncate max-w-[150px]">${dish.dishName}</td>
                    <td class="px-6 py-5 text-slate-300 font-mono font-black">${avgT}</td>
                    <td class="px-6 py-5 text-slate-300 font-mono font-black">${avgW}</td>
                    <td class="px-6 py-5 text-slate-600 hidden sm:table-cell italic font-mono font-bold">${target}</td>
                    <td class="px-6 py-5 font-black ${isChecked ? (ai > 7 ? 'text-green-400' : 'text-indigo-400') : 'text-slate-700'}">${ai}</td>
                </tr>
            `;
        });

        tableHTML += `</tbody></table></div>`;
        wrapper.innerHTML += tableHTML;
        DOMElements.dailySummaryContainer.appendChild(wrapper);
    });
    DOMElements.dailySummarySection.classList.toggle('hidden', dishes.length === 0);
}

window.handleSelectDish = (letter) => {
    const dish = state.menu.dishes.find(d => d.dishLetter === letter);
    if(dish) {
        state.selectedDish = dish;
        showView('detail');
        renderDishCard();
    }
}

// --- Sync Functions ---

function fetchMenu() {
    state.isMenuLoading = true;
    renderApp();
    const weekId = getWeekId(new Date(state.selectedDate + 'T12:00:00Z'));
    onValue(ref(database, `menus/${weekId}`), (snapshot) => {
        state.menu = snapshot.val() || null;
        state.isMenuLoading = false;
        renderApp();
    });
}

function fetchCheckData() {
    state.isCheckDataLoading = true;
    renderApp();
    onValue(ref(database, `quality-checks/${state.selectedDate}`), (snapshot) => {
        state.checkedData = snapshot.val() || {};
        state.isCheckDataLoading = false;
        renderApp();
    });
}

function saveCheckData(data) {
    set(ref(database, `quality-checks/${data.date}/${data.dishLetter}`), data).catch(console.error);
}

