async function fetchHistoricalDishLibrary() {
    // This fetches only the list of dishes to populate the UI quickly
    try {
        const snapshot = await get(ref(database, 'quality-checks'));
        const allData = snapshot.val() || {};
        const dishMap = new Map();

        Object.keys(allData).forEach(date => {
            Object.values(allData[date]).forEach(check => {
                if (check.dishName) {
                    if (!dishMap.has(check.dishName)) {
                        dishMap.set(check.dishName, { 
                            name: check.dishName, 
                            type: check.dishType || 'extras',
                            count: 1
                        });
                    } else {
                        dishMap.get(check.dishName).count++;
                    }
                }
            });
        });
        state.historicalDishLibrary = Array.from(dishMap.values());
    } catch (e) {
        console.error("Library fetch error:", e);
    }
}

