                             <div class="px-2 py-0.5 bg-indigo-500/10 border border-indigo-500/20 rounded text-[9px] font-black text-indigo-400 uppercase tracking-widest shadow-lg animate-pulse">Goal: ${dish.theoreticalWeight.toFixed(0)}g</div>
                        </div>
                        ${(formData.weights || ['', '', '']).map((w, i) => `<input type="text" inputmode="decimal" name="weights" value="${w}" placeholder="Sample ${i + 1}" class="block w-full px-5 py-4 bg-slate-950 border border-slate-800 rounded-2xl text-sm text-indigo-400 focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500 outline-none font-mono font-black transition-all shadow-inner">`).join('')}
                    </div>
                </div>

                <div>
                    <h4 class="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] mb-3 pl-2">Operational Observations</h4>
                    <textarea name="comment" rows="4" placeholder="Detailed notes on flavor, texture, or plating discrepancies..." class="block w-full px-5 py-4 bg-slate-950 border border-slate-800 rounded-3xl text-xs text-slate-200 focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500 outline-none resize-none transition-all shadow-inner leading-relaxed">${formData.comment || ''}</textarea>
                </div>

                <div class="pt-6 flex flex-col sm:flex-row gap-4">
                    <button type="button" id="edit-btn" class="flex-1 py-5 text-xs font-black rounded-2xl text-slate-300 border border-slate-700 hover:bg-slate-700 transition-all uppercase tracking-[0.2em] active:scale-95 shadow-xl">Unlock Entry</button>
                    <button type="submit" id="submit-btn" class="flex-[2] py-5 text-xs font-black text-white bg-indigo-600 rounded-2xl shadow-2xl shadow-indigo-600/40 hover:bg-indigo-700 transition-all uppercase tracking-[0.2em] active:scale-95 border-b-4 border-indigo-800">Complete Quality Audit</button>
                </div>
            </form>
        </div>
    `;
    renderCameraCapture(dish, formData.capturedImage);
    const form = DOMElements.dishCardContainer.querySelector('#dish-form');
    const editBtn = DOMElements.dishCardContainer.querySelector('#edit-btn');
    const submitBtn = DOMElements.dishCardContainer.querySelector('#submit-btn');
    const inputs = form.querySelectorAll('input, textarea');

    const setFormDisabled = (disabled) => {
        inputs.forEach(el => el.disabled = disabled);
        editBtn.classList.toggle('hidden', !disabled);
        submitBtn.classList.toggle('hidden', disabled);
    };

    editBtn.onclick = () => setFormDisabled(false);

    form.onsubmit = (e) => {
        e.preventDefault();
        const data = new FormData(e.target);
        saveCheckData({
            dishLetter: dish.dishLetter,
            dishName: dish.dishName,
            dishType: dish.dishType,
            date: state.selectedDate,
            capturedImage: e.target.dataset.capturedImage || null,
            selectedIngredients: data.getAll('selectedIngredients'),
            temperatures: data.getAll('temperatures'), 
            weights: data.getAll('weights'),
            comment: data.get('comment'), 
            aiCheckResult: e.target.dataset.aiFeedback ? JSON.parse(e.target.dataset.aiFeedback) : null,
            timestamp: new Date().toISOString(),
        });
        showView('dashboard');
    };

    setFormDisabled(!isEditing);
    if (formData.aiCheckResult) renderAiFeedback(formData.aiCheckResult);
}

// --- Export Image Logic (Laptop optimized) ---

async function exportRecapAsImage() {
    const container = DOMElements.dailySummaryContainer;
    if (!container || !container.children.length) {
        alert("No recap data available for export.");
        return;
    }

    DOMElements.exportStatus.classList.remove('hidden');
    DOMElements.exportRecapBtn.disabled = true;

    try {
        // Toggle export mode to ensure background is solid and layout is wide for laptop feel
        container.classList.add('export-mode');

        const canvas = await html2canvas(container, {
            backgroundColor: '#0f172a',
            scale: 2, // Higher resolution
            logging: false,
            useCORS: true
        });

        container.classList.remove('export-mode');

        const image = canvas.toDataURL("image/png");
        const link = document.createElement('a');
        link.download = `Quality_Recap_${state.selectedDate}.png`;
        link.href = image;
        link.click();
    } catch (e) {
        console.error("Export failed:", e);
        alert("Recap export failed. Check browser permissions.");
    } finally {
        DOMElements.exportStatus.classList.add('hidden');
        DOMElements.exportRecapBtn.disabled = false;
    }
}

DOMElements.exportRecapBtn.onclick = exportRecapAsImage;

