        </div>
    `;

    const allDishes = await fetchHistoricalDishLibrary();

    if (allDishes.length === 0) {
        DOMElements.auditResultsContainer.innerHTML = `<div class="p-16 text-center bg-slate-800/30 rounded-3xl border-2 border-dashed border-slate-800"><p class="text-xs text-slate-500 font-bold uppercase tracking-widest">Master Audit History is currently empty.</p></div>`;
        return;
    }

    const hot = allDishes.filter(d => d.type === 'hot').sort((a,b) => a.name.localeCompare(b.name));
