    let html = `<div class="space-y-12 animate-in fade-in duration-500">`;

    const renderSection = (list, title, colorClass) => {
        if (list.length === 0) return '';
        return `
            <div>
                <div class="flex items-center gap-3 mb-4 px-1 border-b border-slate-800 pb-2">
                    <div class="h-2 w-2 rounded-full ${colorClass}"></div>
