// --- Utility Functions ---
const getWeekId = (date) => {
    const d = new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()));
    d.setUTCDate(d.getUTCDate() + 4 - (d.getUTCDay() || 7));
    const yearStart = new Date(Date.UTC(d.getUTCFullYear(), 0, 1));
    const weekNo = Math.ceil((((d.getTime() - yearStart.getTime()) / 86400000) + 1) / 7);
    return `${d.getUTCFullYear()}-${String(weekNo).padStart(2, '0')}`;
};

const getStartOfWeek = (date) => {
    const d = new Date(date);
    const day = d.getDay();
    const diff = d.getDate() - day + (day === 0 ? -6 : 1);
    return new Date(d.setDate(diff));
};

// --- Recap Image Export ---
async function exportRecapAsImage() {
    const container = DOMElements.dailySummaryContainer;
    if (!container || !container.children.length) {
        alert("No quality data recorded for this date.");
        return;
    }

    DOMElements.exportStatus.classList.remove('hidden');
    DOMElements.exportRecapBtn.disabled = true;

    try {
        // Prepare for capture: ensure all tables are expanded and styled for high contrast
        container.classList.add('export-mode');

        // Brief delay for CSS layout transition
        await new Promise(resolve => setTimeout(resolve, 500));

        const canvas = await html2canvas(container, {
            backgroundColor: '#0f172a',
            scale: 2, // 2x resolution for crispness
            logging: false,
            useCORS: true,
            windowWidth: 1280 // Standard laptop width
        });

        container.classList.remove('export-mode');

        const image = canvas.toDataURL("image/png");
        const link = document.createElement('a');
        link.download = `Culinary_Recap_${state.selectedDate}.png`;
        link.href = image;
        link.click();
    } catch (e) {
        console.error("Export Error:", e);
        alert("Recap export failed. Ensure all images are loaded.");
    } finally {
        DOMElements.exportStatus.classList.add('hidden');
        DOMElements.exportRecapBtn.disabled = false;
    }
}

