            <p class="text-[10px] font-black text-slate-500 uppercase tracking-widest animate-pulse">Synchronizing Master Library</p>
        </div>
    `;

    const allDishes = await fetchHistoricalDishLibrary();

    if (allDishes.length === 0) {
        DOMElements.auditResultsContainer.innerHTML = `
            <div class="p-20 text-center bg-slate-800/30 rounded-[3rem] border-2 border-dashed border-slate-800">
                <p class="text-xs text-slate-500 font-bold uppercase tracking-widest">Master history is empty. Start recording checks to build the library.</p>
