                    <div class="h-2.5 w-2.5 rounded-full ${colorClass} shadow-xl"></div>
                    <h3 class="text-[10px] font-black text-slate-400 uppercase tracking-[0.25em]">${title}</h3>
                </div>
                <div class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3">
                    ${list.map(d => `
                        <button onclick="window.runAuditForDish('${d.name.replace(/'/g, "\\'")}')" class="group relative flex flex-col p-5 bg-slate-800/40 border border-slate-700/50 rounded-[1.5rem] hover:border-indigo-500/50 hover:bg-slate-800 transition-all text-left shadow-lg active:scale-[0.98]">
