        `;
    };

    html += renderSection(hot, 'Hot Cuisine Global History', 'bg-red-500');
    html += renderSection(cold, 'Cold Cuisine Global History', 'bg-blue-500');
    html += renderSection(extras, 'Additional Item Logs', 'bg-slate-500');
    html += `</div>`;

    DOMElements.auditResultsContainer.innerHTML = html;
}

