async function handleAiCheck(dish, capturedImageDataUrl) {
    const feedbackContainer = document.getElementById('ai-feedback-container');
    feedbackContainer.innerHTML = `
        <div class="p-8 border border-indigo-500/30 bg-indigo-900/10 rounded-[2.5rem] flex flex-col items-center justify-center space-y-4 shadow-2xl">
            <div class="relative w-8 h-8">
                 <div class="absolute inset-0 border-2 border-indigo-500/20 rounded-full"></div>
                 <div class="absolute inset-0 border-2 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
            </div>
            <p class="font-black text-indigo-400 text-[10px] uppercase tracking-[0.4em] animate-pulse">Neural Quality Audit In-Progress</p>
        </div>`;

    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

        let refImgPart = null;
        try {
            const refRes = await fetch(dish.dishImage);
            if (refRes.ok) {
                const blob = await refRes.blob();
                const refBase64 = await new Promise(res => { 
                    const fr = new FileReader(); 
                    fr.onloadend = () => res(fr.result.split(',')[1]); 
                    fr.readAsDataURL(blob); 
                });
                refImgPart = { inlineData: { mimeType: 'image/jpeg', data: refBase64 } };
            }
        } catch (e) { console.warn("Reference unavailable:", e); }

        const promptText = `Conduct a precision culinary quality audit for '${dish.dishName}'. 

        CRITICAL INSTRUCTIONS:
        1. Compare 'Captured Sample' visually with 'Standard Reference'.
        2. Note: The provided reference or capture may be of slightly lower quality/blurry. Factor this into your reasoning.
        3. Prioritize: Component placement, topological distribution, color balance, and volumetric accuracy over fine pixel detail.
        4. Detect missing ingredients from the assembly checklist if possible.

        Output Strictly JSON: 
        { "score": 1-10, "positives": string[], "improvements": string[], "overall_comment": string }`;

        const contentsParts = [ { text: promptText } ];
        if (refImgPart) contentsParts.push(refImgPart);
        contentsParts.push({ inlineData: { mimeType: 'image/jpeg', data: capturedImageDataUrl.split(',')[1] } });

        const result = await ai.models.generateContent({
            model: 'gemini-3-pro-preview', // Enhanced precision model
            contents: { parts: contentsParts },
            config: { responseMimeType: "application/json", temperature: 0.1 }
        });

        const feedbackData = JSON.parse(result.text);
        document.getElementById('dish-form').dataset.aiFeedback = JSON.stringify(feedbackData);
        renderAiFeedback(feedbackData);
    } catch (e) { 
        console.error("AI Check Error:", e);
        feedbackContainer.innerHTML = `<div class="p-6 border border-red-900/40 bg-red-950/20 rounded-3xl text-[10px] text-red-400 font-black uppercase text-center shadow-xl">Audit Engine Disconnected</div>`; 
    }
}

function renderAiFeedback(feedbackData) {
    const container = document.getElementById('ai-feedback-container');
    if (!container || !feedbackData) return;

    const score = Math.max(1, Math.min(10, feedbackData.score || 0));
    const positives = (feedbackData.positives || []).map(p => `<li class="flex items-center gap-2"><div class="h-1.5 w-1.5 rounded-full bg-green-500"></div>${p}</li>`).join('');
    const improvements = (feedbackData.improvements || []).map(i => `<li class="flex items-center gap-2"><div class="h-1.5 w-1.5 rounded-full bg-yellow-500"></div>${i}</li>`).join('');

    container.innerHTML = `
        <div class="bg-slate-900/60 border border-slate-700/50 rounded-[2.5rem] overflow-hidden shadow-2xl animate-in slide-in-from-bottom-6 duration-500">
            <div class="px-8 py-5 flex justify-between items-center bg-slate-800 border-b border-white/5">
                <span class="text-[10px] font-black uppercase text-indigo-400 tracking-[0.3em]">AI Quality Index</span>
                <span class="text-xl font-black text-white bg-indigo-600 px-6 py-2 rounded-2xl shadow-xl border-b-4 border-indigo-800">${score}/10</span>
            </div>
            <div class="p-8 grid grid-cols-1 sm:grid-cols-2 gap-8 text-xs">
                <div>
                    <p class="font-black text-green-400 uppercase tracking-widest text-[10px] mb-3 border-l-2 border-green-500/50 pl-2">Verified Attributes</p>
                    <ul class="text-slate-300 space-y-2 font-medium">${positives || 'Standard met'}</ul>
                </div>
                <div>
                    <p class="font-black text-yellow-400 uppercase tracking-widest text-[10px] mb-3 border-l-2 border-yellow-500/50 pl-2">Optimization Points</p>
                    <ul class="text-slate-300 space-y-2 font-medium">${improvements || 'Zero deficiencies'}</ul>
                </div>
            </div>
            <div class="px-8 pb-8">
                <div class="bg-slate-950/60 p-6 rounded-[1.5rem] border border-slate-800/80 shadow-inner">
                    <p class="text-xs italic text-slate-400 leading-relaxed font-medium">"${feedbackData.overall_comment}"</p>
                </div>
