    const formData = savedData || { capturedImage: null, selectedIngredients: [], temperatures: ['', '', ''], weights: ['', '', ''], comment: '', aiCheckResult: null, timestamp: null };
    const headerBgClass = dish.dishType === 'hot' ? 'bg-red-600/20' : dish.dishType === 'cold' ? 'bg-blue-600/20' : 'bg-indigo-600/20';

    DOMElements.dishCardContainer.innerHTML = `
        <div class="bg-slate-800/60 rounded-[2.5rem] shadow-2xl overflow-hidden border border-slate-700/50 backdrop-blur-xl animate-in fade-in zoom-in-95 duration-300">
