                            <label class="flex items-center justify-between p-4 rounded-2xl bg-slate-800 border border-slate-700 cursor-pointer hover:border-indigo-500/50 transition-all active:scale-[0.97] group">
                                <div class="flex items-center gap-3 overflow-hidden">
                                    <input type="checkbox" name="selectedIngredients" value="${ing.name}" class="h-4 w-4 text-indigo-500 bg-slate-950 border-slate-700 rounded ring-offset-slate-900 focus:ring-indigo-500" ${(formData.selectedIngredients || []).includes(ing.name) ? 'checked' : ''}>
