            `;
            DOMElements.dishGridContainer.appendChild(button);
        });
    });
}

function renderDailySummaryTable() {
    if (!state.menu || !state.menu.dishes) return;
    const dishes = state.menu.dishes;
    DOMElements.dailySummaryContainer.innerHTML = '';

    // Grouping logic for split recap image
    const coldList = dishes.filter(d => d.dishType === 'cold').sort((a,b) => a.dishLetter.localeCompare(b.dishLetter));
    const hotList = dishes.filter(d => d.dishType === 'hot').sort((a,b) => a.dishLetter.localeCompare(b.dishLetter));
    const extrasList = dishes.filter(d => d.dishType !== 'cold' && d.dishType !== 'hot').sort((a,b) => a.dishLetter.localeCompare(b.dishLetter));

    const renderTableBlock = (list, type) => {
        if (list.length === 0) return '';
        const wrapper = document.createElement('div');
        wrapper.className = 'bg-slate-800/40 rounded-[3rem] border border-slate-700/50 overflow-hidden shadow-2xl backdrop-blur-xl mb-8';

        const header = document.createElement('div');
        const headerColor = type === 'hot' ? 'bg-red-600/30' : type === 'cold' ? 'bg-blue-600/30' : 'bg-slate-700/50';
        header.className = `px-8 py-5 text-[11px] font-black uppercase tracking-[0.3em] text-white border-b border-white/5 ${headerColor}`;
        header.textContent = `${type} PRODUCTION UNITS`;
        wrapper.appendChild(header);

        let tableHTML = `
            <div class="overflow-x-auto custom-scrollbar">
                <table class="min-w-full divide-y divide-slate-800 text-[12px]">
                    <thead class="bg-slate-950/60">
                        <tr>
                            <th scope="col" class="px-8 py-5 text-left font-black text-slate-500 uppercase tracking-widest">ID</th>
                            <th scope="col" class="px-8 py-5 text-left font-black text-slate-500 uppercase tracking-widest">Variant Name</th>
                            <th scope="col" class="px-8 py-5 text-left font-black text-slate-500 uppercase tracking-widest">°C</th>
                            <th scope="col" class="px-8 py-5 text-left font-black text-slate-500 uppercase tracking-widest">Mass</th>
                            <th scope="col" class="px-8 py-5 text-left font-black text-slate-500 uppercase tracking-widest">Index</th>
                        </tr>
                    </thead>
                    <tbody class="divide-y divide-slate-800/50">
        `;

        list.forEach(dish => {
            const check = state.checkedData[dish.dishLetter];
            const isChecked = !!check;
            const vt = (check?.temperatures || []).map(t => parseFloat(t)).filter(t => !isNaN(t));
            const avgT = vt.length ? (vt.reduce((a,b)=>a+b,0)/vt.length).toFixed(1) + '°' : '-';
            const vw = (check?.weights || []).map(w => parseFloat(w)).filter(w => !isNaN(w));
            const avgW = vw.length ? (vw.reduce((a,b)=>a+b,0)/vw.length).toFixed(0) + 'g' : '-';
            const ai = check?.aiCheckResult?.score || '-';

            tableHTML += `
                <tr class="hover:bg-slate-700/40 cursor-pointer transition-colors ${!isChecked ? 'opacity-30' : ''}" onclick="window.handleSelectDish('${dish.dishLetter}')">
                    <td class="px-8 py-6 font-black text-indigo-400">${dish.dishLetter}</td>
                    <td class="px-8 py-6 text-slate-200 font-black uppercase tracking-tight italic truncate max-w-[180px]">${dish.dishName}</td>
                    <td class="px-8 py-6 text-slate-300 font-mono font-black text-sm">${avgT}</td>
                    <td class="px-8 py-6 text-slate-300 font-mono font-black text-sm">${avgW}</td>
                    <td class="px-8 py-6 font-black text-sm ${isChecked ? (ai > 7 ? 'text-green-400' : 'text-indigo-400') : 'text-slate-700'}">${ai}</td>
                </tr>
            `;
        });

        tableHTML += `</tbody></table></div>`;
        wrapper.innerHTML += tableHTML;
        DOMElements.dailySummaryContainer.appendChild(wrapper);
    };

    renderTableBlock(coldList, 'cold');
    renderTableBlock(hotList, 'hot');
    renderTableBlock(extrasList, 'additional');
}

