// --- Utility Functions ---
const getWeekId = (date) => {
    const d = new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()));
    d.setUTCDate(d.getUTCDate() + 4 - (d.getUTCDay() || 7));
    const yearStart = new Date(Date.UTC(d.getUTCFullYear(), 0, 1));
    const weekNo = Math.ceil((((d.getTime() - yearStart.getTime()) / 86400000) + 1) / 7);
    return `${d.getUTCFullYear()}-${String(weekNo).padStart(2, '0')}`;
};

const getStartOfWeek = (date) => {
    const d = new Date(date);
    const day = d.getDay();
    const diff = d.getDate() - day + (day === 0 ? -6 : 1);
    return new Date(d.setDate(diff));
};

// --- Historical Audit Analytics ---
async function fetchHistoricalDishLibrary() {
    try {
        const snapshot = await get(ref(database, 'quality-checks'));
        const allData = snapshot.val() || {};
        const dishMap = new Map();

        // Iterate through all recorded dates in quality-checks history
        Object.keys(allData).forEach(date => {
            const checksForDate = allData[date];
            Object.values(checksForDate).forEach(check => {
                if (check.dishName) {
                    if (!dishMap.has(check.dishName)) {
                        dishMap.set(check.dishName, { 
                            name: check.dishName, 
                            type: check.dishType || 'extras',
                            count: 1
                        });
                    } else {
                        dishMap.get(check.dishName).count++;
                    }
                }
            });
        });
        state.historicalDishLibrary = Array.from(dishMap.values());
        return state.historicalDishLibrary;
    } catch (e) {
        console.error("History fetch deficit:", e);
        return [];
    }
}

