// --- Utility Functions ---
const getWeekId = (date) => {
    const d = new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()));
    d.setUTCDate(d.getUTCDate() + 4 - (d.getUTCDay() || 7));
    const yearStart = new Date(Date.UTC(d.getUTCFullYear(), 0, 1));
    const weekNo = Math.ceil((((d.getTime() - yearStart.getTime()) / 86400000) + 1) / 7);
    return `${d.getUTCFullYear()}-${String(weekNo).padStart(2, '0')}`;
};

const getStartOfWeek = (date) => {
    const d = new Date(date);
    const day = d.getDay();
    const diff = d.getDate() - day + (day === 0 ? -6 : 1);
    return new Date(d.setDate(diff));
};

// --- Historical Audit Analytics & Master Registry ---
async function fetchHistoricalDishLibrary() {
    try {
        // We pull from dish-registry to ensure we see ALL dishes ever entered into the system
        const registrySnapshot = await get(ref(database, 'dish-registry'));
        const registry = registrySnapshot.val() || {};

        // We also pull quality-checks to count actual sample size
        const checksSnapshot = await get(ref(database, 'quality-checks'));
        const allChecks = checksSnapshot.val() || {};

        const counts = {};
        Object.keys(allChecks).forEach(date => {
            Object.values(allChecks[date]).forEach(check => {
                if (check.dishName) {
                    counts[check.dishName] = (counts[check.dishName] || 0) + 1;
                }
            });
        });

        state.historicalDishLibrary = Object.values(registry).map(dish => ({
            name: dish.name,
            type: dish.type,
            count: counts[dish.name] || 0
        })).sort((a,b) => a.name.localeCompare(b.name));

        return state.historicalDishLibrary;
    } catch (e) {
        console.error("Registry fetch deficit:", e);
        return [];
    }
}

