                 <div class="absolute inset-0 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
            </div>
            <p class="font-black text-indigo-400 text-[11px] uppercase tracking-[0.5em] animate-pulse">Neural Quality Inspection Phase</p>
        </div>`;

    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

        let refImgPart = null;
        try {
            const refRes = await fetch(dish.dishImage);
            if (refRes.ok) {
                const blob = await refRes.blob();
                const refBase64 = await new Promise(res => { 
                    const fr = new FileReader(); 
                    fr.onloadend = () => res(fr.result.split(',')[1]); 
                    fr.readAsDataURL(blob); 
                });
                refImgPart = { inlineData: { mimeType: 'image/jpeg', data: refBase64 } };
            }
        } catch (e) { console.warn("Reference load deficit:", e); }

        const promptText = `Execute a precision culinary quality audit for '${dish.dishName}'. Output strictly JSON: { "score": 1-10, "positives": string[], "improvements": string[], "overall_comment": string }`;
        const contentsParts = [ { text: promptText } ];
        if (refImgPart) contentsParts.push(refImgPart);
        contentsParts.push({ inlineData: { mimeType: 'image/jpeg', data: capturedImageDataUrl.split(',')[1] } });

        const result = await ai.models.generateContent({
            model: 'gemini-3-pro-preview', 
            contents: { parts: contentsParts },
            config: { responseMimeType: "application/json", temperature: 0.1 }
        });

        const feedbackData = JSON.parse(result.text);
        const form = document.getElementById('dish-form');
        if (form) form.dataset.aiFeedback = JSON.stringify(feedbackData);
        renderAiFeedback(feedbackData);
    } catch (e) { 
        console.error("AI Fault:", e);
        feedbackContainer.innerHTML = `<div class="p-8 border border-red-900/40 bg-red-950/30 rounded-[2rem] text-[11px] text-red-400 font-black uppercase tracking-widest text-center shadow-xl">Precision Engine Offline</div>`; 
    }
}

function renderAiFeedback(feedbackData) {
    const container = document.getElementById('ai-feedback-container');
    if (!container || !feedbackData) return;

    const score = Math.max(1, Math.min(10, feedbackData.score || 0));
    const positives = (feedbackData.positives || []).map(p => `<li class="flex items-center gap-3"><div class="h-2 w-2 rounded-full bg-green-500 shadow-lg shadow-green-500/30"></div>${p}</li>`).join('');
    const improvements = (feedbackData.improvements || []).map(i => `<li class="flex items-center gap-3"><div class="h-2 w-2 rounded-full bg-yellow-500 shadow-lg shadow-yellow-500/30"></div>${i}</li>`).join('');

    container.innerHTML = `
        <div class="bg-slate-900/80 border border-slate-700/50 rounded-[3rem] overflow-hidden shadow-2xl animate-in slide-in-from-bottom-8 duration-700 backdrop-blur-xl">
            <div class="px-10 py-6 flex justify-between items-center bg-slate-800/80 border-b border-white/5">
                <span class="text-[11px] font-black uppercase text-indigo-400 tracking-[0.4em]">Neural Insight Summary</span>
                <span class="text-2xl font-black text-white bg-indigo-600 px-8 py-3 rounded-2xl shadow-2xl shadow-indigo-600/30 border-b-4 border-indigo-800 italic">${score}/10</span>
            </div>
            <div class="p-10 grid grid-cols-1 sm:grid-cols-2 gap-10 text-xs">
                <div><p class="font-black text-green-400 uppercase tracking-[0.2em] mb-4">Compliance Met</p><ul class="text-slate-300 space-y-3">${positives || 'Blueprint confirmed'}</ul></div>
                <div><p class="font-black text-yellow-400 uppercase tracking-[0.2em] mb-4">Optimal Gains</p><ul class="text-slate-300 space-y-3">${improvements || 'Zero deficiencies'}</ul></div>
            </div>
            <div class="px-10 pb-10"><div class="bg-slate-950/80 p-8 rounded-[2rem] border border-slate-800"><p class="text-xs italic text-slate-400 leading-relaxed">"${feedbackData.overall_comment}"</p></div></div>
        </div>
    `;
}

// --- Dashboard & Summary Rendering ---
function renderApp() {
    DOMElements.loadingIndicator.classList.toggle('hidden', !state.isMenuLoading && !state.isCheckDataLoading);
    DOMElements.mainView.classList.toggle('hidden', state.isMenuLoading || state.isCheckDataLoading || state.currentView !== 'dashboard');
    if (state.menu && state.menu.dishes.length > 0) {
        DOMElements.welcomePlaceholder.classList.add('hidden');
        DOMElements.dishGridContainer.classList.remove('hidden');
        DOMElements.dailySummarySection.classList.remove('hidden');
        renderDishSelectionGrid();
        renderDailySummaryTable();
    } else {
        renderWelcomePlaceholder();
        DOMElements.dailySummarySection.classList.add('hidden');
    }
    renderDateSelector();
}

function renderDateSelector() {
    const viewDate = getStartOfWeek(new Date(state.selectedDate + 'T12:00:00Z'));
    const weekDays = Array.from({ length: 5 }).map((_, i) => {
        const day = new Date(viewDate);
        day.setDate(viewDate.getDate() + i);
        return day;
    });
    DOMElements.dateButtonsContainer.innerHTML = '';
    weekDays.forEach(day => {
        const dayString = day.toISOString().split('T')[0];
        const isSelected = dayString === state.selectedDate;
        const button = document.createElement('button');
        button.className = `flex flex-col items-center justify-center w-12 h-16 sm:w-16 sm:h-20 rounded-[1.5rem] transition-all duration-300 transform active:scale-90 shadow-2xl ${isSelected ? 'bg-indigo-600 text-white shadow-indigo-600/40 ring-4 ring-indigo-400/20' : 'bg-slate-800/80 text-slate-500 hover:text-slate-200 border border-slate-700/50'}`;
        button.innerHTML = `<span class="text-[10px] uppercase font-black opacity-70 mb-1">${day.toLocaleDateString('en-US', { weekday: 'short' })}</span><span class="text-lg font-black">${day.getDate()}</span>`;
        button.onclick = () => { state.selectedDate = dayString; fetchCheckData(); };
        DOMElements.dateButtonsContainer.appendChild(button);
    });
}

function renderDishSelectionGrid() {
    DOMElements.dishGridContainer.innerHTML = '';
    const groups = {
        cold: state.menu.dishes.filter(d => d.dishType === 'cold'),
        hot: state.menu.dishes.filter(d => d.dishType === 'hot'),
        extras: state.menu.dishes.filter(d => d.dishType !== 'cold' && d.dishType !== 'hot')
    };
    const themes = { hot: 'bg-red-500', cold: 'bg-blue-500', default: 'bg-indigo-600' };

    Object.keys(groups).forEach(type => {
        const list = groups[type];
        if (list.length === 0) return;
        const h = document.createElement('div');
        h.className = 'col-span-full text-[11px] font-black text-slate-500 uppercase tracking-[0.4em] mt-8 mb-3 pl-3 border-l-4 border-indigo-500/30';
        h.textContent = `${type} BLOCK`;
        DOMElements.dishGridContainer.appendChild(h);
        list.forEach(dish => {
            const isChecked = !!state.checkedData[dish.dishLetter];
            const circleColor = themes[dish.dishType] || themes.default;
            const button = document.createElement('button');
            button.className = `group relative flex flex-col items-center justify-center p-6 border border-slate-700/50 rounded-[2.5rem] bg-slate-800/50 hover:scale-105 active:scale-95 shadow-2xl backdrop-blur-md transition-all duration-300`;
            button.onclick = () => { state.selectedDish = dish; showView('detail'); renderDishCard(); };
            button.innerHTML = `
                ${isChecked ? '<div class="absolute -top-2 -right-2 bg-green-500 rounded-full p-2 text-white shadow-2xl ring-4 ring-slate-900"><svg xmlns="http://www.w3.org/2000/svg" class="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="5" d="M5 13l4 4L19 7"></path></svg></div>' : ''}
                <div class="mb-4 h-14 w-14 rounded-[1.5rem] flex items-center justify-center text-lg font-black shadow-2xl ${circleColor} text-white uppercase italic">${dish.dishLetter}</div>
                <p class="font-black text-[11px] text-slate-300 px-2 text-center line-clamp-2 uppercase h-10 flex items-center group-hover:text-white">${dish.dishName}</p>`;
            DOMElements.dishGridContainer.appendChild(button);
        });
    });
}

function renderDailySummaryTable() {
    if (!state.menu || !state.menu.dishes) return;
    const dishes = state.menu.dishes;
    const createTableHTML = (list, type) => {
        if (list.length === 0) return '';
        const headerColor = type === 'hot' ? 'bg-red-600/30' : type === 'cold' ? 'bg-blue-600/30' : 'bg-slate-700/50';
        return `
            <div class="bg-slate-800/40 rounded-[2.5rem] border border-slate-700/50 overflow-hidden shadow-2xl backdrop-blur-xl h-full flex flex-col">
                <div class="px-8 py-5 text-[11px] font-black uppercase tracking-[0.3em] text-white border-b border-white/5 ${headerColor}">${type} Production Status</div>
                <div class="overflow-x-auto custom-scrollbar flex-grow">
                    <table class="min-w-full divide-y divide-slate-800 text-[11px]">
                        <thead class="bg-slate-950/60">
                            <tr>
                                <th class="px-6 py-4 text-left font-black text-slate-500 uppercase">ID</th>
                                <th class="px-6 py-4 text-left font-black text-slate-500 uppercase">Variant</th>
                                <th class="px-6 py-4 text-left font-black text-slate-500 uppercase">°C</th>
                                <th class="px-6 py-4 text-left font-black text-slate-500 uppercase">Mass</th>
                                <th class="px-6 py-4 text-left font-black text-slate-500 uppercase">Target</th>
                                <th class="px-6 py-4 text-left font-black text-slate-500 uppercase">AI</th>
                            </tr>
                        </thead>
                        <tbody class="divide-y divide-slate-800/50">
                            ${list.map(dish => {
                                const check = state.checkedData[dish.dishLetter];
                                const isChecked = !!check;
                                const vt = (check?.temperatures || []).map(t => parseFloat(t)).filter(t => !isNaN(t));
                                const avgT = vt.length ? (vt.reduce((a,b)=>a+b,0)/vt.length).toFixed(1) + '°' : '-';
                                const vw = (check?.weights || []).map(w => parseFloat(w)).filter(w => !isNaN(w));
                                const avgW = vw.length ? (vw.reduce((a,b)=>a+b,0)/vw.length).toFixed(0) + 'g' : '-';
                                const ai = check?.aiCheckResult?.score || '-';
                                const targetWeight = dish.theoreticalWeight ? `${dish.theoreticalWeight.toFixed(0)}g` : '-';
                                return `<tr class="hover:bg-slate-700/40 cursor-pointer transition-colors ${!isChecked ? 'opacity-25' : ''}" onclick="window.handleSelectDish('${dish.dishLetter}')">
                                    <td class="px-6 py-5 font-black text-indigo-400">${dish.dishLetter}</td>
                                    <td class="px-6 py-5 text-slate-200 font-black uppercase truncate max-w-[140px]">${dish.dishName}</td>
                                    <td class="px-6 py-5 text-slate-300 font-mono">${avgT}</td>
                                    <td class="px-6 py-5 text-slate-300 font-mono">${avgW}</td>
                                    <td class="px-6 py-5 text-slate-500 font-mono italic">${targetWeight}</td>
                                    <td class="px-6 py-5 font-black ${isChecked ? (ai > 7 ? 'text-green-400' : 'text-indigo-400') : 'text-slate-700'}">${ai}</td>
                                </tr>`;
                            }).join('')}
                        </tbody>
                    </table>
                </div>
            </div>`;
    };
    let splitHtml = `<div id="cold-summary">${createTableHTML(dishes.filter(d => d.dishType === 'cold'), 'cold')}</div><div id="hot-summary">${createTableHTML(dishes.filter(d => d.dishType === 'hot'), 'hot')}</div>`;
    const extras = dishes.filter(d => d.dishType !== 'cold' && d.dishType !== 'hot');
    if (extras.length > 0) splitHtml += `<div class="full-width-section">${createTableHTML(extras, 'additional')}</div>`;
    DOMElements.dailySummaryContainer.innerHTML = splitHtml;
}

