        ).join('\n') : "No recorded quality checks found for this unit.";

        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const response = await ai.models.generateContent({
            model: 'gemini-3-pro-preview', 
            contents: `Execute a multi-week culinary audit for "${dishName}". 

            History:
            ${feedbackSummaries}

            Goal: Identify performance trends, "What's Good", "Needs Improvement", and "Significant Historical Shifts" (e.g., if quality dipped or improved significantly during a specific timeframe).

