            datasets: [{
                data: scores.length > 0 ? scores : [0],
                borderColor: '#6366f1',
                borderWidth: 4,
                tension: 0.4,
                pointRadius: 6,
                pointBackgroundColor: '#6366f1',
                pointHoverRadius: 8,
