// --- Utility Functions ---
const getWeekId = (date) => {
    const d = new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()));
    d.setUTCDate(d.getUTCDate() + 4 - (d.getUTCDay() || 7));
    const yearStart = new Date(Date.UTC(d.getUTCFullYear(), 0, 1));
    const weekNo = Math.ceil((((d.getTime() - yearStart.getTime()) / 86400000) + 1) / 7);
    return `${d.getUTCFullYear()}-${String(weekNo).padStart(2, '0')}`;
};

const getStartOfWeek = (date) => {
    const d = new Date(date);
    const day = d.getDay();
    const diff = d.getDate() - day + (day === 0 ? -6 : 1);
    return new Date(d.setDate(diff));
};

// --- Historical Audit Analytics ---
async function fetchHistoricalDishLibrary() {
    try {
        // Deep scan of ALL quality checks to find every unique dish name recorded in history
        const checksSnapshot = await get(ref(database, 'quality-checks'));
        const allChecks = checksSnapshot.val() || {};

        const dishMap = new Map();

        // Iterate through all dates
        Object.keys(allChecks).forEach(date => {
            const dayChecks = allChecks[date];
            // Iterate through all dishes on that date
            Object.values(dayChecks).forEach(check => {
                if (check.dishName) {
                    if (!dishMap.has(check.dishName)) {
                        dishMap.set(check.dishName, {
                            name: check.dishName,
                            type: check.dishType || 'extras',
                            count: 1
                        });
                    } else {
                        dishMap.get(check.dishName).count++;
                    }
                }
            });
        });

        // Also merge with registry to ensure newly added (but not yet checked) dishes appear
        const registrySnapshot = await get(ref(database, 'dish-registry'));
        const registry = registrySnapshot.val() || {};
        Object.values(registry).forEach(dish => {
            if (!dishMap.has(dish.name)) {
                dishMap.set(dish.name, { name: dish.name, type: dish.type, count: 0 });
            }
        });

        state.historicalDishLibrary = Array.from(dishMap.values()).sort((a,b) => a.name.localeCompare(b.name));
        return state.historicalDishLibrary;
    } catch (e) {
        console.error("Historical discovery deficit:", e);
        return [];
    }
}

