            config: { responseMimeType: "application/json", temperature: 0.1 }
        });

        const auditData = JSON.parse(response.text);
        renderAuditReport(auditData, historicalChecks, dishName);

    } catch (e) {
        console.error(e);
        DOMElements.auditResultsContainer.innerHTML = `<div class="p-10 bg-red-950/20 border border-red-900/40 rounded-[2.5rem] text-center"><p class="text-xs text-red-400 font-black uppercase tracking-widest">Neural Logic Conflict. Please retry.</p><button onclick="renderAuditDishLibrary()" class="mt-8 px-8 py-3 bg-slate-800 rounded-2xl text-[10px] font-black uppercase text-white hover:bg-slate-700">Return to Archive</button></div>`;
    }
};

