            </div>
            <div class="text-center">
                <p class="text-[11px] font-black text-indigo-400 uppercase tracking-[0.6em] animate-pulse mb-4">Synthesizing Historical Matrix</p>
                <h3 class="text-sm text-slate-400 font-black uppercase tracking-widest px-8 italic border-b border-indigo-500/30 pb-2 mx-auto max-w-fit">"${dishName}"</h3>
            </div>
        </div>
    `;

    try {
        const snapshot = await get(ref(database, 'quality-checks'));
        const allData = snapshot.val() || {};
        const historicalChecks = [];

        Object.keys(allData).forEach(date => {
            Object.values(allData[date]).forEach(check => {
                if (check.dishName === dishName) historicalChecks.push({ date, ...check });
            });
        });

        // Sort by timestamp to find trajectory
        historicalChecks.sort((a,b) => (a.timestamp || "").localeCompare(b.timestamp || ""));

        // Pre-calculate actual consistency score to ensure it matches the graph
        const actualScores = historicalChecks.map(c => c.aiCheckResult?.score).filter(s => typeof s === 'number');
        const calculatedStability = actualScores.length ? (actualScores.reduce((a,b)=>a+b,0) / actualScores.length).toFixed(1) : "0.0";

        const logPrompt = historicalChecks.length > 0 ? historicalChecks.map(c => 
            `[Log: ${c.date} ${new Date(c.timestamp).toLocaleTimeString()}] Score: ${c.aiCheckResult?.score || '?'}/10. Positives: ${c.aiCheckResult?.positives?.join(', ')}. Improvements: ${c.aiCheckResult?.improvements?.join(', ')}. Note: ${c.comment}`
        ).join('\n') : "No data.";

        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const response = await ai.models.generateContent({
            model: 'gemini-3-pro-preview', 
            contents: `Audit history for: "${dishName}". 

            LOGS:
            ${logPrompt}

            TASK:
            1. Narrate performance trends.
            2. "What's Working" and "Needs Improvement".
            3. "Significant Time Shifts": Detect if quality changed during specific durations (e.g., shifts in week 1 vs week 4, or specific day timeframes). Mention dates/times.

            JSON ONLY:
            {
              "stability_rating": ${calculatedStability},
              "whats_working": string[],
              "needs_improvement": string[],
              "time_duration_anomalies": string[],
              "detailed_summary": string,
              "score_trajectory": [numbers]
            }`,
            config: { responseMimeType: "application/json", temperature: 0.1 }
        });

        const auditData = JSON.parse(response.text);
        // Force the stability rating to our programmatic calculation if it drifted
        auditData.stability_rating = calculatedStability;
        renderAuditReport(auditData, historicalChecks, dishName);

    } catch (e) {
        console.error(e);
        DOMElements.auditResultsContainer.innerHTML = `<div class="p-10 bg-red-950/20 border border-red-900/40 rounded-[2.5rem] text-center"><p class="text-xs text-red-400 font-black uppercase tracking-widest">Neural Fault during Analysis. Retry.</p></div>`;
    }
};

