            </div>
        </div>

        <div class="bg-indigo-600 rounded-[3rem] p-10 mb-10 shadow-2xl relative overflow-hidden">
            <div class="relative z-10">
                <h3 class="text-[11px] font-black text-indigo-100 uppercase tracking-[0.4em] mb-3 opacity-80">Full History Analysis</h3>
                <h4 class="text-3xl font-black text-white uppercase tracking-tighter leading-none mb-6 italic underline decoration-indigo-400/40 decoration-8 underline-offset-12">${dishName}</h4>
