            </div>
        </div>
    `;

    try {
        const snapshot = await get(ref(database, 'quality-checks'));
        const allData = snapshot.val() || {};
        const historicalChecks = [];

        Object.keys(allData).forEach(date => {
            Object.values(allData[date]).forEach(check => {
                if (check.dishName === dishName) historicalChecks.push({ date, ...check });
            });
        });

        historicalChecks.sort((a,b) => (a.timestamp || "").localeCompare(b.timestamp || ""));

        // Calculate Average Score Programmatically
        const scores = historicalChecks.map(c => c.aiCheckResult?.score).filter(s => typeof s === 'number');
        const avgStability = scores.length ? (scores.reduce((a,b)=>a+b,0) / scores.length).toFixed(1) : "0.0";

        const logPrompt = historicalChecks.length > 0 ? historicalChecks.map(c => 
            `[Log: ${c.date} ${new Date(c.timestamp).toLocaleTimeString()}] AI Score: ${c.aiCheckResult?.score || '?'}/10. Positives: ${c.aiCheckResult?.positives?.join(', ')}. Improvements: ${c.aiCheckResult?.improvements?.join(', ')}. Note: ${c.comment}`
        ).join('\n') : "Zero sampling data available.";

        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const response = await ai.models.generateContent({
            model: 'gemini-3-pro-preview', 
            contents: `Audit all-time quality for: "${dishName}". 

            HISTORICAL RECORDS:
            ${logPrompt}

            GOALS:
            1. Summarize quality consistency.
            2. TIME SHIFTS: Did quality performance change significantly during specific time frames or weeks? Cite specific dates/times.

            OUTPUT JSON ONLY:
            {
              "stability_rating": ${avgStability},
              "whats_good": string[],
              "needs_improvement": string[],
              "time_anomalies": string[],
              "summary": string,
              "trajectory_values": [numbers]
            }`,
            config: { responseMimeType: "application/json", temperature: 0.1 }
        });

        const auditData = JSON.parse(response.text);
        // Force math stability to match programmatic average
        auditData.stability_rating = avgStability;
        renderAuditReport(auditData, historicalChecks, dishName);

    } catch (e) {
        console.error(e);
        DOMElements.auditResultsContainer.innerHTML = `<div class="p-10 bg-red-950/20 border border-red-900/40 rounded-[2.5rem] text-center"><p class="text-xs text-red-400 font-black uppercase tracking-widest">Logic Node Conflict. Retry.</p></div>`;
    }
};

