function saveCheckData(data) { set(ref(database, `quality-checks/${data.date}/${data.dishLetter}`), data).then(() => { state.isLibraryLoaded = false; fetchHistoricalDishLibrary(); }).catch(console.error); update(ref(database, `dish-registry/${data.dishName.replace(/[.#$\[\]]/g, "_")}`), { name: data.dishName, type: data.dishType }); }

