function renderCameraCapture(dish, initialImage) {
    const container = document.getElementById('camera-container');
    container.innerHTML = `<p class="text-[11px] font-black text-slate-400 uppercase tracking-[0.4em] mb-4 text-center">Neural Lens</p><div id="camera-placeholder" class="w-full aspect-square rounded-[3rem] bg-slate-950 border-4 border-dashed border-slate-800 flex flex-col items-center justify-center text-slate-700 cursor-pointer overflow-hidden shadow-inner hover:border-indigo-500/50 transition-all"><svg xmlns="http://www.w3.org/2000/svg" class="h-16 w-16 mb-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z"></path></svg><span class="text-[11px] uppercase font-black">Capture Specimen</span></div><div id="camera-view" class="w-full aspect-square rounded-[3rem] bg-black hidden relative overflow-hidden"><video id="camera-video" autoplay playsinline class="w-full h-full object-cover"></video><button type="button" id="capture-btn" class="absolute bottom-12 left-1/2 -translate-x-1/2 w-20 h-20 rounded-full border-[8px] border-white/20 bg-indigo-600 shadow-2xl active:scale-90 transition-all"></button></div><div id="image-preview" class="w-full aspect-square rounded-[3rem] relative hidden group border-4 border-slate-700 overflow-hidden shadow-2xl"><img id="preview-img" class="w-full h-full object-cover"/><div class="absolute inset-0 bg-slate-950/80 text-white flex items-center justify-center opacity-0 group-hover:opacity-100 transition-all backdrop-blur-md"><button type="button" id="retake-btn" class="px-10 py-4 bg-white text-slate-900 rounded-[1.5rem] text-[11px] font-black uppercase tracking-[0.4em] border-b-4 border-slate-300">Abort & Rescan</button></div></div>`;
    const videoEl = container.querySelector('#camera-video'); const form = DOMElements.dishCardContainer.querySelector('#dish-form'); let stream = null;
    container.querySelector('#camera-placeholder').onclick = async () => { if (form.querySelector('input').disabled) return; try { stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } }); videoEl.srcObject = stream; container.querySelector('#camera-placeholder').classList.add('hidden'); container.querySelector('#camera-view').classList.remove('hidden'); } catch (e) { alert("Optic deficit: " + e.message); } };
    container.querySelector('#capture-btn').onclick = () => { const canvas = document.createElement('canvas'); canvas.width = 1024; canvas.height = 1024; canvas.getContext('2d').drawImage(videoEl, 0, 0, 1024, 1024); const dataUrl = canvas.toDataURL('image/jpeg', 0.95); container.querySelector('#preview-img').src = dataUrl; form.dataset.capturedImage = dataUrl; if (stream) stream.getTracks().forEach(t => t.stop()); container.querySelector('#camera-view').classList.add('hidden'); container.querySelector('#image-preview').classList.remove('hidden'); handleAiCheck(state.selectedDish, dataUrl); };
    container.querySelector('#retake-btn').onclick = () => { if (!form.querySelector('input').disabled) { container.querySelector('#image-preview').classList.add('hidden'); container.querySelector('#camera-placeholder').classList.remove('hidden'); } };
    if (initialImage) { container.querySelector('#preview-img').src = initialImage; form.dataset.capturedImage = initialImage; container.querySelector('#camera-placeholder').classList.add('hidden'); container.querySelector('#image-preview').classList.remove('hidden'); }
}

async function handleAiCheck(dish, capturedImageDataUrl) {
    const feedbackContainer = document.getElementById('ai-feedback-container'); if (!feedbackContainer) return;
    feedbackContainer.innerHTML = `<div class="p-10 border border-indigo-500/30 bg-indigo-900/20 rounded-[3rem] flex flex-col items-center justify-center space-y-6 shadow-2xl backdrop-blur-md"><div class="relative w-10 h-10"><div class="absolute inset-0 border-4 border-indigo-500/10 rounded-full"></div><div class="absolute inset-0 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin"></div></div><p class="font-black text-indigo-400 text-[11px] uppercase tracking-[0.5em] animate-pulse">Neural Quality Inspection</p></div>`;
    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY }); let refImgPart = null; try { const refRes = await fetch(dish.dishImage); if (refRes.ok) { const blob = await refRes.blob(); const refBase64 = await new Promise(res => { const fr = new FileReader(); fr.onloadend = () => res(fr.result.split(',')[1]); fr.readAsDataURL(blob); }); refImgPart = { inlineData: { mimeType: 'image/jpeg', data: refBase64 } }; } } catch (e) { console.warn("Reference deficit:", e); }
        const result = await ai.models.generateContent({ model: 'gemini-3-pro-preview', contents: { parts: [ { text: `Audit '${dish.dishName}'. strictly JSON: { "score": 1-10, "positives": string[], "improvements": string[], "overall_comment": string }` }, ...(refImgPart ? [refImgPart] : []), { inlineData: { mimeType: 'image/jpeg', data: capturedImageDataUrl.split(',')[1] } } ] }, config: { responseMimeType: "application/json", temperature: 0.1 } });
        const feedbackData = JSON.parse(result.text); document.getElementById('dish-form').dataset.aiFeedback = JSON.stringify(feedbackData); renderAiFeedback(feedbackData);
    } catch (e) { feedbackContainer.innerHTML = `<div class="p-8 border border-red-900/40 bg-red-950/30 rounded-[2rem] text-xs text-red-400 uppercase font-black text-center shadow-xl">Precision Engine Offline</div>`; }
}

function renderAiFeedback(feedbackData) {
