async function fetchHistoricalDishLibrary() {
    if (state.isLibrarySyncing) return;
    state.isLibrarySyncing = true;

    try {
        const dishMap = new Map();

        // 1. SCAN ALL HISTORICAL QUALITY CHECKS (Deep Dive)
        const checksSnapshot = await get(ref(database, 'quality-checks'));
        const allChecks = checksSnapshot.val() || {};
        Object.keys(allChecks).forEach(dateKey => {
            const dayLogs = allChecks[dateKey];
            Object.values(dayLogs).forEach(log => {
                if (log.dishName) {
                    const name = log.dishName.trim();
                    if (!dishMap.has(name)) {
                        dishMap.set(name, { name, type: log.dishType || 'extras', count: 1 });
                    } else {
                        dishMap.get(name).count++;
                    }
                }
            });
        });

        // 2. SCAN ALL HISTORICAL MENUS (Catch dishes on menus not checked)
        const menusSnapshot = await get(ref(database, 'menus'));
        const allMenus = menusSnapshot.val() || {};
        Object.values(allMenus).forEach(weekMenu => {
            if (weekMenu.dishes) {
                weekMenu.dishes.forEach(dish => {
                    const name = dish.dishName.trim();
                    if (!dishMap.has(name)) {
                        dishMap.set(name, { name, type: dish.dishType || 'extras', count: 0 });
                    }
                });
            }
        });

        // 3. SCAN DISH REGISTRY
        const registrySnapshot = await get(ref(database, 'dish-registry'));
        const registry = registrySnapshot.val() || {};
        Object.values(registry).forEach(dish => {
            if (!dishMap.has(dish.name)) {
                dishMap.set(dish.name, { name: dish.name, type: dish.type, count: 0 });
            }
        });

        state.historicalDishLibrary = Array.from(dishMap.values()).sort((a,b) => a.name.localeCompare(b.name));
        state.isLibraryLoaded = true;
    } catch (e) {
        console.error("Archive discovery deficit:", e);
    } finally {
        state.isLibrarySyncing = false;
    }
}

window.runAuditForDish = async (dishName) => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
    DOMElements.auditResultsContainer.innerHTML = `
        <div class="flex flex-col items-center justify-center py-32 space-y-10">
            <div class="relative w-24 h-24">
                <div class="absolute inset-0 border-4 border-indigo-500/10 rounded-full"></div>
                <div class="absolute inset-0 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
            </div>
            <div class="text-center">
                <p class="text-[11px] font-black text-indigo-400 uppercase tracking-[0.6em] animate-pulse mb-4">Parsing Historical Life-Cycle</p>
                <h3 class="text-sm text-slate-400 font-black uppercase tracking-widest px-8 italic border-b border-indigo-500/30 pb-2 mx-auto max-w-fit">"${dishName}"</h3>
            </div>
        </div>
    `;

    try {
        const snapshot = await get(ref(database, 'quality-checks'));
        const allData = snapshot.val() || {};
        const historicalChecks = [];

        Object.keys(allData).forEach(date => {
            Object.values(allData[date]).forEach(check => {
                if (check.dishName === dishName) historicalChecks.push({ date, ...check });
            });
        });

        historicalChecks.sort((a,b) => (a.timestamp || "").localeCompare(b.timestamp || ""));

        // PROGRAMMATIC STABILITY MATH
        const scores = historicalChecks.map(c => c.aiCheckResult?.score).filter(s => typeof s === 'number');
        const avgStability = scores.length ? (scores.reduce((a,b)=>a+b,0) / scores.length).toFixed(1) : "0.0";

        const logPrompt = historicalChecks.length > 0 ? historicalChecks.map(c => 
            `[Check: ${c.date} ${new Date(c.timestamp).toLocaleTimeString()}] AI: ${c.aiCheckResult?.score || '?'}/10. Positives: ${c.aiCheckResult?.positives?.join(', ')}. Deficits: ${c.aiCheckResult?.improvements?.join(', ')}. Chef Observation: ${c.comment}`
        ).join('\n') : "Zero data found.";

        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const response = await ai.models.generateContent({
            model: 'gemini-3-pro-preview', 
            contents: `Deep Audit Performance for: "${dishName}". 

            HISTORY LOGS:
            ${logPrompt}

            MISSION:
            1. Narrate trend stability.
            2. TIME-DURATION ANALYSIS: Cite exactly when and why quality fluctuated (e.g., "Mondays between 11-12 show consistent dips").

            JSON FORMAT ONLY:
            {
              "stability_rating": ${avgStability},
              "whats_good": string[],
              "needs_improvement": string[],
              "time_anomalies": string[],
              "report_summary": string,
              "trajectory_map": [numbers]
            }`,
            config: { responseMimeType: "application/json", temperature: 0.1 }
        });

        const auditData = JSON.parse(response.text);
        auditData.stability_rating = avgStability; // Force exact consistency
        renderAuditReport(auditData, historicalChecks, dishName);

    } catch (e) {
        console.error(e);
        DOMElements.auditResultsContainer.innerHTML = `<div class="p-10 bg-red-950/20 border border-red-900/40 rounded-[2.5rem] text-center"><p class="text-xs text-red-400 font-black uppercase tracking-widest">Neural Logic Timeout. Please Retry.</p></div>`;
    }
};

