// --- Utility Functions ---
const getWeekId = (date) => {
    const d = new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()));
    d.setUTCDate(d.getUTCDate() + 4 - (d.getUTCDay() || 7));
    const yearStart = new Date(Date.UTC(d.getUTCFullYear(), 0, 1));
    const weekNo = Math.ceil((((d.getTime() - yearStart.getTime()) / 86400000) + 1) / 7);
    return `${d.getUTCFullYear()}-${String(weekNo).padStart(2, '0')}`;
};

const getStartOfWeek = (date) => {
    const d = new Date(date);
    const day = d.getDay();
    const diff = d.getDate() - day + (day === 0 ? -6 : 1);
    return new Date(d.setDate(diff));
};

// --- Historical Audit Analytics ---

async function fetchHistoricalDishLibrary() {
    if (state.syncPromise) return state.syncPromise;

    state.syncPromise = (async () => {
        try {
            const dishMap = new Map();
            const addOrUpdate = (name, type, increment = 0) => {
                if (!name) return;
                const cleanName = name.trim();
                if (!dishMap.has(cleanName)) {
                    dishMap.set(cleanName, { name: cleanName, type: type || 'extras', count: increment });
                } else {
                    const entry = dishMap.get(cleanName);
                    entry.count += increment;
                    if (type && entry.type === 'extras') entry.type = type;
                }
            };

            // 1. Scan quality-checks
            const checksSnap = await get(ref(database, 'quality-checks'));
            const checksData = checksSnap.val() || {};
            Object.values(checksData).forEach(dayNode => {
                if (dayNode && typeof dayNode === 'object') {
                    Object.values(dayNode).forEach(log => {
                        addOrUpdate(log.dishName, log.dishType, 1);
                    });
                }
            });

            // 2. Scan menus
            const menusSnap = await get(ref(database, 'menus'));
            const menusData = menusSnap.val() || {};
            Object.values(menusData).forEach(weekNode => {
                if (weekNode && weekNode.dishes) {
                    weekNode.dishes.forEach(d => addOrUpdate(d.dishName, d.dishType, 0));
                }
            });

            // 3. Scan registry
            const regSnap = await get(ref(database, 'dish-registry'));
            const regData = regSnap.val() || {};
            Object.values(regData).forEach(d => addOrUpdate(d.name, d.type, 0));

            state.historicalDishLibrary = Array.from(dishMap.values()).sort((a,b) => a.name.localeCompare(b.name));
            state.isLibraryLoaded = true;
            return state.historicalDishLibrary;
        } catch (e) {
            console.error("Discovery Error:", e);
            return [];
        } finally {
            state.syncPromise = null;
        }
    })();

    return state.syncPromise;
}

