                    ${audit.improvements.map(d => `<li class="text-xs text-slate-300 flex items-start gap-4"><div class="h-1.5 w-1.5 rounded-full bg-slate-600 mt-2 flex-shrink-0"></div>${d}</li>`).join('')}
