function initAuditChart(scores) {
    const ctx = document.getElementById('audit-chart');
    if (!ctx) return;
    new Chart(ctx, {
        type: 'line',
        data: {
            labels: scores.length > 0 ? scores.map((_, i) => i + 1) : [1],
            datasets: [{
                data: scores.length > 0 ? scores : [0],
                borderColor: '#6366f1',
                borderWidth: 4,
                tension: 0.4,
                pointRadius: 6,
                pointBackgroundColor: '#6366f1',
                fill: true,
                backgroundColor: 'rgba(99, 102, 241, 0.05)'
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            plugins: { legend: { display: false } },
            scales: {
                y: { min: 0, max: 10, grid: { color: 'rgba(255,255,255,0.05)' }, ticks: { color: '#64748b', font: { weight: 'bold' } } },
                x: { display: false }
            }
        }
    });
}

// --- Dashboard Logic ---
function renderApp() {
    DOMElements.loadingIndicator.classList.toggle('hidden', !state.isMenuLoading && !state.isCheckDataLoading);
    DOMElements.mainView.classList.toggle('hidden', state.isMenuLoading || state.isCheckDataLoading || state.currentView !== 'dashboard');
    if (state.menu && state.menu.dishes.length > 0) {
        DOMElements.welcomePlaceholder.classList.add('hidden');
        DOMElements.dishGridContainer.classList.remove('hidden');
        DOMElements.dailySummarySection.classList.remove('hidden');
        renderDishSelectionGrid();
        renderDailySummaryTable();
    } else {
        renderWelcomePlaceholder();
        DOMElements.dailySummarySection.classList.add('hidden');
    }
    renderDateSelector();
}

function renderDateSelector() {
    const viewDate = getStartOfWeek(new Date(state.selectedDate + 'T12:00:00Z'));
    const weekDays = Array.from({ length: 5 }).map((_, i) => {
        const d = new Date(viewDate); d.setDate(viewDate.getDate() + i); return d;
    });
    DOMElements.dateButtonsContainer.innerHTML = '';
    weekDays.forEach(day => {
        const dayString = day.toISOString().split('T')[0];
        const isSelected = dayString === state.selectedDate;
        const button = document.createElement('button');
        button.className = `flex flex-col items-center justify-center w-12 h-16 sm:w-16 sm:h-20 rounded-[1.5rem] transition-all duration-300 transform active:scale-90 shadow-2xl ${isSelected ? 'bg-indigo-600 text-white shadow-indigo-600/40 ring-4 ring-indigo-400/20' : 'bg-slate-800/80 text-slate-500 border border-slate-700/50'}`;
        button.innerHTML = `<span class="text-[10px] uppercase font-black opacity-70 mb-1">${day.toLocaleDateString('en-US', { weekday: 'short' })}</span><span class="text-lg font-black">${day.getDate()}</span>`;
        button.onclick = () => { state.selectedDate = dayString; fetchCheckData(); };
        DOMElements.dateButtonsContainer.appendChild(button);
    });
}

function renderDishSelectionGrid() {
    DOMElements.dishGridContainer.innerHTML = '';
    const sorted = [...(state.menu.dishes || [])].sort((a,b) => a.dishLetter.localeCompare(b.dishLetter));
    const groups = { cold: sorted.filter(d => d.dishType === 'cold'), hot: sorted.filter(d => d.dishType === 'hot'), extras: sorted.filter(d => d.dishType !== 'cold' && d.dishType !== 'hot') };
    const themes = { hot: 'bg-red-500', cold: 'bg-blue-500', default: 'bg-indigo-600' };

    Object.keys(groups).forEach(type => {
        const list = groups[type];
        if (list.length === 0) return;
        const h = document.createElement('div'); h.className = 'col-span-full text-[11px] font-black text-slate-500 uppercase tracking-[0.4em] mt-8 mb-3 pl-3 border-l-4 border-indigo-500/30'; h.textContent = `${type} BLOCK`;
        DOMElements.dishGridContainer.appendChild(h);
        list.forEach(dish => {
            const isChecked = !!state.checkedData[dish.dishLetter];
            const button = document.createElement('button');
            button.className = `group relative flex flex-col items-center justify-center p-6 border border-slate-700/50 rounded-[2.5rem] bg-slate-800/50 hover:scale-105 active:scale-95 shadow-2xl backdrop-blur-md transition-all duration-300`;
            button.onclick = () => { state.selectedDish = dish; showView('detail'); renderDishCard(); };
            button.innerHTML = `${isChecked ? '<div class="absolute -top-2 -right-2 bg-green-500 rounded-full p-2 text-white shadow-2xl ring-4 ring-slate-900"><svg xmlns="http://www.w3.org/2000/svg" class="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="5" d="M5 13l4 4L19 7"></path></svg></div>' : ''}<div class="mb-4 h-14 w-14 rounded-[1.5rem] flex items-center justify-center text-lg font-black shadow-2xl ${themes[dish.dishType] || themes.default} text-white uppercase italic">${dish.dishLetter}</div><p class="font-black text-[11px] text-slate-300 px-2 text-center line-clamp-2 uppercase h-10 flex items-center group-hover:text-white">${dish.dishName}</p>`;
            DOMElements.dishGridContainer.appendChild(button);
        });
    });
}

function renderDailySummaryTable() {
    if (!state.menu || !state.menu.dishes) return;
    const sorted = [...state.menu.dishes].sort((a,b) => a.dishLetter.localeCompare(b.dishLetter));
    const createTableHTML = (list, type) => {
        if (list.length === 0) return '';
        const headerColor = type === 'hot' ? 'bg-red-600/30' : type === 'cold' ? 'bg-blue-600/30' : 'bg-slate-700/50';
        return `<div class="bg-slate-800/40 rounded-[2.5rem] border border-slate-700/50 overflow-hidden shadow-2xl backdrop-blur-xl h-full flex flex-col"><div class="px-8 py-5 text-[11px] font-black uppercase tracking-[0.3em] text-white border-b border-white/5 ${headerColor}">${type} Recap</div><div class="overflow-x-auto custom-scrollbar flex-grow"><table class="min-w-full divide-y divide-slate-800 text-[11px]"><thead class="bg-slate-950/60"><tr><th class="px-6 py-4 text-left uppercase">ID</th><th class="px-6 py-4 text-left uppercase">Variant</th><th class="px-6 py-4 text-left uppercase">°C</th><th class="px-6 py-4 text-left uppercase">Mass</th><th class="px-6 py-4 text-left uppercase">Goal</th><th class="px-6 py-4 text-left uppercase">AI</th></tr></thead><tbody class="divide-y divide-slate-800/50">${list.map(dish => {
            const check = state.checkedData[dish.dishLetter];
            const vt = (check?.temperatures || []).map(t => parseFloat(t)).filter(t => !isNaN(t));
            const vw = (check?.weights || []).map(w => parseFloat(w)).filter(w => !isNaN(w));
            const ai = check?.aiCheckResult?.score || '-';
            return `<tr class="hover:bg-slate-700/40 cursor-pointer transition-colors ${!check ? 'opacity-25' : ''}" onclick="window.handleSelectDish('${dish.dishLetter}')"><td class="px-6 py-5 font-black text-indigo-400">${dish.dishLetter}</td><td class="px-6 py-5 text-slate-200 font-black uppercase truncate max-w-[140px]">${dish.dishName}</td><td class="px-6 py-5 text-slate-300 font-mono">${vt.length ? (vt.reduce((a,b)=>a+b,0)/vt.length).toFixed(1) + '°' : '-'}</td><td class="px-6 py-5 text-slate-300 font-mono">${vw.length ? (vw.reduce((a,b)=>a+b,0)/vw.length).toFixed(0) + 'g' : '-'}</td><td class="px-6 py-5 text-slate-500 italic">${dish.theoreticalWeight?.toFixed(0) || '-'}g</td><td class="px-6 py-5 font-black ${check && ai > 7 ? 'text-green-400' : 'text-indigo-400'}">${ai}</td></tr>`;
        }).join('')}</tbody></table></div></div>`;
    };
    let splitHtml = `<div id="cold-summary">${createTableHTML(sorted.filter(d => d.dishType === 'cold'), 'cold')}</div><div id="hot-summary">${createTableHTML(sorted.filter(d => d.dishType === 'hot'), 'hot')}</div>`;
    const extras = sorted.filter(d => d.dishType !== 'cold' && d.dishType !== 'hot');
    if (extras.length > 0) splitHtml += `<div class="full-width-section">${createTableHTML(extras, 'additional')}</div>`;
    DOMElements.dailySummaryContainer.innerHTML = splitHtml;
}

