                    ${audit.positives.map(p => `<li class="text-xs text-slate-300 flex items-start gap-4"><div class="h-1.5 w-1.5 rounded-full bg-slate-600 mt-2 flex-shrink-0"></div>${p}</li>`).join('')}
                </ul>
            </div>
            <div class="bg-slate-800 rounded-[3rem] p-10 border border-slate-700/50 shadow-2xl">
