/**
 * Performs a deep-scan of the database to build a flat searchable cache
 * and a unique library of all discovered dishes.
 */
async function syncGlobalHistory() {
    if (state.syncPromise) return state.syncPromise;

    state.syncPromise = (async () => {
        try {
            const flatChecks = [];
            const dishMap = new Map();

            const registerToLibrary = (name, type, increment = 0) => {
                if (!name) return;
                const cleanName = name.trim();
                const key = normalizeName(cleanName);
                if (!dishMap.has(key)) {
                    dishMap.set(key, { name: cleanName, type: type || 'extras', count: increment });
                } else {
                    const entry = dishMap.get(key);
                    entry.count += increment;
                    if (type && entry.type === 'extras') entry.type = type;
                }
            };

            // 1. Excavate quality-checks node
            const checksSnap = await get(ref(database, 'quality-checks'));
            safeIterate(checksSnap.val(), (dayNode, date) => {
                safeIterate(dayNode, (log, letter) => {
                    if (log && log.dishName) {
                        const enhancedLog = { ...log, date, letter, originalTimestamp: log.timestamp };
                        flatChecks.push(enhancedLog);
                        registerToLibrary(log.dishName, log.dishType, 1);
                    }
                });
            });

            // 2. Scan menu manifests for potential dishes not yet logged
            const menusSnap = await get(ref(database, 'menus'));
            safeIterate(menusSnap.val(), (weekNode) => {
                if (weekNode && weekNode.dishes) {
                    weekNode.dishes.forEach(d => registerToLibrary(d.dishName, d.dishType, 0));
                }
            });

            // 3. Scan central registry
            const regSnap = await get(ref(database, 'dish-registry'));
            safeIterate(regSnap.val(), (d) => {
                registerToLibrary(d.name, d.type, 0);
            });

            state.allHistoricalChecks = flatChecks;
            state.historicalDishLibrary = Array.from(dishMap.values()).sort((a,b) => a.name.localeCompare(b.name));
            state.isLibraryLoaded = true;
            return state.historicalDishLibrary;
        } catch (e) {
            console.error("Critical Global Sync Failure:", e);
            return [];
        } finally {
            state.syncPromise = null;
        }
    })();

    return state.syncPromise;
}

