/**
 * Hyper-Normalization: Ensures that "B&B Butter Chicken" and "BB Butter Chicken" match.
 */
const normalizeName = (name) => {
    if (!name) return "";
    return name
        .toLowerCase()
        .replace(/&/g, 'and')
        .replace(/[^\w\s]/gi, '') // Remove punctuation
        .replace(/\b(and|with|the|of|for)\b/g, '') // Remove stop-words
        .replace(/\s+/g, ' ') // Collapse spaces
        .trim();
};

/**
 * Recursive Crawler: Digs through ANY database structure to find dish logs.
 */
const crawlForLogsRecursive = (node, foundLogs = []) => {
    if (!node || typeof node !== 'object') return foundLogs;

    // If this node looks like a quality check record
    if (node.dishName && (node.timestamp || node.aiCheckResult)) {
        foundLogs.push(node);
        return foundLogs;
    }

    // Otherwise, keep digging
    Object.values(node).forEach(child => {
        crawlForLogsRecursive(child, foundLogs);
    });

    return foundLogs;
};

const getWeekId = (date) => {
    const d = new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()));
    d.setUTCDate(d.getUTCDate() + 4 - (d.getUTCDay() || 7));
    const yearStart = new Date(Date.UTC(d.getUTCFullYear(), 0, 1));
    const weekNo = Math.ceil((((d.getTime() - yearStart.getTime()) / 86400000) + 1) / 7);
    return `${d.getUTCFullYear()}-${String(weekNo).padStart(2, '0')}`;
};

const getStartOfWeek = (date) => {
    const d = new Date(date);
    const day = d.getDay();
    const diff = d.getDate() - day + (day === 0 ? -6 : 1);
    return new Date(d.setDate(diff));
};

