/**
 * Excavates every single log from the database regardless of path.
 */
async function syncGlobalHistory() {
    if (state.syncPromise) return state.syncPromise;

    state.syncPromise = (async () => {
        try {
            const checksSnap = await get(ref(database, 'quality-checks'));
            const rawData = checksSnap.val();

            // The magic: Recursive crawl find EVERYTHING
            const flatChecks = crawlForLogsRecursive(rawData);

            const dishMap = new Map();
            flatChecks.forEach(log => {
                const key = normalizeName(log.dishName);
                if (!dishMap.has(key)) {
                    dishMap.set(key, { 
                        name: log.dishName, 
                        type: log.dishType || 'extras', 
                        count: 1 
                    });
                } else {
                    dishMap.get(key).count += 1;
                }
            });

            // Also check menus for entries that might not have logs yet
            const menusSnap = await get(ref(database, 'menus'));
            const menusData = menusSnap.val();
            if (menusData) {
                Object.values(menusData).forEach(week => {
                    if (week.dishes) {
                        week.dishes.forEach(d => {
                            const key = normalizeName(d.dishName);
                            if (!dishMap.has(key)) {
                                dishMap.set(key, { name: d.dishName, type: d.dishType, count: 0 });
                            }
                        });
                    }
                });
            }

            state.allHistoricalChecks = flatChecks;
            state.totalRecordsFound = flatChecks.length;
            state.historicalDishLibrary = Array.from(dishMap.values()).sort((a,b) => a.name.localeCompare(b.name));
            state.isLibraryLoaded = true;

            console.log(`[Neural Sync] Excavated ${state.totalRecordsFound} records across ${dishMap.size} unique dishes.`);
            return state.historicalDishLibrary;
        } catch (e) {
            console.error("Critical Neural Excavation Failure:", e);
            return [];
        } finally {
            state.syncPromise = null;
        }
    })();

    return state.syncPromise;
}

