async function renderHistoricalIntel(dishName) {
    const intelContainer = document.getElementById('historical-intel-container');
    if (!intelContainer) return;

    const target = normalizeName(dishName);
    const checks = state.allHistoricalChecks.filter(c => normalizeName(c.dishName) === target);

    if (checks.length === 0) {
        intelContainer.innerHTML = `<span class="text-slate-500 font-black tracking-widest italic uppercase">Zero Matches in ${state.totalRecordsFound} Logs</span>`;
        return;
    }

    const recent = [...checks].sort((a,b) => (b.timestamp || "").localeCompare(a.timestamp || "")).slice(0, 5);
    const avg = (recent.reduce((sum, c) => sum + (c.aiCheckResult?.score || 0), 0) / recent.length).toFixed(1);

    intelContainer.innerHTML = `
        <div class="flex items-center gap-4 animate-in fade-in duration-700">
            <div class="flex items-center gap-1.5">${recent.map(c => `<div class="w-2.5 h-2.5 rounded-full ${c.aiCheckResult?.score > 7 ? 'bg-green-500' : 'bg-indigo-500'} shadow-sm"></div>`).join('')}</div>
            <div class="h-4 w-px bg-slate-800"></div>
            <span class="text-[10px] font-black text-indigo-400 uppercase tracking-widest">${avg} Historical Index (${checks.length} Identity Matches)</span>
        </div>
    `;
}

