// --- Neural Identity & Crawler Logic ---

/**
 * Robust Normalization: Strips sides and common variations to find matches like 
 * "B&B Butter Chicken" and "Butter Chicken with Rice".
 */
const normalizeName = (name) => {
    if (!name) return "";
    return name
        .toLowerCase()
        .replace(/&/g, 'and')
        .replace(/[^\w\s]/gi, '') 
        .replace(/\b(with|rice|chips|salad|side|and|the|of|for|pasta|potato)\b/g, '')
        .replace(/\s+/g, ' ')
        .trim();
};

/**
 * Fuzzy Matching: Returns true if two dish names are likely the same entity.
 */
const isDishMatch = (name1, name2) => {
    const n1 = normalizeName(name1);
    const n2 = normalizeName(name2);
    if (!n1 || !n2) return false;
    // Exact normalized match or one contains the other (for dishes with/without side descriptions)
    return n1 === n2 || n1.includes(n2) || n2.includes(n1);
};

/**
 * Recursive Discovery: Traverses any depth to find logs and extract dates from keys if needed.
 */
const discoverLogs = (node, found = [], currentPathKey = "") => {
    if (!node || typeof node !== 'object') return found;

    // Check if this leaf node is a Quality Record
    if (node.dishName && (node.timestamp || node.aiCheckResult)) {
        // Try to find a date in the path if not in the object
        const dateMatch = currentPathKey.match(/\d{4}-\d{2}-\d{2}/);
        found.push({
            ...node,
            pathDate: dateMatch ? dateMatch[0] : null
        });
        return found;
    }

    Object.entries(node).forEach(([key, val]) => {
        discoverLogs(val, found, key);
    });

    return found;
};

// --- Core Data Synchronization ---

/**
 * Real-time listener for the entire quality-checks node.
 * This ensures state.allHistoricalChecks is ALWAYS up to date.
 */
function listenToGlobalHistory() {
    onValue(ref(database, 'quality-checks'), (snapshot) => {
        const data = snapshot.val();
        const logs = discoverLogs(data);

        state.allHistoricalChecks = logs;
        state.totalRecordsFound = logs.length;

        // Rebuild Library for Analytics
        const dishMap = new Map();
        logs.forEach(log => {
            const key = normalizeName(log.dishName);
            if (!dishMap.has(key)) {
                dishMap.set(key, { name: log.dishName, type: log.dishType || 'extras', count: 1 });
            } else {
                dishMap.get(key).count += 1;
            }
        });

        state.historicalDishLibrary = Array.from(dishMap.values()).sort((a,b) => b.count - a.count);
        state.isLibraryLoaded = true;

        console.log(`[Neural Sync] Found ${state.totalRecordsFound} logs across ${dishMap.size} unique identities.`);

        // If we are in audit view, refresh it automatically
        if (state.currentView === 'audit' && !document.querySelector('#audit-chart')) {
            window.renderAuditDishLibrary();
        }
    });
}

