    try {
        const historicalChecks = state.allHistoricalChecks.filter(c => isDishMatch(c.dishName, dishName));

        historicalChecks.sort((a,b) => (a.timestamp || "").localeCompare(b.timestamp || ""));
        const scores = historicalChecks.map(c => c.aiCheckResult?.score).filter(s => typeof s === 'number');
        const avgStability = scores.length ? (scores.reduce((a,b)=>a+b,0) / scores.length).toFixed(1) : "0.0";

        const logPrompt = historicalChecks.length > 0 ? historicalChecks.map(c => 
            `[Log: ${c.pathDate || c.date || 'Historical'}] Score: ${c.aiCheckResult?.score || '?'}/10. Notes: ${c.comment || 'N/A'}. Results: ${c.aiCheckResult?.overall_comment || ''}`
        ).join('\n') : "Zero matching data found in recursive crawl.";

        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const response = await ai.models.generateContent({
            model: 'gemini-3-pro-preview', 
            contents: `Conduct a longitudinal quality audit for: "${dishName}". 

            FULL HISTORICAL DATASET (${historicalChecks.length} instances):
            ${logPrompt}

            REQUIRED OUTPUT (JSON ONLY):
            {
              "stability_rating": ${avgStability},
              "positives": string[],
              "improvements": string[],
              "temporal_insights": string[],
              "summary": string,
              "trend_scores": [numbers]
