        const auditData = JSON.parse(response.text);
        renderAuditReport(auditData, historicalChecks, dishName);

    } catch (e) {
        console.error(e);
        DOMElements.auditResultsContainer.innerHTML = `<div class="p-10 bg-red-950/20 border border-red-900/40 rounded-[2.5rem] text-center"><p class="text-xs text-red-400 font-black uppercase tracking-widest">Logic extraction fault. Neural bridge broken.</p></div>`;
    }
};

