// --- Neural Identity & Crawler Logic ---

/**
 * Normalization helper to collapse variations in manual naming.
 */
const normalizeName = (name) => {
    if (!name) return "";
    return name
        .toLowerCase()
        .replace(/&/g, 'and')
        .replace(/[^\w\s]/gi, '') 
        .replace(/\b(with|rice|chips|salad|side|and|the|of|for|pasta|potato|extra|veg|vege)\b/g, '')
        .replace(/\s+/g, ' ')
        .trim();
};

/**
 * Logic to check if two names refer to the same dish.
 */
const isDishMatch = (name1, name2) => {
    const n1 = normalizeName(name1);
    const n2 = normalizeName(name2);
    if (!n1 || !n2) return false;
    // Identity resolution: exact or substring containment
    return n1 === n2 || n1.includes(n2) || n2.includes(n1);
};

/**
 * FIXED: getStartOfWeek was undefined in the previous build.
 */
const getStartOfWeek = (date) => {
    const d = new Date(date);
    const day = d.getDay();
    const diff = d.getDate() - day + (day === 0 ? -6 : 1);
    return new Date(d.setDate(diff));
};

const getWeekId = (date) => {
    const d = new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()));
    d.setUTCDate(d.getUTCDate() + 4 - (d.getUTCDay() || 7));
    const yearStart = new Date(Date.UTC(d.getUTCFullYear(), 0, 1));
    const weekNo = Math.ceil((((d.getTime() - yearStart.getTime()) / 86400000) + 1) / 7);
    return `${d.getUTCFullYear()}-${String(weekNo).padStart(2, '0')}`;
};

/**
 * REFINED: Recursive Discovery that passes date context down the tree.
 * Ensures "Butter Chicken" on Monday is not lost if monday's key is "2023-10-23".
 */
const discoverLogs = (node, found = [], dateContext = null) => {
    if (!node || typeof node !== 'object') return found;

    // Is this a quality check object?
    if (node.dishName && (node.timestamp || node.aiCheckResult)) {
        found.push({
            ...node,
            pathDate: dateContext || node.date || (node.timestamp ? node.timestamp.split('T')[0] : null)
        });
        return found;
    }

    Object.entries(node).forEach(([key, val]) => {
        // Inherit date if key matches YYYY-MM-DD pattern
        const isDateKey = /^\d{4}-\d{2}-\d{2}$/.test(key);
        discoverLogs(val, found, isDateKey ? key : dateContext);
    });

    return found;
};

