/**
 * Listen globally to discover every record ever made.
 */
function listenToGlobalHistory() {
    onValue(ref(database, 'quality-checks'), (snapshot) => {
        const data = snapshot.val();
        const logs = discoverLogs(data);

        state.allHistoricalChecks = logs;
        state.totalRecordsFound = logs.length;

        const dishMap = new Map();
        logs.forEach(log => {
            const key = normalizeName(log.dishName);
            if (!dishMap.has(key)) {
                dishMap.set(key, { name: log.dishName, type: log.dishType || 'extras', count: 1 });
            } else {
                dishMap.get(key).count += 1;
            }
        });

        state.historicalDishLibrary = Array.from(dishMap.values()).sort((a,b) => b.count - a.count);
        state.isLibraryLoaded = true;

        console.log(`[Global Intelligence] ${state.totalRecordsFound} entries indexed.`);

        if (state.currentView === 'audit' && !document.querySelector('#audit-chart')) {
            window.renderAuditDishLibrary();
        }
    });
}

window.renderAuditDishLibrary = async function() {
    let html = `
        <div class="mb-12 flex flex-col sm:flex-row items-center justify-between gap-6 bg-slate-800/40 p-10 rounded-[3rem] border border-slate-700/50">
            <div>
                <h3 class="text-xl font-black text-white italic tracking-tighter uppercase">Deep Storage Analytics</h3>
                <p class="text-[10px] font-black text-indigo-400 uppercase tracking-[0.4em] mt-2">${state.totalRecordsFound} Total Points Processed</p>
            </div>
            <div class="flex gap-4">
                <div class="px-6 py-4 bg-slate-900/80 rounded-2xl border border-slate-800 text-center">
                    <span class="block text-lg font-black text-white">${state.historicalDishLibrary.length}</span>
                    <span class="text-[9px] font-black text-slate-500 uppercase tracking-widest">Dishes</span>
                </div>
                 <div class="px-6 py-4 bg-slate-900/80 rounded-2xl border border-slate-800 text-center">
                    <span class="block text-lg font-black text-white">${state.totalRecordsFound}</span>
                    <span class="text-[9px] font-black text-slate-500 uppercase tracking-widest">Logs</span>
                </div>
            </div>
        </div>
    `;

    const hot = state.historicalDishLibrary.filter(d => d.type === 'hot');
    const cold = state.historicalDishLibrary.filter(d => d.type === 'cold');
    const extras = state.historicalDishLibrary.filter(d => d.type !== 'hot' && d.type !== 'cold');

    const renderSection = (list, title, colorClass) => {
        if (list.length === 0) return '';
        return `
            <div class="mb-16">
                <div class="flex items-center gap-4 mb-6 px-2 border-b border-slate-800 pb-3">
                    <div class="h-3 w-3 rounded-full ${colorClass} shadow-xl"></div>
                    <h3 class="text-[11px] font-black text-slate-400 uppercase tracking-[0.4em]">${title}</h3>
                </div>
                <div class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
                    ${list.map(d => `
                        <button onclick="window.runAuditForDish('${d.name.replace(/'/g, "\\'")}')" class="group relative flex flex-col p-6 bg-slate-800/40 border border-slate-700/50 rounded-[2rem] hover:border-indigo-500/50 hover:bg-slate-800 transition-all text-left shadow-2xl active:scale-95">
                             <div class="absolute top-6 right-6 text-indigo-500/20 group-hover:text-indigo-400 transition-colors"><svg xmlns="http://www.w3.org/2000/svg" class="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M13 7h8m0 0v8m0-8l-8 8-4-4-6 6"></path></svg></div>
                            <p class="text-[14px] font-black text-slate-200 group-hover:text-white mb-2 uppercase tracking-tight pr-10 italic truncate">${d.name}</p>
                            <div class="flex items-center gap-2"><span class="text-[10px] text-indigo-400 font-black px-3 py-1 bg-indigo-500/10 rounded-xl border border-indigo-500/20">${d.count} Samples</span></div>
                        </button>
                    `).join('')}
                </div>
            </div>
        `;
    };

    html += `<div class="animate-in fade-in duration-700">`;
    html += renderSection(hot, 'Hot Kitchen Archive', 'bg-red-500');
    html += renderSection(cold, 'Cold Kitchen Archive', 'bg-blue-500');
    html += renderSection(extras, 'Supplemental Archives', 'bg-slate-500');
    html += `</div>`;

    DOMElements.auditResultsContainer.innerHTML = html;
};

window.runAuditForDish = async (dishName) => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
    DOMElements.auditResultsContainer.innerHTML = `
        <div class="flex flex-col items-center justify-center py-32 space-y-10">
            <div class="relative w-24 h-24">
                <div class="absolute inset-0 border-4 border-indigo-500/10 rounded-full"></div>
                <div class="absolute inset-0 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
            </div>
            <div class="text-center">
                <p class="text-[11px] font-black text-indigo-400 uppercase tracking-[0.6em] animate-pulse mb-4">Filtering ${state.totalRecordsFound} Points</p>
                <h3 class="text-sm text-slate-400 font-black uppercase tracking-widest px-8 italic border-b border-indigo-500/30 pb-2 mx-auto max-w-fit italic underline underline-offset-8 decoration-indigo-500/20">${dishName}</h3>
            </div>
        </div>
    `;

    try {
        const historicalChecks = state.allHistoricalChecks.filter(c => isDishMatch(c.dishName, dishName));

        historicalChecks.sort((a,b) => (a.timestamp || "").localeCompare(b.timestamp || ""));
        const scores = historicalChecks.map(c => c.aiCheckResult?.score).filter(s => typeof s === 'number');
        const avgStability = scores.length ? (scores.reduce((a,b)=>a+b,0) / scores.length).toFixed(1) : "0.0";

        const logPrompt = historicalChecks.length > 0 ? historicalChecks.map(c => 
            `[Record: ${c.pathDate || c.date || 'Historical'}] Score: ${c.aiCheckResult?.score || '?'}/10. Note: ${c.comment || 'N/A'}. AI Comment: ${c.aiCheckResult?.overall_comment || ''}`
        ).join('\n') : "Zero matching data found for this normalized entity.";

        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const response = await ai.models.generateContent({
            model: 'gemini-3-pro-preview', 
            contents: `Conduct a longitudinal quality audit for: "${dishName}". 

            HISTORICAL SET (${historicalChecks.length} instances):
            ${logPrompt}

            REQUIRED OUTPUT (JSON ONLY):
            {
              "stability_rating": ${avgStability},
              "positives": string[],
              "improvements": string[],
              "temporal_insights": string[],
              "summary": string,
              "trend_scores": [numbers]
            }`,
            config: { responseMimeType: "application/json", temperature: 0.1 }
        });

        const auditData = JSON.parse(response.text);
        renderAuditReport(auditData, historicalChecks, dishName);

    } catch (e) {
        console.error(e);
        DOMElements.auditResultsContainer.innerHTML = `<div class="p-10 bg-red-950/20 border border-red-900/40 rounded-[2.5rem] text-center"><p class="text-xs text-red-400 font-black uppercase tracking-widest">Logic extraction fault.</p></div>`;
    }
};

