        <div class="flex items-center justify-between mb-8">
            <button onclick="window.renderAuditDishLibrary()" class="flex items-center gap-3 px-6 py-4 text-[10px] font-black rounded-2xl bg-slate-800 text-slate-300 border border-slate-700 hover:text-white transition-all shadow-xl active:scale-95">
                <svg xmlns="http://www.w3.org/2000/svg" class="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="3" d="M15 19l-7-7 7-7"></path></svg>
                BACK TO DISH LIBRARY
            </button>
            <div class="px-6 py-3 bg-slate-900/90 border border-slate-800 rounded-2xl shadow-inner text-[10px] font-black text-slate-500 uppercase tracking-widest">
                 Matching Samples: ${history.length}
            </div>
        </div>

        <div class="bg-indigo-600 rounded-[3rem] p-10 mb-10 shadow-2xl relative overflow-hidden">
            <div class="relative z-10">
                <h3 class="text-[11px] font-black text-indigo-100 uppercase tracking-[0.4em] mb-3 opacity-80">Stability Narrative</h3>
                <h4 class="text-3xl font-black text-white uppercase tracking-tighter leading-none mb-6 italic underline decoration-indigo-400/40 decoration-8 underline-offset-12">${dishName}</h4>
                <p class="text-sm text-indigo-50 leading-relaxed font-medium opacity-95 max-w-3xl italic">"${audit.summary}"</p>
            </div>
        </div>

        <div class="grid grid-cols-1 md:grid-cols-4 gap-8 mb-10">
            <div class="bg-slate-800 rounded-[3rem] p-10 border border-slate-700/50 shadow-2xl flex flex-col items-center justify-center text-center">
                <p class="text-[11px] font-black text-slate-500 uppercase tracking-widest mb-4">Quality Index</p>
                <div class="text-8xl font-black ${scoreColor} tracking-tighter italic">${audit.stability_rating}<span class="text-2xl text-slate-600 not-italic ml-1">/10</span></div>
            </div>
            <div class="md:col-span-3 bg-slate-800 rounded-[3rem] p-10 border border-slate-700/50 shadow-2xl overflow-hidden">
                <p class="text-[11px] font-black text-slate-500 uppercase tracking-widest mb-6">Historical Persistence</p>
                <div class="h-48 w-full"><canvas id="audit-chart"></canvas></div>
            </div>
        </div>

        <div class="grid grid-cols-1 md:grid-cols-2 gap-8 mb-10">
            <div class="bg-slate-800 rounded-[3rem] p-10 border border-slate-700/50 shadow-2xl">
                <p class="text-[11px] font-black text-green-400 uppercase tracking-widest mb-6 flex items-center gap-3"><span class="h-2 w-2 rounded-full bg-green-500 shadow-lg shadow-green-500/30"></span>Consistent Strengths</p>
                <ul class="space-y-4">
                    ${audit.positives.map(p => `<li class="text-xs text-slate-300 flex items-start gap-4"><div class="h-1.5 w-1.5 rounded-full bg-slate-600 mt-2 flex-shrink-0"></div>${p}</li>`).join('')}
                </ul>
            </div>
            <div class="bg-slate-800 rounded-[3rem] p-10 border border-slate-700/50 shadow-2xl">
                <p class="text-[11px] font-black text-yellow-400 uppercase tracking-widest mb-6 flex items-center gap-3"><span class="h-2 w-2 rounded-full bg-yellow-500 shadow-lg shadow-yellow-500/30"></span>Optimization Gains</p>
                <ul class="space-y-4">
                    ${audit.improvements.map(d => `<li class="text-xs text-slate-300 flex items-start gap-4"><div class="h-1.5 w-1.5 rounded-full bg-slate-600 mt-2 flex-shrink-0"></div>${d}</li>`).join('')}
                </ul>
            </div>
        </div>

        <div class="bg-slate-800 rounded-[3rem] border border-slate-700/50 overflow-hidden shadow-2xl">
            <div class="px-10 py-6 bg-slate-900/50 border-b border-slate-800 text-[11px] font-black text-slate-500 uppercase tracking-[0.3em]">Identity Verification Audit (${history.length} Matches)</div>
            <div class="p-4 space-y-2 max-h-96 overflow-y-auto custom-scrollbar">
                ${history.map(log => `
                    <div class="bg-slate-900/40 p-5 rounded-2xl border border-slate-800 flex items-center justify-between group hover:bg-slate-800 transition-all">
                        <div class="flex items-center gap-6">
                            <span class="text-[10px] font-mono text-slate-500">${log.pathDate || log.date || '??-??-??'}</span>
                            <span class="text-xs font-black text-slate-300 uppercase truncate max-w-[200px]">${log.dishName}</span>
                        </div>
                        <span class="px-4 py-1.5 bg-slate-950 rounded-xl text-[10px] font-black ${log.aiCheckResult?.score > 7 ? 'text-green-500' : 'text-indigo-400'}">${log.aiCheckResult?.score || '-'}/10</span>
                    </div>
                `).join('')}
            </div>
