/**
 * The 'Universal Brain': Synchronizes all historical data in real-time.
 */
function listenToGlobalHistory() {
    onValue(ref(database, 'quality-checks'), (snapshot) => {
        const data = snapshot.val();
        const logs = discoverLogs(data);

        state.allHistoricalChecks = logs;
        state.totalRecordsFound = logs.length;

        // Re-index dish library for the Analytics view
        const dishMap = new Map();
        logs.forEach(log => {
            const key = normalizeName(log.dishName);
            if (!dishMap.has(key)) {
                dishMap.set(key, { 
                    name: log.dishName, 
                    type: log.dishType || 'extras', 
                    count: 1 
                });
            } else {
                dishMap.get(key).count += 1;
            }
        });

        state.historicalDishLibrary = Array.from(dishMap.values()).sort((a,b) => b.count - a.count);
        state.isLibraryLoaded = true;

        console.log(`[Neural Index] Found ${state.totalRecordsFound} entries across ${dishMap.size} identities.`);

        // Refresh UI if we're in the Audit view
        if (state.currentView === 'audit' && !document.querySelector('#audit-chart')) {
            window.renderAuditDishLibrary();
        }
    });
}

