            <div class="text-center">
                <p class="text-[11px] font-black text-indigo-400 uppercase tracking-[0.6em] animate-pulse mb-6">Filtering ${state.totalRecordsFound} Points for Neural Match</p>
                <h3 class="text-lg text-slate-400 font-black uppercase tracking-widest italic border-b-2 border-indigo-500/20 pb-4 px-12 inline-block">"${dishName}"</h3>
            </div>
        </div>
    `;

    try {
        const matches = state.allHistoricalChecks.filter(c => isDishMatch(c.dishName, dishName));
        matches.sort((a,b) => (a.timestamp || "").localeCompare(b.timestamp || ""));

        const scores = matches.map(c => c.aiCheckResult?.score).filter(s => typeof s === 'number');
        const avgStability = scores.length ? (scores.reduce((a,b)=>a+b,0) / scores.length).toFixed(1) : "0.0";

        const logPrompt = matches.length > 0 ? matches.map(c => 
            `[Record: ${c.pathDate || 'Historical'}] Score: ${c.aiCheckResult?.score || '?'}/10. Note: ${c.comment || 'N/A'}.`
        ).join('\n') : "Zero matching data found for this normalized identity.";

        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const response = await ai.models.generateContent({
            model: 'gemini-3-pro-preview', 
            contents: `Longitudinal analysis for: "${dishName}". 

            FULL HISTORICAL SET (${matches.length} matches across all dates):
            ${logPrompt}

            REQUIRED OUTPUT (JSON ONLY):
            {
              "stability_rating": ${avgStability},
              "positives": string[],
              "improvements": string[],
              "temporal_insights": string[],
              "summary": string,
              "trend_scores": [numbers]
            }`,
            config: { responseMimeType: "application/json", temperature: 0.1 }
        });

        const auditData = JSON.parse(response.text);
        renderAuditReport(auditData, matches, dishName);

    } catch (e) {
        console.error(e);
        DOMElements.auditResultsContainer.innerHTML = `<div class="p-10 bg-red-950/20 border border-red-900/40 rounded-[3rem] text-center"><p class="text-xs text-red-400 font-black uppercase tracking-widest">Logic extraction fault.</p></div>`;
    }
};

