function fetchMenu() { state.isMenuLoading = true; renderApp(); const weekId = getWeekId(new Date(state.selectedDate + 'T12:00:00Z')); onValue(ref(database, `menus/${weekId}`), (snapshot) => { state.menu = snapshot.val() || null; state.isMenuLoading = false; renderApp(); }); }
function fetchCheckData() { state.isCheckDataLoading = true; renderApp(); onValue(ref(database, `quality-checks/${state.selectedDate}`), (snapshot) => { state.checkedData = snapshot.val() || {}; state.isCheckDataLoading = false; renderApp(); }); }
function saveCheckData(data) { set(ref(database, `quality-checks/${data.date}/${data.dishLetter}`), data).catch(console.error); }

DOMElements.navDashboardBtn.onclick = () => showView('dashboard');
DOMElements.navAuditBtn.onclick = () => showView('audit');
DOMElements.settingsBtn.onclick = () => DOMElements.settingsModal.classList.remove('hidden');
DOMElements.settingsCloseBtn.onclick = () => DOMElements.settingsModal.classList.add('hidden');
DOMElements.backToMenuBtn.onclick = () => showView('dashboard');

DOMElements.settingsSaveBtn.onclick = async () => {
    const val = DOMElements.jsonInput.value.trim(); if (!val) return;
    try {
        const p = JSON.parse(val);
        const dishes = p.dishes.filter(d => d.stickerNo && d.stickerNo !== 'addons').map(d => ({ dishLetter: d.stickerNo, dishName: d.variantName, dishImage: d.webUrl, dishType: ['hot', 'cold'].includes(d.type) ? d.type : 'extras', dishIngredients: (d.ingredients || []).map(i => ({name: i.name, weight: i.amount + 'g'})), theoreticalWeight: (d.ingredients || []).reduce((sum, ing) => sum + (parseFloat(ing.amount) || 0), 0) }));
        const registryUpdates = {}; dishes.forEach(d => { registryUpdates[normalizeName(d.dishName).replace(/[.#$\[\]]/g, "_")] = { name: d.dishName, type: d.dishType }; });
        await update(ref(database, 'dish-registry'), registryUpdates);
        const menuWeekId = getWeekId(new Date(p.startDate + 'T12:00:00Z'));
        await set(ref(database, `menus/${menuWeekId}`), { dishes, startDate: p.startDate });
        DOMElements.settingsModal.classList.add('hidden'); fetchMenu();
    } catch (e) { DOMElements.settingsError.textContent = "Manifest Validation Fault."; }
};

DOMElements.prevWeekBtn.onclick = () => { const d = new Date(state.selectedDate + 'T12:00:00Z'); d.setDate(d.getDate()-7); state.selectedDate = d.toISOString().split('T')[0]; fetchMenu(); fetchCheckData(); };
DOMElements.nextWeekBtn.onclick = () => { const d = new Date(state.selectedDate + 'T12:00:00Z'); d.setDate(d.getDate()+7); state.selectedDate = d.toISOString().split('T')[0]; fetchMenu(); fetchCheckData(); };

window.handleSelectDish = (letter) => { const dish = state.menu.dishes.find(d => d.dishLetter === letter); if(dish) { state.selectedDish = dish; showView('detail'); renderDishCard(); } };
function renderWelcomePlaceholder() { DOMElements.dishGridContainer.classList.add('hidden'); DOMElements.welcomePlaceholder.innerHTML = `<div class="text-center py-40 bg-slate-800/20 rounded-[4rem] border-2 border-slate-800 border-dashed"><p class="text-sm text-slate-500 font-black uppercase tracking-[0.4em]">Operational Vacuum detected. Sync via setup matrix.</p></div>`; DOMElements.welcomePlaceholder.classList.remove('hidden'); }

// --- Detail Context Logic ---

async function renderHistoricalIntel(dishName) {
    const intelContainer = document.getElementById('historical-intel-container');
    if (!intelContainer) return;

    // Identity verification using fuzzy matching across global brain
    const matches = state.allHistoricalChecks.filter(c => isDishMatch(c.dishName, dishName));

    if (matches.length === 0) {
        intelContainer.innerHTML = `<span class="text-slate-500 font-black tracking-widest italic uppercase text-[10px]">Zero Historical Data Points</span>`;
        return;
    }

    const recent = [...matches].sort((a,b) => (b.timestamp || "").localeCompare(a.timestamp || "")).slice(0, 5);
    const avg = (recent.reduce((sum, c) => sum + (c.aiCheckResult?.score || 0), 0) / recent.length).toFixed(1);

    intelContainer.innerHTML = `
        <div class="flex items-center gap-5 animate-in fade-in duration-700">
            <div class="flex items-center gap-2">${recent.map(c => `<div class="w-3 h-3 rounded-full ${c.aiCheckResult?.score > 7 ? 'bg-green-500' : 'bg-indigo-500'} shadow-lg ring-2 ring-white/5"></div>`).join('')}</div>
            <div class="h-5 w-px bg-slate-800"></div>
            <span class="text-[11px] font-black text-indigo-400 uppercase tracking-widest italic">${avg} Quality index (${matches.length} Total Logs Tracked)</span>
        </div>
    `;
}

