                    <div class="grid grid-cols-1 xs:grid-cols-2 gap-6">${(dish.dishIngredients || []).map(ing => `<label class="flex items-center justify-between p-6 rounded-[2rem] bg-slate-800/80 border border-slate-700 cursor-pointer group shadow-xl"><div class="flex items-center gap-5 overflow-hidden"><input type="checkbox" name="selectedIngredients" value="${ing.name}" class="h-7 w-7 text-indigo-600 bg-slate-950 rounded-xl" ${(formData.selectedIngredients || []).includes(ing.name) ? 'checked' : ''}><span class="truncate font-black text-slate-200 text-sm tracking-tight uppercase italic">${ing.name}</span></div><span class="text-[12px] font-black text-slate-500 font-mono opacity-60">${ing.weight}</span></label>`).join('')}</div>
