                <p class="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-8">Performance Trajectory</p>
                <div class="h-60 w-full"><canvas id="audit-chart"></canvas></div>
            </div>
        </div>
        <div class="grid grid-cols-1 md:grid-cols-2 gap-6 sm:gap-8 mb-8">
            <div class="bg-slate-800 rounded-[2.5rem] sm:rounded-[3.5rem] p-8 sm:p-12 border border-slate-700/50 shadow-2xl">
                <p class="text-[10px] font-black text-green-400 uppercase tracking-widest mb-6 flex items-center gap-4"><span class="h-2 w-2 rounded-full bg-green-500 shadow-lg"></span>Confirmed Strengths</p>
                <ul class="space-y-4">
                    ${audit.positives.map(p => `<li class="text-xs text-slate-300 flex items-start gap-4 leading-relaxed font-medium"><div class="h-1.5 w-1.5 rounded-full bg-slate-600 mt-1.5 flex-shrink-0"></div>${p}</li>`).join('')}
                </ul>
            </div>
            <div class="bg-slate-800 rounded-[2.5rem] sm:rounded-[3.5rem] p-8 sm:p-12 border border-slate-700/50 shadow-2xl">
                <p class="text-[10px] font-black text-yellow-400 uppercase tracking-widest mb-6 flex items-center gap-4"><span class="h-2 w-2 rounded-full bg-yellow-500 shadow-lg"></span>Recursive Deficits</p>
                <ul class="space-y-4">
                    ${audit.improvements.map(d => `<li class="text-xs text-slate-300 flex items-start gap-4 leading-relaxed font-medium"><div class="h-1.5 w-1.5 rounded-full bg-slate-600 mt-1.5 flex-shrink-0"></div>${d}</li>`).join('')}
