function renderDailySummaryTable() {
    if (!state.menu || !state.menu.dishes) return;
    const sorted = [...state.menu.dishes].sort((a,b) => a.dishLetter.localeCompare(b.dishLetter));
    const createTableHTML = (list, type) => {
        if (list.length === 0) return '';
        const headerColor = type === 'hot' ? 'bg-red-600/30' : type === 'cold' ? 'bg-blue-600/30' : 'bg-slate-700/50';
        return `<div class="bg-slate-800/40 rounded-[2rem] sm:rounded-[2.5rem] border border-slate-700/50 overflow-hidden shadow-2xl backdrop-blur-xl h-full flex flex-col min-h-[150px]"><div class="px-6 py-4 sm:px-8 sm:py-5 text-[10px] sm:text-[11px] font-black uppercase tracking-[0.3em] text-white border-b border-white/5 ${headerColor}">${type} Recap</div><div class="overflow-x-auto custom-scrollbar flex-grow"><table class="min-w-full divide-y divide-slate-800 text-[10px] sm:text-[11px]"><thead class="bg-slate-950/60 text-slate-500 uppercase"><tr><th class="px-4 py-3 sm:px-6 sm:py-4 text-left">ID</th><th class="px-4 py-3 sm:px-6 sm:py-4 text-left">Dish</th><th class="px-4 py-3 sm:px-6 sm:py-4 text-left">°C</th><th class="px-4 py-3 sm:px-6 sm:py-4 text-left">AI</th></tr></thead><tbody class="divide-y divide-slate-800/50">${list.map(dish => {
            const check = state.checkedData[dish.dishLetter];
            const vt = (check?.temperatures || []).map(t => parseFloat(t)).filter(t => !isNaN(t));
            const ai = check?.aiCheckResult?.score || '-';
            return `<tr class="hover:bg-slate-700/40 cursor-pointer transition-colors ${!check ? 'opacity-25' : ''}" onclick="window.handleSelectDish('${dish.dishLetter}')"><td class="px-4 py-4 sm:px-6 sm:py-5 font-black text-indigo-400">${dish.dishLetter}</td><td class="px-4 py-4 sm:px-6 sm:py-5 text-slate-200 font-black uppercase truncate max-w-[100px] sm:max-w-[140px] italic">${dish.dishName}</td><td class="px-4 py-4 sm:px-6 sm:py-5 text-slate-300 font-mono">${vt.length ? (vt.reduce((a,b)=>a+b,0)/vt.length).toFixed(1) + '°' : '-'}</td><td class="px-4 py-4 sm:px-6 sm:py-5 font-black ${check && ai > 7 ? 'text-green-400' : 'text-indigo-400'}">${ai}</td></tr>`;
        }).join('')}</tbody></table></div></div>`;
    };
    let splitHtml = `<div id="cold-summary">${createTableHTML(sorted.filter(d => d.dishType === 'cold'), 'cold')}</div><div id="hot-summary">${createTableHTML(sorted.filter(d => d.dishType === 'hot'), 'hot')}</div>`;
    const extras = sorted.filter(d => d.dishType !== 'cold' && d.dishType !== 'hot');
    if (extras.length > 0) splitHtml += `<div class="full-width-section">${createTableHTML(extras, 'additional')}</div>`;
    DOMElements.dailySummaryContainer.innerHTML = splitHtml;
}

