                        </button>
                    `).join('')}
                </div>
            </div>
        `;
    };

    html += `<div class="animate-in fade-in duration-700">`;
    html += renderList(state.historicalDishLibrary.filter(d => d.type === 'hot'), 'Hot Kitchen Archives', 'bg-red-500');
    html += renderList(state.historicalDishLibrary.filter(d => d.type === 'cold'), 'Cold Kitchen Archives', 'bg-blue-500');
    html += renderList(state.historicalDishLibrary.filter(d => d.type !== 'hot' && d.type !== 'cold'), 'Supplemental Assets', 'bg-slate-500');
    html += `</div>`;

    DOMElements.auditResultsContainer.innerHTML = html;
};

window.runAuditForDish = async (dishName) => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
    DOMElements.auditResultsContainer.innerHTML = `<div class="flex flex-col items-center justify-center py-32"><div class="relative w-20 h-20"><div class="absolute inset-0 border-8 border-indigo-500 border-t-transparent rounded-full animate-spin"></div></div></div>`;

    try {
        const matches = state.allHistoricalChecks.filter(c => isDishMatch(c.dishName, dishName));
        matches.sort((a,b) => (a.pathDate || a.timestamp || "").localeCompare(b.pathDate || b.timestamp || ""));
        const scores = matches.map(c => c.aiCheckResult?.score).filter(s => typeof s === 'number');
        const labels = matches.map(c => c.pathDate || 'Legacy');
        const avgStability = scores.length ? (scores.reduce((a,b)=>a+b,0) / scores.length).toFixed(1) : "0.0";

        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const response = await ai.models.generateContent({
            model: 'gemini-3-pro-preview', 
            contents: `Audit Analysis for: "${dishName}". Data: ${matches.map(c => c.aiCheckResult?.score || '?').join(',')}. Output JSON: { "stability_rating": ${avgStability}, "positives": string[], "improvements": string[], "temporal_insights": string[], "summary": string }`,
            config: { responseMimeType: "application/json", temperature: 0.1 }
        });
        const auditData = JSON.parse(response.text);
        renderAuditReport(auditData, matches, dishName, { scores, labels });
    } catch (e) {
        DOMElements.auditResultsContainer.innerHTML = `<div class="p-10 bg-red-950/20 rounded-[3rem] text-center"><p class="text-xs text-red-400 font-black uppercase">Logic fault.</p></div>`;
    }
};

function renderAuditReport(audit, history, dishName, chartData) {
    DOMElements.auditResultsContainer.innerHTML = `
        <div class="space-y-8">
            <button onclick="window.renderAuditDishLibrary()" class="px-8 py-4 text-[10px] font-black rounded-2xl bg-slate-800 text-slate-300 border border-slate-700 uppercase tracking-widest">Back to Library</button>
            <div class="bg-indigo-600 rounded-[2.5rem] p-8 text-white shadow-2xl">
                <h4 class="text-2xl font-black uppercase italic">${dishName}</h4>
                <p class="text-sm opacity-90 mt-4">"${audit.summary}"</p>
            </div>
            <div class="h-64 bg-slate-800 rounded-[2.5rem] p-8 border border-slate-700">
                <canvas id="audit-chart"></canvas>
            </div>
        </div>
    `;
    initAuditChart(chartData);
}

function initAuditChart(chartData) {
    const ctx = document.getElementById('audit-chart');
    if (!ctx) return;
    new Chart(ctx, {
        type: 'line',
        data: {
            labels: chartData.labels,
            datasets: [{
                data: chartData.scores,
                borderColor: '#6366f1',
                tension: 0.3,
                fill: true,
                backgroundColor: 'rgba(99, 102, 241, 0.1)'
            }]
        },
        options: { responsive: true, maintainAspectRatio: false, plugins: { legend: { display: false } } }
    });
}

// --- Real-time Listeners ---

function listenToGlobalHistory() {
    onValue(ref(database, 'quality-checks'), (snapshot) => {
        const data = snapshot.val();
        const logs = discoverLogs(data);
        state.allHistoricalChecks = logs;
        state.totalRecordsFound = logs.length;
        const dishMap = new Map();
        logs.forEach(log => {
            const key = normalizeName(log.dishName);
            if (!dishMap.has(key)) {
                dishMap.set(key, { name: log.dishName, type: log.dishType || 'extras', count: 1 });
            } else {
                dishMap.get(key).count += 1;
            }
        });
        state.historicalDishLibrary = Array.from(dishMap.values()).sort((a,b) => b.count - a.count);
        state.isLibraryLoaded = true;
    });
}

