function renderCameraCapture(item, initialImage) {
    const container = document.getElementById('camera-container');
    if (!container) return;
    container.innerHTML = `<div id="camera-placeholder" class="w-full aspect-square rounded-[2rem] bg-slate-950 border-4 border-dashed border-slate-800 flex flex-col items-center justify-center text-slate-700 cursor-pointer hover:border-indigo-500/50 transition-all"><svg xmlns="http://www.w3.org/2000/svg" class="h-12 w-12 mb-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z"></path></svg><span class="text-[11px] uppercase font-black tracking-widest">Capture</span></div><div id="camera-view" class="w-full aspect-square rounded-[2rem] bg-black hidden relative overflow-hidden"><video id="camera-video" autoplay playsinline class="w-full h-full object-cover"></video><button type="button" id="capture-btn" class="absolute bottom-6 left-1/2 -translate-x-1/2 w-16 h-16 rounded-full border-4 border-white/20 bg-indigo-600 shadow-2xl"></button></div><div id="image-preview" class="w-full aspect-square rounded-[2rem] relative hidden border-4 border-slate-700 overflow-hidden shadow-2xl"><img id="preview-img" class="w-full h-full object-cover"/><button type="button" id="retake-btn" class="absolute bottom-4 left-1/2 -translate-x-1/2 px-6 py-2 bg-white text-slate-900 rounded-full text-[10px] font-black uppercase">Retake</button></div>`;
    const videoEl = container.querySelector('#camera-video'); const form = DOMElements.dishCardContainer.querySelector('form'); let stream = null;
    container.querySelector('#camera-placeholder').onclick = async () => { try { stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } }); videoEl.srcObject = stream; container.querySelector('#camera-placeholder').classList.add('hidden'); container.querySelector('#camera-view').classList.remove('hidden'); } catch (e) { alert("Camera offline."); } };
    container.querySelector('#capture-btn').onclick = () => { const canvas = document.createElement('canvas'); canvas.width = 1024; canvas.height = 1024; canvas.getContext('2d').drawImage(videoEl, 0, 0, 1024, 1024); const dataUrl = canvas.toDataURL('image/jpeg', 0.95); container.querySelector('#preview-img').src = dataUrl; form.dataset.capturedImage = dataUrl; if (stream) stream.getTracks().forEach(t => t.stop()); container.querySelector('#camera-view').classList.add('hidden'); container.querySelector('#image-preview').classList.remove('hidden'); };
    container.querySelector('#retake-btn').onclick = () => { container.querySelector('#image-preview').classList.add('hidden'); container.querySelector('#camera-placeholder').classList.remove('hidden'); };
    if (initialImage) { container.querySelector('#preview-img').src = initialImage; form.dataset.capturedImage = initialImage; container.querySelector('#camera-placeholder').classList.add('hidden'); container.querySelector('#image-preview').classList.remove('hidden'); }
}

async function handleAiCheck(dish, capturedImageDataUrl) {
    const feedbackContainer = document.getElementById('ai-feedback-container'); if (!feedbackContainer) return;
    feedbackContainer.innerHTML = `<div class="p-8 border-2 border-indigo-500/30 bg-indigo-900/10 rounded-[2rem] flex items-center justify-center"><p class="font-black text-indigo-400 text-[10px] uppercase animate-pulse">Analyzing Compliance...</p></div>`;
    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const result = await ai.models.generateContent({ model: 'gemini-3-pro-preview', contents: { parts: [ { text: `Quality Audit '${dish.dishName}'. JSON: { "score": 1-10, "positives": string[], "improvements": string[], "overall_comment": string }` }, { inlineData: { mimeType: 'image/jpeg', data: capturedImageDataUrl.split(',')[1] } } ] }, config: { responseMimeType: "application/json" } });
        const feedbackData = JSON.parse(result.text); document.getElementById('dish-form').dataset.aiFeedback = JSON.stringify(feedbackData); renderAiFeedback(feedbackData);
    } catch (e) { feedbackContainer.innerHTML = ''; }
}

function renderAiFeedback(feedbackData) {
    const container = document.getElementById('ai-feedback-container'); if (!container || !feedbackData) return;
    container.innerHTML = `<div class="bg-slate-900/90 p-8 rounded-[2rem] border border-slate-700/50"><div class="flex justify-between items-center mb-6"><span class="text-[10px] font-black uppercase text-indigo-400 tracking-widest">Neural Insight</span><span class="text-xl font-black text-white bg-indigo-600 px-6 py-2 rounded-xl italic">${feedbackData.score}/10</span></div><p class="text-xs italic text-slate-400">${feedbackData.overall_comment}</p></div>`;
}

async function renderHistoricalIntel(dishName) {
    const intelContainer = document.getElementById('historical-intel-container');
    if (!intelContainer) return;
    const matches = state.allHistoricalChecks.filter(c => isDishMatch(c.dishName, dishName));
    if (matches.length === 0) return;
    const avg = (matches.reduce((sum, c) => sum + (c.aiCheckResult?.score || 0), 0) / matches.length).toFixed(1);
    intelContainer.innerHTML = `<span class="text-[10px] font-black text-indigo-400 uppercase italic">Historical Index: ${avg} (${matches.length} Records)</span>`;
}

