        button.className = `group relative flex flex-col items-center justify-center p-4 border border-slate-700 rounded-2xl bg-slate-800 hover:scale-105 active:scale-95 transition-all`;
        button.onclick = () => { state.selectedDish = dish; state.selectedPrepItem = null; showView('detail'); renderDishCard(); };
        button.innerHTML = `
            <div class="mb-2 h-10 w-10 rounded-xl flex items-center justify-center text-xs font-black shadow-2xl ${dish.dishType === 'hot' ? 'bg-red-500' : 'bg-indigo-600'} text-white uppercase italic">${dish.dishLetter}</div>
            <p class="font-black text-[9px] text-slate-300 text-center uppercase h-8 flex items-center group-hover:text-white leading-tight">${dish.dishName}</p>
        `;
        DOMElements.dishGridContainer.appendChild(button);
    });
}

function renderDailySummaryTable() {
    if (!state.menu) return;
    DOMElements.dailySummaryContainer.innerHTML = `<div class="p-10 text-center uppercase font-black tracking-widest opacity-20">Summary Engine Ready</div>`;
}

function renderWelcomePlaceholder() { 
    DOMElements.welcomePlaceholder.innerHTML = `<div class="py-20 text-center opacity-30 uppercase font-black tracking-widest">No Operational Blueprint Detected</div>`; 
}

window.handleSelectDish = (letter) => { 
    const dish = state.menu.dishes.find(d => d.dishLetter === letter); 
    if(dish) { state.selectedDish = dish; state.selectedPrepItem = null; showView('detail'); renderDishCard(); } 
