function renderCameraCapture(item, initialImage) {
    const container = document.getElementById('camera-container');
    if (!container) return;
    container.innerHTML = `<div id="camera-placeholder" class="w-full aspect-square rounded-[2rem] bg-slate-950 border-4 border-dashed border-slate-800 flex flex-col items-center justify-center text-slate-700 cursor-pointer hover:border-indigo-500 transition-colors"><svg xmlns="http://www.w3.org/2000/svg" class="h-12 w-12 mb-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z"></path></svg><span class="text-[10px] font-black uppercase tracking-widest">Capture Specimen</span></div><div id="camera-view" class="w-full aspect-square rounded-[2rem] bg-black hidden relative overflow-hidden"><video id="camera-video" autoplay playsinline class="w-full h-full object-cover"></video><button type="button" id="capture-btn" class="absolute bottom-6 left-1/2 -translate-x-1/2 w-20 h-20 rounded-full border-8 border-white/20 bg-indigo-600 shadow-2xl active:scale-90 transition-all"></button></div><div id="image-preview" class="w-full aspect-square rounded-[2rem] relative hidden border-4 border-slate-700 overflow-hidden shadow-2xl"><img id="preview-img" class="w-full h-full object-cover"/><button type="button" id="retake-btn" class="absolute bottom-4 left-1/2 -translate-x-1/2 px-8 py-3 bg-white text-slate-900 rounded-full text-[10px] font-black uppercase shadow-2xl">Recapture</button></div>`;
    const videoEl = container.querySelector('#camera-video'); const form = DOMElements.dishCardContainer.querySelector('form'); let stream = null;
    container.querySelector('#camera-placeholder').onclick = async () => { try { stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } }); videoEl.srcObject = stream; container.querySelector('#camera-placeholder').classList.add('hidden'); container.querySelector('#camera-view').classList.remove('hidden'); } catch (e) { alert("Camera offline."); } };
    container.querySelector('#capture-btn').onclick = () => { const canvas = document.createElement('canvas'); canvas.width = 1024; canvas.height = 1024; canvas.getContext('2d').drawImage(videoEl, 0, 0, 1024, 1024); const dataUrl = canvas.toDataURL('image/jpeg', 0.95); container.querySelector('#preview-img').src = dataUrl; form.dataset.capturedImage = dataUrl; if (stream) stream.getTracks().forEach(t => t.stop()); container.querySelector('#camera-view').classList.add('hidden'); container.querySelector('#image-preview').classList.remove('hidden'); };
    container.querySelector('#retake-btn').onclick = () => { container.querySelector('#image-preview').classList.add('hidden'); container.querySelector('#camera-placeholder').classList.remove('hidden'); };
    if (initialImage) { container.querySelector('#preview-img').src = initialImage; form.dataset.capturedImage = initialImage; container.querySelector('#camera-placeholder').classList.add('hidden'); container.querySelector('#image-preview').classList.remove('hidden'); }
}

// --- Navigation Controller ---

function showView(viewName) {
    state.currentView = viewName;
    DOMElements.mainView.classList.toggle('hidden', viewName !== 'dashboard');
    DOMElements.prepView.classList.toggle('hidden', viewName !== 'prep');
    DOMElements.aiAgentView.classList.toggle('hidden', viewName !== 'audit');
    DOMElements.dishDetailView.classList.toggle('hidden', viewName !== 'detail');

    const active = "bg-indigo-600 text-white shadow-2xl shadow-indigo-600/30";
    const activePrep = "bg-emerald-600 text-white shadow-2xl shadow-emerald-600/30";
    const inactive = "text-slate-400 hover:text-white";

    DOMElements.navDashboardBtn.className = `px-5 py-2.5 text-[10px] font-black rounded-xl transition-all uppercase ${viewName === 'dashboard' ? active : inactive}`;
    DOMElements.navAuditBtn.className = `px-5 py-2.5 text-[10px] font-black rounded-xl transition-all uppercase ${viewName === 'audit' ? active : inactive}`;
    DOMElements.navPrepBtn.className = `px-5 py-2.5 text-[10px] font-black rounded-xl transition-all uppercase ${viewName === 'prep' ? activePrep : inactive}`;

    if (viewName === 'audit') renderAuditDishLibrary();
    if (viewName === 'prep') renderPrepView();
    if (viewName === 'dashboard') renderApp();
}

function fetchCheckData() { 
    state.isCheckDataLoading = true; 
    onValue(ref(database, `quality-checks/${state.selectedDate}`), (snapshot) => { state.checkedData = snapshot.val() || {}; state.isCheckDataLoading = false; renderApp(); }); 
    onValue(ref(database, `prep-checks/${state.selectedDate}`), (snapshot) => { state.prepData = snapshot.val() || {}; if(state.currentView === 'prep') renderPrepView(); }); 
}

function fetchMenu() { 
    state.isMenuLoading = true; 
    const weekId = getWeekId(new Date(state.selectedDate + 'T12:00:00Z')); 
    onValue(ref(database, `menus/${weekId}`), (snapshot) => { state.menu = snapshot.val() || null; state.isMenuLoading = false; renderApp(); if(state.currentView === 'prep') renderPrepView(); }); 
}

DOMElements.navDashboardBtn.onclick = () => showView('dashboard');
DOMElements.navPrepBtn.onclick = () => showView('prep');
DOMElements.navAuditBtn.onclick = () => showView('audit');
DOMElements.settingsBtn.onclick = () => DOMElements.settingsModal.classList.remove('hidden');
DOMElements.settingsCloseBtn.onclick = () => DOMElements.settingsModal.classList.add('hidden');
DOMElements.backToMenuBtn.onclick = () => showView(state.selectedPrepItem ? 'prep' : 'dashboard');

DOMElements.settingsSaveBtn.onclick = async () => {
    const val = DOMElements.jsonInput.value.trim(); if (!val) return;
    try {
        const p = JSON.parse(val);
        const dishes = p.dishes.filter(d => d.stickerNo && d.stickerNo !== 'addons').map(d => ({ dishLetter: d.stickerNo, dishName: d.variantName, dishImage: d.webUrl, dishType: ['hot', 'cold'].includes(d.type) ? d.type : 'extras', dishIngredients: (d.ingredients || []).map(i => ({name: i.name, weight: i.amount + 'g'})) }));
        const menuWeekId = getWeekId(new Date(p.startDate + 'T12:00:00Z'));
        await set(ref(database, `menus/${menuWeekId}`), { dishes, startDate: p.startDate });
        DOMElements.settingsModal.classList.add('hidden'); fetchMenu();
    } catch (e) { DOMElements.settingsError.textContent = "Blueprint Sync Failure."; }
};

function renderApp() {
    DOMElements.loadingIndicator.classList.toggle('hidden', !state.isMenuLoading && !state.isCheckDataLoading);
    if (state.menu && state.menu.dishes.length > 0) {
        DOMElements.welcomePlaceholder.classList.add('hidden');
        renderDishSelectionGrid();
    } else {
        DOMElements.dishGridContainer.innerHTML = `<div class="col-span-full py-20 text-center opacity-20 uppercase font-black tracking-widest italic">Sync Weekly Manifest via Settings</div>`;
    }
    renderDateSelector();
}

function renderDateSelector() {
    const viewDate = getStartOfWeek(new Date(state.selectedDate + 'T12:00:00Z'));
    DOMElements.dateButtonsContainer.innerHTML = '';
    Array.from({ length: 5 }).forEach((_, i) => {
        const d = new Date(viewDate); d.setDate(viewDate.getDate() + i);
        const dayString = d.toISOString().split('T')[0];
        const isSelected = dayString === state.selectedDate;
        const button = document.createElement('button');
        button.className = `flex flex-col items-center justify-center w-12 h-16 rounded-xl transition-all shadow-lg ${isSelected ? 'bg-indigo-600 text-white ring-2 ring-indigo-400/20' : 'bg-slate-800 text-slate-500 hover:text-white border border-slate-700/50'}`;
        button.innerHTML = `<span class="text-[8px] font-black uppercase mb-1">${d.toLocaleDateString('en-US', { weekday: 'short' })}</span><span class="text-base font-black">${d.getDate()}</span>`;
        button.onclick = () => { state.selectedDate = dayString; fetchCheckData(); };
        DOMElements.dateButtonsContainer.appendChild(button);
    });
}

