// --- Utilities & Shared Logic ---

const normalizeName = (name) => {
    if (!name) return "";
    return name.toLowerCase().replace(/&/g, 'and').replace(/[^\w\s]/gi, '').replace(/\s+/g, ' ').trim();
};

const isDishMatch = (n1, n2) => normalizeName(n1) === normalizeName(n2);

const getWeekId = (date) => {
    const d = new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()));
    d.setUTCDate(d.getUTCDate() + 4 - (d.getUTCDay() || 7));
    const yearStart = new Date(Date.UTC(d.getUTCFullYear(), 0, 1));
    const weekNo = Math.ceil((((d.getTime() - yearStart.getTime()) / 86400000) + 1) / 7);
    return `${d.getUTCFullYear()}-${String(weekNo).padStart(2, '0')}`;
};

const getStartOfWeek = (date) => {
    const d = new Date(date);
    const day = d.getDay();
    const diff = d.getDate() - day + (day === 0 ? -6 : 1);
    return new Date(d.setDate(diff));
};

const discoverLogs = (node, found = [], dateContext = null) => {
    if (!node || typeof node !== 'object') return found;

    if (node.dishLetter && (node.timestamp || node.aiCheckResult || node.temperatures)) {
        let name = node.dishName;
        if (!name && state.menu) {
            const match = state.menu.dishes.find(d => d.dishLetter === node.dishLetter);
            if (match) name = match.dishName;
        }

        found.push({ 
            ...node, 
            dishName: name || `Dish ${node.dishLetter}`,
            pathDate: dateContext || node.date || 'Historical Log' 
        });
        return found;
    }

    Object.entries(node).forEach(([key, val]) => {
        const isDateKey = /^\d{4}-\d{2}-\d{2}$/.test(key);
        discoverLogs(val, found, isDateKey ? key : dateContext);
    });
    return found;
};

function saveCheckData(data) {
    return set(ref(database, `quality-checks/${data.date}/${data.dishLetter}`), data);
}

// --- Kitchen Prep Logic ---

const PREP_KEYWORDS = ['rice', 'curry', 'sauce', 'gravy', 'dal', 'veg', 'meat', 'chicken', 'base', 'paste', 'stew', 'broth', 'cooked'];

function getPrepIcon(name) {
    const n = name.toLowerCase();
    if (n.includes('rice')) return '🍚';
    if (n.includes('curry') || n.includes('sauce') || n.includes('gravy')) return '🥫';
    if (n.includes('veg')) return '🥦';
    if (n.includes('chicken') || n.includes('meat') || n.includes('beef')) return '🥩';
    if (n.includes('dal') || n.includes('stew')) return '🍲';
    return '🥘';
}

function extractPrepItems(menu) {
    if (!menu || !menu.dishes) return [];
    const uniqueIngredients = new Set();
    const prepItems = [];
    menu.dishes.forEach(dish => {
        (dish.dishIngredients || []).forEach(ing => {
            const lowerName = ing.name.trim().toLowerCase();
            if (PREP_KEYWORDS.some(k => lowerName.includes(k)) && !uniqueIngredients.has(lowerName)) {
                uniqueIngredients.add(lowerName);
                prepItems.push({ id: 'prep_' + lowerName.replace(/\s+/g, '_'), name: ing.name.trim(), icon: getPrepIcon(ing.name) });
            }
        });
    });
    return prepItems;
}

