                                // Average Weight
                                const weights = (check?.weights || []).map(w => parseFloat(w)).filter(w => !isNaN(w));
                                const avgWgt = weights.length ? (weights.reduce((a,b)=>a+b,0)/weights.length).toFixed(0) + 'g' : '--';

                                // Theoretical Weight calculation
                                const theoWgtVal = (dish.dishIngredients || []).reduce((acc, ing) => {
                                    const amount = parseFloat(ing.weight);
                                    return acc + (isNaN(amount) ? 0 : amount);
                                }, 0);
                                const theoWgt = theoWgtVal > 0 ? theoWgtVal + 'g' : '--';

                                // AI Rating
                                const aiRating = check?.aiCheckResult?.score ? check.aiCheckResult.score + '/10' : '--';

                                return `
                                    <tr onclick="window.handleSelectDish('${dish.dishLetter}')" class="hover:bg-slate-800/50 cursor-pointer transition-colors ${!check ? 'opacity-40' : ''}">
