// --- Historical Performance Matrix ---

function listenToGlobalHistory() {
    onValue(ref(database, 'quality-checks'), (snapshot) => {
        const data = snapshot.val();
        const logs = discoverLogs(data);
        state.allHistoricalChecks = logs;
        state.totalRecordsFound = logs.length;

        const dishMap = new Map();
        logs.forEach(log => {
            const key = normalizeName(log.dishName);
            if (!dishMap.has(key)) {
                dishMap.set(key, { name: log.dishName, type: log.dishType || 'extras', count: 1 });
            } else {
                dishMap.get(key).count += 1;
            }
        });
        state.historicalDishLibrary = Array.from(dishMap.values()).sort((a,b) => b.count - a.count);
        state.isLibraryLoaded = true;
        if (state.currentView === 'audit') renderAuditDishLibrary();
    });
}

function renderAuditDishLibrary() {
    let html = `
        <div class="mb-8 flex flex-col sm:flex-row items-center justify-between gap-6 bg-slate-800/40 p-6 sm:p-10 rounded-[2.5rem] border border-slate-700/50 shadow-2xl">
            <div>
                <h3 class="text-xl font-black text-white italic tracking-tighter uppercase">Historical Matrix</h3>
                <p class="text-[10px] font-black text-indigo-400 uppercase tracking-[0.4em] mt-2">${state.totalRecordsFound} Data Points Analyzed</p>
            </div>
            <div class="px-6 py-4 bg-slate-900/80 rounded-[1.5rem] border border-slate-800 text-center">
                <span class="block text-xl font-black text-white italic">${state.historicalDishLibrary.length}</span>
                <span class="text-[9px] font-black text-slate-500 uppercase tracking-widest">Logged Dishes</span>
            </div>
