        <div class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
            ${state.historicalDishLibrary.map(d => `
                <button onclick="window.runAuditForDish('${d.name.replace(/'/g, "\\'")}')" class="group flex flex-col p-6 bg-slate-800/40 border border-slate-700/50 rounded-[2rem] hover:border-indigo-500 hover:bg-slate-800 transition-all text-left shadow-2xl">
                    <p class="text-[14px] font-black text-slate-200 group-hover:text-white mb-3 uppercase tracking-tight italic truncate">${d.name}</p>
                    <span class="text-[9px] text-indigo-400 font-black px-3 py-1 bg-indigo-500/10 rounded-xl border border-indigo-500/20">${d.count} Logs Found</span>
