window.runAuditForDish = async (dishName) => {
    DOMElements.auditResultsContainer.innerHTML = `<div class="flex justify-center py-20"><div class="w-12 h-12 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin"></div></div>`;
    const matches = state.allHistoricalChecks.filter(c => isDishMatch(c.dishName, dishName));
    const scores = matches.map(c => c.aiCheckResult?.score || 0);
    const labels = matches.map(c => c.pathDate);

    DOMElements.auditResultsContainer.innerHTML = `
        <div class="space-y-6">
            <button onclick="window.renderAuditDishLibrary()" class="px-6 py-3 bg-slate-800 rounded-xl text-[10px] font-black uppercase text-slate-400 border border-slate-700">Back to Library</button>
            <div class="bg-indigo-600 p-8 rounded-[2rem] text-white shadow-2xl">
                <h4 class="text-xl font-black uppercase italic">${dishName}</h4>
                <p class="text-sm mt-2 opacity-80">Aggregate consistency profile from ${matches.length} historical logs.</p>
            </div>
            <div class="h-64 bg-slate-900 rounded-[2rem] p-6 border border-slate-800">
                <canvas id="audit-chart"></canvas>
            </div>
        </div>
    `;

    const ctx = document.getElementById('audit-chart');
    if (ctx) {
        new Chart(ctx, {
            type: 'line',
            data: { labels, datasets: [{ data: scores, borderColor: '#6366f1', tension: 0.3, fill: true, backgroundColor: 'rgba(99, 102, 241, 0.1)' }] },
            options: { responsive: true, maintainAspectRatio: false, plugins: { legend: { display: false } } }
        });
    }
};

// --- Daily Summary Matrix ---

function renderDailySummaryTable() {
    if (!state.menu || !state.menu.dishes) return;

    const sorted = [...state.menu.dishes].sort((a,b) => a.dishLetter.localeCompare(b.dishLetter));

    const createTableHTML = (list, title, isHot) => {
        if (list.length === 0) return '';
        const accentColorClass = isHot ? 'text-red-500' : 'text-blue-500';
        const bgHeaderClass = isHot ? 'bg-red-950/20' : 'bg-blue-950/20';
        const borderClass = isHot ? 'border-red-900/50' : 'border-blue-900/50';

        return `
            <div class="bg-slate-900/80 rounded-[2rem] border ${borderClass} overflow-hidden shadow-2xl mb-10 backdrop-blur-md">
                <div class="px-6 py-5 ${bgHeaderClass} border-b ${borderClass} flex justify-between items-center">
                    <h3 class="text-[12px] font-black ${accentColorClass} uppercase tracking-[0.2em] italic">${title} Quality Summary</h3>
                </div>
                <div class="overflow-x-auto">
                    <table class="w-full text-left text-[11px] table-auto">
                        <thead class="bg-slate-950/80 text-[10px] text-slate-400 uppercase font-black tracking-widest border-b border-slate-800">
                            <tr>
                                <th class="px-5 py-4 w-12 text-center">ID</th>
                                <th class="px-5 py-4">Dish Name</th>
                                <th class="px-5 py-4 text-center">Avg Wgt</th>
                                <th class="px-5 py-4 text-center">Theo Wgt</th>
                                <th class="px-5 py-4 text-center">Avg Temp</th>
                                <th class="px-5 py-4 text-center">AI Rate</th>
                            </tr>
                        </thead>
                        <tbody class="divide-y divide-slate-800/50">
                            ${list.map(dish => {
                                const check = state.checkedData[dish.dishLetter];

                                // Average Temp
                                const temps = (check?.temperatures || []).map(t => parseFloat(t)).filter(t => !isNaN(t));
                                const avgTemp = temps.length ? (temps.reduce((a,b)=>a+b,0)/temps.length).toFixed(1) + '°' : '--';

                                // Average Weight
                                const weights = (check?.weights || []).map(w => parseFloat(w)).filter(w => !isNaN(w));
                                const avgWgt = weights.length ? (weights.reduce((a,b)=>a+b,0)/weights.length).toFixed(0) + 'g' : '--';

                                // Theoretical Weight calculation
                                const theoWgtVal = (dish.dishIngredients || []).reduce((acc, ing) => {
                                    const amount = parseFloat(ing.weight);
                                    return acc + (isNaN(amount) ? 0 : amount);
                                }, 0);
                                const theoWgt = theoWgtVal > 0 ? theoWgtVal + 'g' : '--';

                                // AI Rating
                                const aiRating = check?.aiCheckResult?.score ? check.aiCheckResult.score + '/10' : '--';

                                return `
                                    <tr onclick="window.handleSelectDish('${dish.dishLetter}')" class="group hover:bg-slate-800/80 cursor-pointer transition-all duration-200 ${!check ? 'opacity-40 grayscale-[0.5]' : ''}">
                                        <td class="px-5 py-5 font-black ${accentColorClass} text-center text-[12px] group-hover:scale-110 transition-transform">${dish.dishLetter}</td>
                                        <td class="px-5 py-5 font-black uppercase italic ${accentColorClass} tracking-tight">${dish.dishName}</td>
                                        <td class="px-5 py-5 font-mono text-emerald-400 text-center text-[11px]">${avgWgt}</td>
                                        <td class="px-5 py-5 font-mono text-slate-500 text-center text-[11px]">${theoWgt}</td>
                                        <td class="px-5 py-5 font-mono text-orange-400 text-center text-[11px] font-black">${avgTemp}</td>
                                        <td class="px-5 py-5 text-center">
                                            <span class="px-3 py-1 bg-indigo-500/10 border border-indigo-500/20 rounded-full font-black text-indigo-400 text-[10px]">${aiRating}</span>
                                        </td>
                                    </tr>
                                `;
                            }).join('')}
                        </tbody>
                    </table>
                </div>
            </div>
        `;
    };

    DOMElements.dailySummaryContainer.innerHTML = `
        <div class="grid grid-cols-1 lg:grid-cols-2 gap-10">
            ${createTableHTML(sorted.filter(d => d.dishType === 'hot'), 'Hot', true)}
            ${createTableHTML(sorted.filter(d => d.dishType === 'cold'), 'Cold', false)}
        </div>
        <div class="mt-8">
            ${createTableHTML(sorted.filter(d => d.dishType !== 'hot' && d.dishType !== 'cold'), 'Other', false)}
        </div>
    `;
    DOMElements.dailySummarySection.classList.remove('hidden');
}

