                        ${[0,1,2].map(i => `<input type="text" name="weights" inputmode="decimal" value="${formData.weights[i] || ''}" placeholder="Weight ${i+1}" class="px-6 py-6 bg-slate-950 border border-slate-800 rounded-2xl text-emerald-400 font-mono font-black text-center text-xl outline-none focus:border-emerald-500 shadow-inner">`).join('')}
