            <div class="h-4 w-px bg-slate-800"></div>
            <span class="text-[10px] font-black text-indigo-400 uppercase tracking-widest italic">${avg} Quality index (${matches.length} Total Logs)</span>
        </div>
    `;
}

function renderWelcomePlaceholder() { DOMElements.dishGridContainer.classList.add('hidden'); DOMElements.welcomePlaceholder.innerHTML = `<div class="text-center py-40 bg-slate-800/20 rounded-[4rem] border-2 border-slate-800 border-dashed"><p class="text-[10px] text-slate-500 font-black uppercase tracking-[0.4em] px-10 leading-loose">Operational Vacuum detected. Sync via setup matrix.</p></div>`; DOMElements.welcomePlaceholder.classList.remove('hidden'); }

