async function renderHistoricalIntel(dishName) {
    const intelContainer = document.getElementById('historical-intel-container');
    if (!intelContainer) return;
    const matches = state.allHistoricalChecks.filter(c => isDishMatch(c.dishName, dishName));
    if (matches.length === 0) {
        intelContainer.innerHTML = `<span class="text-slate-500 font-black tracking-widest italic uppercase text-[9px]">Zero Historical Data Points</span>`;
        return;
    }
    const recent = [...matches].sort((a,b) => (b.timestamp || "").localeCompare(a.timestamp || "")).slice(0, 5);
    const avg = (recent.reduce((sum, c) => sum + (c.aiCheckResult?.score || 0), 0) / recent.length).toFixed(1);
    intelContainer.innerHTML = `
        <div class="flex items-center gap-4 animate-in fade-in duration-700">
            <div class="flex items-center gap-1.5">${recent.map(c => `<div class="w-2.5 h-2.5 rounded-full ${c.aiCheckResult?.score > 7 ? 'bg-green-500' : 'bg-indigo-500'} shadow-lg"></div>`).join('')}</div>
            <div class="h-4 w-px bg-slate-800"></div>
            <span class="text-[10px] font-black text-indigo-400 uppercase tracking-widest italic">${avg} Quality index (${matches.length} Total Logs)</span>
        </div>
    `;
}

function renderAuditDishLibrary() {
    DOMElements.auditResultsContainer.innerHTML = '';

    if (state.historicalDishLibrary.length === 0) {
        DOMElements.auditResultsContainer.innerHTML = `<div class="text-center py-20 border-2 border-dashed border-slate-800 rounded-[3rem]"><p class="text-[10px] font-black text-slate-600 uppercase tracking-[0.4em]">No audit data vectors found</p></div>`;
        return;
    }

    const dishStats = {};
    state.allHistoricalChecks.forEach(check => {
        const key = normalizeName(check.dishName);
        if (!dishStats[key]) {
            dishStats[key] = { 
                name: check.dishName, 
                checks: [], 
                scores: [] 
            };
        }
        dishStats[key].checks.push(check);
        if (check.aiCheckResult && typeof check.aiCheckResult.score === 'number') {
            dishStats[key].scores.push(check.aiCheckResult.score);
        }
    });

    const sortedDishes = Object.values(dishStats).sort((a, b) => b.checks.length - a.checks.length);

    sortedDishes.forEach(dish => {
        const avgScore = dish.scores.length ? (dish.scores.reduce((a, b) => a + b, 0) / dish.scores.length).toFixed(1) : 'N/A';
        const scoreColor = avgScore === 'N/A' ? 'text-slate-500' : parseFloat(avgScore) >= 8 ? 'text-green-400' : parseFloat(avgScore) >= 6 ? 'text-yellow-400' : 'text-red-400';
        const lastCheck = dish.checks.sort((a,b) => (b.timestamp || '').localeCompare(a.timestamp || ''))[0];
        const lastDate = lastCheck.timestamp ? new Date(lastCheck.timestamp).toLocaleDateString() : 'Unknown';

        const card = document.createElement('div');
        card.className = "bg-slate-800/40 rounded-[2.5rem] p-8 sm:p-10 border border-slate-700/50 backdrop-blur-sm hover:bg-slate-800/60 transition-all group";
        card.innerHTML = `
            <div class="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-6 mb-8">
                <div>
                    <h3 class="text-xl sm:text-2xl font-black text-white italic uppercase tracking-tight">${dish.name}</h3>
                    <p class="text-[10px] font-black text-slate-500 uppercase tracking-[0.3em] mt-2">Historical Aggregate</p>
                </div>
                <div class="flex items-center gap-4">
                    <div class="px-5 py-3 rounded-2xl bg-indigo-500/10 border border-indigo-500/20 text-[10px] font-black text-indigo-300 uppercase tracking-widest">${dish.checks.length} Checks</div>
                    <div class="px-5 py-3 rounded-2xl bg-slate-900 border border-slate-800 text-xl font-black ${scoreColor} font-mono">${avgScore}</div>
                </div>
            </div>

            <div class="space-y-4">
                <div class="flex justify-between items-center text-[11px] font-bold text-slate-400 border-b border-slate-700/50 pb-2 mb-4 uppercase tracking-wider">
                    <span>Recent Logs</span>
                    <span>Score</span>
                </div>
                ${dish.checks.slice(0, 3).map(check => {
                    const s = check.aiCheckResult?.score || '-';
                    const sCol = s === '-' ? 'text-slate-600' : s >= 8 ? 'text-green-500' : 'text-indigo-400';
                    return `
                        <div class="flex justify-between items-center py-2">
                            <div class="flex items-center gap-3">
                                <div class="w-2 h-2 rounded-full ${s >= 8 ? 'bg-green-500' : 'bg-indigo-500'}"></div>
                                <span class="text-slate-300 text-xs font-medium">${check.timestamp ? new Date(check.timestamp).toLocaleDateString() : 'Historic'}</span>
                            </div>
                            <span class="font-mono font-black ${sCol}">${s}</span>
                        </div>
                    `;
                }).join('')}
            </div>
        `;
        DOMElements.auditResultsContainer.appendChild(card);
    });
}

