                    <div class="px-5 py-3 rounded-2xl bg-slate-900 border border-slate-800 text-xl font-black ${scoreColor} font-mono">${avgScore}</div>
                </div>
            </div>
            <div class="space-y-3">
                <div class="flex justify-between items-center text-[11px] font-bold text-slate-400 border-b border-slate-700/50 pb-2 mb-4 uppercase tracking-wider">
                    <span>Performance Timeline</span>
                    <span>Audit Score</span>
                </div>
        `;

        // Check Rows
        const sortedChecks = dish.checks.sort((a,b) => (b.timestamp || '').localeCompare(a.timestamp || ''));
        sortedChecks.forEach((check, index) => {
            const s = check.aiCheckResult?.score || '-';
            const sCol = s === '-' ? 'text-slate-600' : s >= 8 ? 'text-green-500' : 'text-indigo-400';
            const uniqueId = `detail-${normalizeName(dish.name)}-${index}`;

            // Extract AI Details
            const positives = check.aiCheckResult?.positives || [];
            const improvements = check.aiCheckResult?.improvements || [];
            const comment = check.aiCheckResult?.overall_comment || "No detailed feedback recorded.";
            const temps = (check.temperatures || []).join(', ') || 'N/A';

            cardHtml += `
                <div class="cursor-pointer group/row transition-all duration-300" onclick="document.getElementById('${uniqueId}').classList.toggle('hidden'); document.getElementById('${uniqueId}').classList.toggle('flex');">
                    <div class="flex justify-between items-center py-3 px-2 rounded-xl hover:bg-slate-700/30">
                        <div class="flex items-center gap-4">
                             <div class="w-2.5 h-2.5 rounded-full ${s >= 8 ? 'bg-green-500' : 'bg-indigo-500'} shadow-lg shadow-indigo-500/20"></div>
                             <span class="text-slate-300 text-xs font-bold uppercase tracking-wide">${check.timestamp ? new Date(check.timestamp).toLocaleDateString(undefined, {month:'short', day:'numeric'}) : 'Historic'}</span>
