            const mid = Math.floor(sortedChecks.length / 2);
            const firstHalf = sortedChecks.slice(0, mid);
            const secondHalf = sortedChecks.slice(mid);
            const avg1 = firstHalf.reduce((s, c) => s + (c.aiCheckResult?.score || 0), 0) / firstHalf.length;
            const avg2 = secondHalf.reduce((s, c) => s + (c.aiCheckResult?.score || 0), 0) / secondHalf.length;
