                <div>
                    <h3 class="text-xl sm:text-2xl font-black text-white italic uppercase tracking-tight">${dish.name}</h3>
                    <div class="flex items-center gap-4 mt-3">
                         ${trendHtml}
                         <div class="w-1 h-1 bg-slate-600 rounded-full"></div>
                         <span class="text-[10px] font-black text-slate-500 uppercase tracking-[0.3em]">${dish.checks.length} Total Logs</span>
                    </div>
                </div>
                <div class="px-6 py-4 rounded-[2rem] bg-slate-900 border border-slate-800 flex flex-col items-center min-w-[100px]">
                    <span class="text-3xl font-black ${scoreColor} font-mono">${avgScore}</span>
