                <div class="space-y-4">
                     <p class="text-[10px] font-black text-yellow-500/80 uppercase tracking-[0.3em] pl-2 border-l-2 border-yellow-500/30">Recurring Improvement Areas</p>
                     ${topIssues.length > 0 ? 
