function renderAuditDishLibrary() {
    DOMElements.auditResultsContainer.innerHTML = '';

    // 1. Group ALL history by Normalized Name (Independent of current Menu)
    const dishStats = {};
    state.allHistoricalChecks.forEach(check => {
        const key = normalizeName(check.dishName);
        if (!dishStats[key]) {
            dishStats[key] = { 
                name: check.dishName, // Keep the most recent name found
                checks: [], 
                scores: [] 
            };
        }
        // Update name to the most recent one if possible to avoid old naming conventions
        if (check.timestamp && (!dishStats[key].lastTs || check.timestamp > dishStats[key].lastTs)) {
             dishStats[key].name = check.dishName;
             dishStats[key].lastTs = check.timestamp;
        }

        dishStats[key].checks.push(check);
        if (check.aiCheckResult && typeof check.aiCheckResult.score === 'number') {
            dishStats[key].scores.push(check.aiCheckResult.score);
        }
    });

    const libraryList = Object.values(dishStats);

    if (libraryList.length === 0) {
        DOMElements.auditResultsContainer.innerHTML = `<div class="text-center py-20 border-2 border-dashed border-slate-800 rounded-[3rem]"><p class="text-[10px] font-black text-slate-600 uppercase tracking-[0.4em]">Knowledge Base Empty</p></div>`;
        return;
    }

    // 2. Sorting Logic: Priority to those with MORE data, then by Score
    libraryList.sort((a, b) => b.checks.length - a.checks.length);

    // 3. Render Intelligence Cards
    libraryList.forEach(dish => {
        // --- STATISTICS ENGINE ---
        const total = dish.scores.length;
        const sum = dish.scores.reduce((a, b) => a + b, 0);
        const avgScore = total ? (sum / total).toFixed(1) : '0.0';

        // Standard Deviation for Consistency
        const mean = total ? sum / total : 0;
        const variance = total ? dish.scores.reduce((a, b) => a + Math.pow(b - mean, 2), 0) / total : 0;
        const stdDev = Math.sqrt(variance);

        // Reliability Tier Logic
        let tier = 'C';
        let tierColor = 'text-red-500';
        let tierBg = 'bg-red-500/10 border-red-500/20';

        if (mean >= 9 && stdDev < 1.0) { tier = 'S'; tierColor = 'text-purple-400'; tierBg = 'bg-purple-500/10 border-purple-500/20'; }
        else if (mean >= 8 && stdDev < 2.0) { tier = 'A'; tierColor = 'text-emerald-400'; tierBg = 'bg-emerald-500/10 border-emerald-500/20'; }
        else if (mean >= 6.5) { tier = 'B'; tierColor = 'text-yellow-400'; tierBg = 'bg-yellow-500/10 border-yellow-500/20'; }

        // Trend Analysis
        const sortedChecks = dish.checks.sort((a,b) => (a.timestamp || '').localeCompare(b.timestamp || ''));
        const lastCheckDate = sortedChecks[sortedChecks.length - 1]?.timestamp ? new Date(sortedChecks[sortedChecks.length - 1].timestamp).toLocaleDateString() : 'N/A';

        // Semantic Extraction
        const allImprovements = sortedChecks.flatMap(c => c.aiCheckResult?.improvements || []);
        const keywords = ['Salt', 'Temperature', 'Texture', 'Portion', 'Seasoning', 'Presentation', 'Sauce', 'Cooked'];
        const failureModes = keywords.map(k => {
            const count = allImprovements.filter(i => i && i.toLowerCase().includes(k.toLowerCase())).length;
            return { keyword: k, count };
        }).filter(k => k.count > 0).sort((a,b) => b.count - a.count).slice(0, 3);

        const card = document.createElement('div');
        card.className = "bg-slate-800/60 rounded-[2.5rem] p-8 border border-slate-700/50 backdrop-blur-md hover:bg-slate-800/80 transition-all group overflow-hidden relative";

        card.innerHTML = `
            <div class="absolute top-0 right-0 p-8 opacity-10 pointer-events-none">
                <span class="text-[8rem] font-black ${tierColor} leading-none">${tier}</span>
            </div>

            <div class="flex flex-col gap-6 relative z-10">
                <!-- Header -->
                <div class="border-b border-white/5 pb-6">
                    <div class="flex justify-between items-start">
                        <div>
                            <h3 class="text-2xl font-black text-white italic uppercase tracking-tight max-w-[80%]">${dish.name}</h3>
                            <div class="flex items-center gap-3 mt-3">
                                <div class="px-3 py-1 rounded-lg ${tierBg} border text-[9px] font-black ${tierColor} uppercase tracking-widest">Tier ${tier} Reliability</div>
                                <span class="text-[9px] font-black text-slate-500 uppercase tracking-widest px-2 border-l border-slate-700">Last Audit: ${lastCheckDate}</span>
                            </div>
                        </div>
                        <div class="text-right">
                             <div class="text-4xl font-black text-white font-mono tracking-tighter">${avgScore}</div>
                             <div class="text-[9px] font-black text-slate-500 uppercase tracking-widest mt-1">Global Avg</div>
                        </div>
                    </div>
                </div>

                <!-- Intelligence Grid -->
                <div class="grid grid-cols-1 sm:grid-cols-2 gap-6">
                    <!-- Consistency Metrics -->
                    <div class="bg-slate-900/50 p-5 rounded-3xl border border-slate-800">
                        <p class="text-[9px] font-black text-indigo-400 uppercase tracking-[0.3em] mb-4">Stability Vector</p>
                        <div class="flex justify-between items-end">
                            <div>
                                <span class="text-2xl font-bold text-white">${total}</span>
                                <span class="text-[10px] text-slate-500 uppercase font-bold ml-1">Total Logs</span>
                            </div>
                            <div class="text-right">
                                <span class="text-xl font-bold text-slate-300">${stdDev.toFixed(2)}</span>
                                <span class="text-[10px] text-slate-500 uppercase font-bold ml-1">Deviation</span>
                            </div>
                        </div>
                        <div class="w-full bg-slate-800 h-1.5 mt-4 rounded-full overflow-hidden">
                            <div class="h-full bg-indigo-500" style="width: ${Math.min(100, (1 - stdDev/5)*100)}%"></div>
                        </div>
                        <p class="text-[8px] text-slate-600 mt-2 uppercase font-black text-right tracking-wider">Consistency Rating</p>
                    </div>

                    <!-- Semantic Failure Modes -->
                    <div class="bg-slate-900/50 p-5 rounded-3xl border border-slate-800">
                        <p class="text-[9px] font-black text-pink-400 uppercase tracking-[0.3em] mb-4">Critical Drift Factors</p>
                        ${failureModes.length > 0 ? 
                           `<div class="space-y-2">
                                ${failureModes.map(m => `
                                    <div class="flex justify-between items-center">
                                        <span class="text-[10px] font-bold text-slate-300 uppercase tracking-wider">${m.keyword}</span>
                                        <div class="flex items-center gap-1">
                                            <div class="h-1.5 w-16 bg-slate-800 rounded-full overflow-hidden"><div class="h-full bg-pink-500" style="width: ${(m.count/total)*100}%"></div></div>
                                            <span class="text-[9px] font-mono text-pink-400 w-4 text-right">${m.count}</span>
                                        </div>
                                    </div>
                                `).join('')}
                           </div>` 
                           : `<p class="text-[10px] text-slate-500 italic">No dominant failure patterns detected in text logs.</p>`
                        }
                    </div>
                </div>

                <!-- Recent Feedback Snippet -->
                <div class="mt-2">
                    <p class="text-[9px] font-black text-slate-500 uppercase tracking-[0.3em] mb-2">Latest Neural Comment</p>
                    <div class="p-4 bg-slate-950/30 rounded-2xl border border-slate-800/50">
                        <p class="text-[11px] text-slate-400 italic leading-relaxed line-clamp-2">"${sortedChecks[sortedChecks.length-1]?.aiCheckResult?.overall_comment || 'No textual data.'}"</p>
                    </div>
                </div>
            </div>
        `;

        DOMElements.auditResultsContainer.appendChild(card);
    });
}

