function renderAuditDishLibrary() {
    DOMElements.auditResultsContainer.innerHTML = '';

    // Clear old charts to prevent memory leaks
    if (window.auditCharts) {
        window.auditCharts.forEach(c => c.destroy());
        window.auditCharts = [];
    }

    // 1. Group ALL history by Normalized Name
    const dishStats = {};
    state.allHistoricalChecks.forEach(check => {
        const key = normalizeName(check.dishName);
        if (!dishStats[key]) {
            dishStats[key] = { 
                name: check.dishName, 
                checks: [], 
                scores: [] 
            };
        }
        if (check.timestamp && (!dishStats[key].lastTs || check.timestamp > dishStats[key].lastTs)) {
             dishStats[key].name = check.dishName;
             dishStats[key].lastTs = check.timestamp;
        }
        dishStats[key].checks.push(check);
        if (check.aiCheckResult && typeof check.aiCheckResult.score === 'number') {
            dishStats[key].scores.push(check.aiCheckResult.score);
        }
    });

    const libraryList = Object.values(dishStats).sort((a, b) => b.checks.length - a.checks.length);

    if (libraryList.length === 0) {
        DOMElements.auditResultsContainer.innerHTML = `<div class="text-center py-20 border-2 border-dashed border-slate-800 rounded-[3rem]"><p class="text-[10px] font-black text-slate-600 uppercase tracking-[0.4em]">Knowledge Base Empty</p></div>`;
        return;
    }

    // Helper to count frequency of feedback items
    const getTopicFrequency = (items) => {
        const counts = {};
        items.forEach(i => {
            if(!i) return;
            const k = i.trim().toLowerCase().replace(/[.,!]/g, ''); 
            if (!counts[k]) counts[k] = { text: i.trim(), count: 0 };
            counts[k].count++;
        });
        return Object.values(counts).sort((a,b) => b.count - a.count).slice(0, 5);
    };

    libraryList.forEach((dish, index) => {
        const total = dish.scores.length;
        const sum = dish.scores.reduce((a, b) => a + b, 0);
        const avgScore = total ? (sum / total).toFixed(1) : '0.0';

        // --- RELIABILITY TIER ---
        const mean = total ? sum / total : 0;
        const variance = total ? dish.scores.reduce((a, b) => a + Math.pow(b - mean, 2), 0) / total : 0;
        const stdDev = Math.sqrt(variance);
        let tier = 'C', tierColor = 'text-red-500', tierBg = 'bg-red-500/10 border-red-500/20';
        if (mean >= 9 && stdDev < 1.0) { tier = 'S'; tierColor = 'text-purple-400'; tierBg = 'bg-purple-500/10 border-purple-500/20'; }
        else if (mean >= 8 && stdDev < 2.0) { tier = 'A'; tierColor = 'text-emerald-400'; tierBg = 'bg-emerald-500/10 border-emerald-500/20'; }
        else if (mean >= 6.5) { tier = 'B'; tierColor = 'text-yellow-400'; tierBg = 'bg-yellow-500/10 border-yellow-500/20'; }

        // --- SORTED CHECKS & GRAPH DATA ---
        const sortedChecks = dish.checks.sort((a,b) => (a.timestamp || '').localeCompare(b.timestamp || ''));
        const labels = sortedChecks.map(c => c.timestamp ? new Date(c.timestamp).toLocaleDateString(undefined, {month:'numeric', day:'numeric'}) : '-');
        const dataPoints = sortedChecks.map(c => c.aiCheckResult?.score || 0);

        // --- WHY GOOD VS WHY BAD LOGIC ---
        const goodChecks = sortedChecks.filter(c => c.aiCheckResult?.score >= 8);
        const badChecks = sortedChecks.filter(c => c.aiCheckResult?.score <= 6);

        const goodReasons = getTopicFrequency(goodChecks.flatMap(c => c.aiCheckResult?.positives || []));
        const badReasons = getTopicFrequency(badChecks.flatMap(c => c.aiCheckResult?.improvements || []));

        // --- GLOBAL AGGREGATIONS ---
        const allPositives = getTopicFrequency(sortedChecks.flatMap(c => c.aiCheckResult?.positives || []));
        const allImprovements = getTopicFrequency(sortedChecks.flatMap(c => c.aiCheckResult?.improvements || []));

        const card = document.createElement('div');
        card.className = "bg-slate-800/60 rounded-[2.5rem] p-8 border border-slate-700/50 backdrop-blur-md hover:bg-slate-800/80 transition-all relative overflow-hidden";
        const canvasId = `chart-${index}`;

        card.innerHTML = `
            <div class="flex flex-col gap-8 relative z-10">
                <!-- Header -->
                <div class="border-b border-white/5 pb-6 flex justify-between items-start">
                    <div>
                        <h3 class="text-2xl font-black text-white italic uppercase tracking-tight">${dish.name}</h3>
                        <div class="flex items-center gap-3 mt-3">
                            <div class="px-3 py-1 rounded-lg ${tierBg} border text-[9px] font-black ${tierColor} uppercase tracking-widest">Tier ${tier} Reliability</div>
                            <span class="text-[9px] font-black text-slate-500 uppercase tracking-widest px-2 border-l border-slate-700">${total} Audits</span>
                        </div>
                    </div>
                    <div class="text-right">
                         <div class="text-4xl font-black text-white font-mono tracking-tighter">${avgScore}</div>
                         <div class="text-[9px] font-black text-slate-500 uppercase tracking-widest mt-1">Avg Score</div>
                    </div>
                </div>

                <!-- Trend Graph -->
                <div class="h-40 w-full relative">
                    <canvas id="${canvasId}"></canvas>
                </div>

                <!-- Deep Dive Analysis Grid -->
                <div class="grid grid-cols-1 lg:grid-cols-2 gap-8 border-t border-white/5 pt-8">

                    <!-- LEFT COLUMN: ANATOMY OF SUCCESS (WHY GOOD) -->
                    <div class="bg-slate-900/50 p-6 rounded-3xl border border-slate-800 space-y-6">
                        <div class="flex items-center gap-3 mb-2">
                             <div class="bg-green-500/20 p-2 rounded-xl text-green-400"><svg xmlns="http://www.w3.org/2000/svg" class="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="3" d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg></div>
                             <p class="text-[10px] font-black text-green-400 uppercase tracking-[0.3em]">Anatomy of Success (>8.0)</p>
                        </div>
                        ${goodReasons.length > 0 ? 
                            `<ul class="space-y-3">
                                ${goodReasons.map(r => `<li class="flex justify-between text-xs font-bold text-slate-300"><span>${r.text}</span><span class="text-green-500/70">x${r.count}</span></li>`).join('')}
                            </ul>` : 
                            `<p class="text-[10px] text-slate-600 italic">No meaningful patterns in high scores yet.</p>`
                        }
                    </div>

                    <!-- RIGHT COLUMN: FAILURE PATTERNS (WHY BAD) -->
                    <div class="bg-slate-900/50 p-6 rounded-3xl border border-slate-800 space-y-6">
                         <div class="flex items-center gap-3 mb-2">
                             <div class="bg-red-500/20 p-2 rounded-xl text-red-400"><svg xmlns="http://www.w3.org/2000/svg" class="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="3" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"></path></svg></div>
                             <p class="text-[10px] font-black text-red-400 uppercase tracking-[0.3em]">Failure Patterns (<6.0)</p>
                        </div>
                        ${badReasons.length > 0 ? 
                            `<ul class="space-y-3">
                                ${badReasons.map(r => `<li class="flex justify-between text-xs font-bold text-slate-300"><span>${r.text}</span><span class="text-red-500/70">x${r.count}</span></li>`).join('')}
                            </ul>` : 
                            `<p class="text-[10px] text-slate-600 italic">No recurring severe failure modes detected.</p>`
                        }
                    </div>
                </div>

                <!-- Aggregated Feedback Summary -->
                <div class="grid grid-cols-1 md:grid-cols-2 gap-8 border-t border-white/5 pt-8">
                     <div>
                        <p class="text-[9px] font-black text-slate-500 uppercase tracking-widest mb-4">Most Common Strengths</p>
                        <div class="flex flex-wrap gap-2">
                            ${allPositives.map(p => `<span class="px-3 py-1 bg-green-900/20 border border-green-500/20 rounded-lg text-[10px] font-bold text-green-300 uppercase">${p.text}</span>`).join('') || '<span class="text-slate-600 text-[10px]">N/A</span>'}
                        </div>
                     </div>
                     <div>
                        <p class="text-[9px] font-black text-slate-500 uppercase tracking-widest mb-4">Most Common Improvements</p>
                        <div class="flex flex-wrap gap-2">
                            ${allImprovements.map(p => `<span class="px-3 py-1 bg-yellow-900/20 border border-yellow-500/20 rounded-lg text-[10px] font-bold text-yellow-300 uppercase">${p.text}</span>`).join('') || '<span class="text-slate-600 text-[10px]">N/A</span>'}
                        </div>
                     </div>
                </div>
            </div>
        `;
        DOMElements.auditResultsContainer.appendChild(card);

        // --- RENDER CHART.JS ---
        if (typeof Chart !== 'undefined') {
            const ctx = document.getElementById(canvasId).getContext('2d');
            const chart = new Chart(ctx, {
                type: 'line',
                data: {
                    labels: labels,
                    datasets: [{
                        label: 'Quality Score',
                        data: dataPoints,
                        borderColor: '#6366f1',
                        backgroundColor: (context) => {
                            const bg = context.chart.ctx.createLinearGradient(0, 0, 0, 200);
                            bg.addColorStop(0, 'rgba(99, 102, 241, 0.5)');
                            bg.addColorStop(1, 'rgba(99, 102, 241, 0)');
                            return bg;
                        },
                        borderWidth: 2,
                        pointBackgroundColor: '#1e293b',
                        pointBorderColor: '#818cf8',
                        pointRadius: 4,
                        fill: true,
                        tension: 0.4
                    }]
                },
                options: {
                    responsive: true,
                    maintainAspectRatio: false,
                    plugins: { legend: { display: false } },
                    scales: {
                        y: {
                            min: 0, max: 10,
                            grid: { color: 'rgba(148, 163, 184, 0.1)' },
                            ticks: { color: '#64748b', font: { size: 10, weight: 'bold' } }
                        },
                        x: {
                            grid: { display: false },
                            ticks: { color: '#64748b', font: { size: 9, weight: 'bold' }, maxTicksLimit: 6 }
                        }
                    }
                }
            });
            window.auditCharts.push(chart);
        }
    });
}

