                         <div>
                            <p class="text-[9px] font-black text-slate-500 uppercase tracking-widest mb-4">Most Common Improvements</p>
                            <div class="flex flex-wrap gap-2">
                                ${allImprovements.map(p => `<span class="px-3 py-1 bg-yellow-900/20 border border-yellow-500/20 rounded-lg text-[10px] font-bold text-yellow-300 uppercase">${p.text}</span>`).join('') || '<span class="text-slate-600 text-[10px]">N/A</span>'}
                            </div>
